local config = {
  ui_story_5082_50820100_X1_dialog_content = "Reinhardt!",
  ui_story_5082_50820100_X2_dialog_content = "Huh, so the reckoning souls finally fizzled out, did it? Reinhardt, just what kind of \"evil dragon\" have you become?",
  ui_story_5082_50820100_X3_dialog_content = "Break free from those chains, Reinhardt... just as we once did.",
  ui_story_5082_50820100_1_dialog_content = "<color=#e8d9bb>On a rare sunny day, you decide to lay in the grass outside the temporary headquarters and let your mind wander...</color>",
  ui_story_5082_50820100_2_dialog_content = "Want to hear the latest reports?!",
  ui_story_5082_50820100_3_dialog_content = "Ahhh! Ph-Philyshy! Where did you come from?!",
  ui_story_5082_50820100_4_dialog_content = "Meow? That's not the point.",
  ui_story_5082_50820100_5_dialog_content = "Officer Vivian gave me a job to do, remember? I'm supposed to write you a Dark Zone Distress Guide.",
  ui_story_5082_50820100_6_dialog_content = "You finished it? Wow, I didn't expect you to finish this task so quickly.",
  ui_story_5082_50820100_7_dialog_content = "Right?! I spent a whole week thinking about it, but I'm finally done! That's why—",
  ui_story_5082_50820100_8_dialog_content = "I asked Commander Barton to take two days off to do some special combat training with you!",
  ui_story_5082_50820100_9_dialog_content = "Special combat training... with Barton? What happened to the Dark Zone Distress Guide?",
  ui_story_5082_50820100_10_dialog_content = "Well, I thought long and hard about it for days and realized Officer Vivian was testing me—combat isn't something you can learn from a book, meow!",
  ui_story_5082_50820100_11_dialog_content = "You're just pushing your work onto someone else, aren't you?!",
  ui_story_5082_50820100_12_dialog_content = "If I go through any sort of training with Barton right now, I'll be dead before I even reach the Dark Zone.",
  ui_story_5082_50820100_13_dialog_content = "Which is precisely why you need training, meow!",
  ui_story_5082_50820100_14_dialog_content = "Besides, it also gives me a chance to assess your combat proficiency—",
  ui_story_5082_50820100_15_dialog_content = "I'll make sure you make lots of meaningful progress, which also means I'll be doing my job, meow!",
  ui_story_5082_50820100_16_dialog_content = "Coming up with such a brilliant idea wasn't easy, you know! But writing up reports should be much easier now, which means I can take it easy too!",
  ui_story_5082_50820100_17_dialog_content = "Is there no limit to your laziness, Philyshy?!",
  ui_story_5082_50820100_18_dialog_content = "Nope, and now that you know the plan, there's no use debating it! Now come with me back to Illumina!",
  ui_story_5082_50820100_19_dialog_content = "If we hurry, I might even have time for a little catnap... Yaaawn!",
  ui_story_5082_50820100_20_dialog_content = "If slacking off was a sport, she'd be a professional... H-Hey! Don't you dare fall asleep!",
  ui_story_5082_50820100_21_dialog_content = "At least tell me what the training is about—",
  ui_story_5082_50820100_22_dialog_content = "<color=#e8d9bb>Gannon City Training Grounds</color>",
  ui_story_5082_50820100_23_dialog_content = "She actually brought me to the training grounds without falling asleep...",
  ui_story_5082_50820100_24_dialog_content = "I'm sorry Philyshy, I was wrong to doubt you. I didn't realize you could be such a hard worker too.",
  ui_story_5082_50820100_25_dialog_content = "Apology and compliment accepted! There's a reason I brought you straight here, you know!",
  ui_story_5082_50820100_26_dialog_content = "A reason?",
  ui_story_5082_50820100_27_dialog_content = "Huff... Huff...",
  ui_story_5082_50820100_28_dialog_content = "Did you forget to eat or something? The Eclipsites will make a meal out of you if you keep running so slowly!",
  ui_story_5082_50820100_29_dialog_content = "Dig deep and give me fifty more kilometers! And do it faster this time!",
  ui_story_5082_50820100_30_dialog_content = "Yes, sir!",
  ui_story_5082_50820100_31_dialog_content = "It's Barton's team. It looks like they're in the middle of training.",
  ui_story_5082_50820100_32_dialog_content = "Perfect timing! Now go and join them!",
  ui_story_5082_50820100_33_dialog_content = "Wait... Me?",
  ui_story_5082_50820100_34_dialog_content = "Yes, you!",
  ui_story_5082_50820100_35_dialog_content = "This is Commander Barton's new training camp, where he whips our inexperienced recruits into shape! It's the perfect place for you, PlayerName!",
  ui_story_5082_50820100_36_dialog_content = "So do your best to keep up with their training program, okay? I'll just be over here sleeping... I mean observing!",
  ui_story_5082_50820100_37_dialog_content = "... I take back everything I just said!",
  ui_story_5082_50820100_38_dialog_content = "Haha, I like your spirit, kid!",
  ui_story_5082_50820100_39_dialog_content = "But if you want to stand a chance against our enemies in the Dark Zone, our training here won't be nearly enough.",
  ui_story_5082_50820100_40_dialog_content = "After all your battles, I'm sure it's perfectly clear to you: losing out there means death.",
  ui_story_5082_50820100_41_dialog_content = "That's why I'm gonna train you to death before the Dark Zone beats me to it! Understood?",
  ui_story_5082_50820100_42_dialog_content = "Y-Yes, sir!",
  ui_story_5082_50820100_43_dialog_content = "(Barton's presence is so overwhelming... I didn't even think of saying no just now...)",
  ui_story_5082_50820100_44_dialog_content = "Good to hear.",
  ui_story_5082_50820100_45_dialog_content = "Let's see, how can I turn a wimpy little Caelestite into a lean, mean, fighting machine in the shortest amount of time possible?",
  ui_story_5082_50820100_46_dialog_content = "Um, why can't I just do the same training as everyone else?",
  ui_story_5082_50820100_47_dialog_content = "Hmph, take it up with those old fools on the Committee. They're the ones insisting that we use their new \"scientific\" training methods.",
  ui_story_5082_50820100_48_dialog_content = "They set up all kinds of benchmarks and templates, like they're trying to dictate every second of training!",
  ui_story_5082_50820100_49_dialog_content = "But isn't that sort of the point?",
  ui_story_5082_50820100_50_dialog_content = "Maybe for just physical training, sure.",
  ui_story_5082_50820100_51_dialog_content = "But I train real soldiers here, not a bunch of mass-produced puppets! My job is to prepare them for fighting enemies on the front lines!",
  ui_story_5082_50820100_52_dialog_content = "Rigid training methods like this will never produce truly outstanding soldiers. That's what I think anyway.",
  ui_story_5082_50820100_53_dialog_content = "In the past, the Grand Marshal and I would always engage in live combat training with others, even if we weren't on the front lines.",
  ui_story_5082_50820100_54_dialog_content = "Regardless of rank or position, we would all go into the same unfamiliar territory and test our strength against each other.",
  ui_story_5082_50820100_55_dialog_content = "Aside from a scarce number of ammo and supply drops, all we had to rely on were our bodies and our wits.",
  ui_story_5082_50820100_56_dialog_content = "Under those circumstances, the high and mighty weren't necessarily ahead of the competition. Even the least remarkable participants had a shot at winning.",
  ui_story_5082_50820100_57_dialog_content = "Combat, strategy, defeat, and victory.",
  ui_story_5082_50820100_58_dialog_content = "The pain of getting stomped into the mud by the strong, and the resolve to win by any means necessary.",
  ui_story_5082_50820100_59_dialog_content = "Only by experiencing these things first-hand can a soldier be molded into something truly powerful.",
  ui_story_5082_50820100_60_dialog_content = "A realistic combat scenario where anything can happen at any time is the best way to sharpen one's skills!",
  ui_story_5082_50820100_61_dialog_content = "Well said, Barton.",
  ui_story_5082_50820100_62_dialog_content = "Reinhardt! You're here too?",
  ui_story_5082_50820100_63_dialog_content = "I came to see the progress of our soldiers before we entered the Dark Zone. Looks like I showed up at just the right time.",
  ui_story_5082_50820100_64_dialog_content = "We haven't gone head-to-head in a while, Barton. Care to see which of us has improved the most since last time?",
  ui_story_5082_50820100_65_dialog_content = "That's all I could ask for!",
  ui_story_5082_50820100_66_dialog_content = "Wait, you two aren't gonna...",
  ui_story_5082_50820100_67_dialog_content = "That's right! We're having a live-combat exercise, right here and now!",
  ui_story_5082_50820100_68_dialog_content = "No running away, got it, kid?!",
  ui_story_5082_50820100_69_dialog_content = "I-I would never! I'm not the type to give up before I even start!",
  ui_story_5082_50820100_70_dialog_content = "Good, then consider this a part of your special training, PlayerName. Naturally, your handler will also be participating.",
  ui_story_5082_50820100_71_dialog_content = "Isn't that right, Intel Chief Philyshy?",
  ui_story_5082_50820100_72_dialog_content = "Now that you mention it, I haven't heard her say anything in a while... Hey! When did you scurry off over there?!",
  ui_story_5082_50820100_73_dialog_content = "Sigh... If you say so, Grand Marshal.",
  ui_story_5082_50820100_74_dialog_content = "Philyshy has joined the battle!",
  ui_story_5082_50820100_75_dialog_content = "<color=#e8d9bb>Moments later</color>",
  ui_story_5082_50820100_76_dialog_content = "Good afternoon, everyone. Although it wasn't part of the original program—",
  ui_story_5082_50820100_77_dialog_content = "At the Grand Marshal's request, I've come to serve as the judge for this training exercise.",
  ui_story_5082_50820100_78_dialog_content = "The exercise, which will run for two days and two nights, will be comprised of four teams of two people each. Feel free to take a look at the list of participants.",
  ui_story_5082_50820100_79_dialog_content = "Team 1 is Reinhardt and Philyshy.",
  ui_story_5082_50820100_80_dialog_content = "Barton and I are on Team 2. The last two teams are made up of officers from the 2nd Legion...",
  ui_story_5082_50820100_81_dialog_content = "So, where exactly are we doing battle?",
  ui_story_5082_50820100_82_dialog_content = "That's simple enough to answer.",
  ui_story_5082_50820100_83_dialog_content = "<color=#e8d9bb>Shake, shake, shake—Roll—</color>",
  ui_story_5082_50820100_84_dialog_content = "He actually carries the dice for military simulation on him...?",
  ui_story_5082_50820100_85_dialog_content = "Ha! Looks like we're taking this little competition to that nearby Undercity.",
  ui_story_5082_50820100_86_dialog_content = "You're in luck, kid. That Undercity's been abandoned for ages, and I'm in the process of acquiring it for my training grounds.",
  ui_story_5082_50820100_87_dialog_content = "It's a huge area with tons of abandoned structures.",
  ui_story_5082_50820100_88_dialog_content = "The layout is perfect for launching surprise attacks—Though I'm sure our opponents are thinking the exact same thing.",
  ui_story_5082_50820100_89_dialog_content = "You seem awfully calm about this. Are you sure this isn't gonna be a problem?",
  ui_story_5082_50820100_90_dialog_content = "Eclipsites don't take these things into account when they attack. This level of uncertainty is just another part of the combat simulation; I suggest you get used to it.",
  ui_story_5082_50820100_91_dialog_content = "Wait... As the judge, shouldn't I be the one to designate the location?",
  ui_story_5082_50820100_92_dialog_content = "Hahahaha! Sorry, I got so excited that I ended up doing the Chief of Staff's job for her!",
  ui_story_5082_50820100_93_dialog_content = "...",
  ui_story_5082_50820100_94_dialog_content = "Just go with Barton's choice, Vivian.",
  ui_story_5082_50820100_95_dialog_content = "Very well then. You each have thirty minutes to prepare before entering the contest site. When the bell rings, the match will officially begin.",
  ui_story_5082_50820100_96_dialog_content = "This is a precious opportunity to gain valuable combat experience, so please treat it seriously and fight with all your strength.",
  ui_story_5082_50820100_97_dialog_content = "Understood!",
  ui_story_5082_50820100_98_dialog_content = "The nearby Undercity... We hardly have any information on it. Barton definitely knows how to pick his battles.",
  ui_story_5082_50820201_1_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5082_50820201_2_dialog_content = "Hahahaha, not bad! Let's see the Grand Marshal stop us now that her stronghold is in shambles!",
  ui_story_5082_50820201_3_dialog_content = "*cough*",
  ui_story_5082_50820201_4_dialog_content = "So much smoke and debris... Ugh... An explosion like that is sure to give away our position.",
  ui_story_5082_50820201_5_dialog_content = "Shouldn't we try to distance ourselves from this location?",
  ui_story_5082_50820201_6_dialog_content = "That's right. We can let the others play for the rest of the match.",
  ui_story_5082_50820201_7_dialog_content = "Let's split up and gather any food and resources we can find, PlayerName!",
  ui_story_5082_50820201_8_dialog_content = "Roger!",
  ui_story_5082_50820201_9_dialog_content = "I'll just go this way... Huh?",
  ui_story_5082_50820201_10_dialog_content = "It feels like someone's watching me...",
  ui_story_5082_50820201_11_dialog_content = "Sigh... I worked so hard on that stronghold too.",
  ui_story_5082_50820201_12_dialog_content = "You didn't have to blow it up like that, you know!",
  ui_story_5082_50820201_13_dialog_content = "(She's already back?!)",
  ui_story_5082_50820201_14_dialog_content = "(But it looks like Philyshy's alone...)",
  ui_story_5082_50820201_15_dialog_content = "Wait, Philyshy! Just hear me out!",
  ui_story_5082_50820201_16_dialog_content = "Barton's not too far from our location. If you attack me right now, he'll be here before you know it.",
  ui_story_5082_50820201_17_dialog_content = "Fighting both of us on your own isn't in your best interest.",
  ui_story_5082_50820201_18_dialog_content = "So why not retreat for now? If you do, I promise we won't attack your team for the next two hours.",
  ui_story_5082_50820201_19_dialog_content = "We'll even help you by taking down the other two teams! You'll have two whole hours to do whatever you want, even if it's nothing at all!",
  ui_story_5082_50820201_20_dialog_content = "Hmm, that does sound nice.",
  ui_story_5082_50820201_21_dialog_content = "Then—",
  ui_story_5082_50820201_22_dialog_content = "Unfortunately, I never let a mouse out of my sight once I've cornered it!",
  ui_story_5082_50820201_23_dialog_content = "Oh no... It's Yumi!",
  ui_story_5082_50820201_24_dialog_content = "It's too late now!",
  ui_story_5082_50820201_25_dialog_content = "(If I can't negotiate my way out of this... Then I just have to run!)",
  ui_story_5082_50820201_26_dialog_content = "Hold still, would ya?!",
  ui_story_5082_50820201_27_dialog_content = "I can't stand it when my prey keeps running around!",
  ui_story_5082_50820201_28_dialog_content = "PlayerName! Hang on, I'm almost there!",
  ui_story_5082_50820201_29_dialog_content = "Hmm? Was that...",
  ui_story_5082_50820201_30_dialog_content = "Look up, PlayerName!",
  ui_story_5082_50820201_31_dialog_content = "!!",
  ui_story_5082_50820201_32_dialog_content = "That's... It's Reinhardt! Now I'm really done for!",
  ui_story_5082_50820201_33_dialog_content = "I knew building a stronghold in such an obvious place was the right move.",
  ui_story_5082_50820201_34_dialog_content = "Sorry PlayerName, but it looks like your special training's getting cut short.",
  ui_story_5082_50820201_35_dialog_content = "Look out, kid! The Grand Marshal's gonna make mincemeat out of you if this keeps up!",
  ui_story_5082_50820201_36_dialog_content = "Hurry up and run!",
  ui_story_5082_50820201_37_dialog_content = "You can run as fast as you'd like, but—",
  ui_story_5082_50820201_38_dialog_content = "Run!",
  ui_story_5082_50820201_39_dialog_content = "Run!",
  ui_story_5082_50820201_40_dialog_content = "... Who's there?",
  ui_story_5082_50820201_41_dialog_content = "Don't let them steal your power—",
  ui_story_5082_50820201_42_dialog_content = "That voice...",
  ui_story_5082_50820201_43_dialog_content = "Run!!!",
  ui_story_5082_50820201_44_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5082_50820201_45_dialog_content = "...!",
  ui_story_5082_50820201_46_dialog_content = "Nothing's more unsightly than losing a battle because of your own indecision!",
  ui_story_5082_50820201_47_dialog_content = "Barton—Aah!",
  ui_story_5082_50820201_48_dialog_content = "PlayerName has been secured!",
  ui_story_5082_50820201_49_dialog_content = "\"Secured\"? What am I, a package?!",
  ui_story_5082_50820201_50_dialog_content = "Is this... A mine cart? Where did this come from?!",
  ui_story_5082_50820201_51_dialog_content = "Here's another valuable lesson for you, kid: in battle, there's no such thing as a useless object!",
  ui_story_5082_50820201_52_dialog_content = "And to that, I'd like to add a few of my own words.",
  ui_story_5082_50820201_53_dialog_content = "In battle, there's no such thing as a perfect solution to every problem.",
  ui_story_5082_50820201_54_dialog_content = "Reinhardt's catching up!",
  ui_story_5082_50820201_55_dialog_content = "Even if her heart's not in it, I guess she's still the Grand Marshal.",
  ui_story_5082_50820201_56_dialog_content = "Some old wounds flared up just now, that's all. Trust me, you won't get another chance like that again.",
  ui_story_5082_50820201_57_dialog_content = "Tch! Hang on tight, PlayerName!",
  ui_story_5082_50820201_58_dialog_content = "The Barton Express is going full speed ahead!",
  ui_story_5082_50820201_59_dialog_content = "Ahhhhh—",
  ui_story_5082_50820201_60_dialog_content = "If you're gonna treat me like cargo, at least handle me with care!!!",
  ui_story_5082_50820201_61_dialog_content = "Hahahaha!",
  ui_story_5082_50820201_62_dialog_content = "W-Wait, look over there! It's a dead end! We're gonna crash—!",
  ui_story_5082_50820201_63_dialog_content = "Then we'll blast our way through!",
  ui_story_5082_50820201_64_dialog_content = "What?!",
  ui_story_5082_50820201_65_dialog_content = "No time to explain! Watch your head!",
  ui_story_5082_50820201_66_dialog_content = "Wait—",
  ui_story_5082_50820201_67_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5082_50820201_68_dialog_content = "<color=#e8d9bb>Ping! Bam! Clang, clang, clang!</color>",
  ui_story_5082_50820201_69_dialog_content = "Urgh...",
  ui_story_5082_50820201_70_dialog_content = "We finally stopped... I thought I was dead for sure...",
  ui_story_5082_50820201_71_dialog_content = "What's there to be afraid of? I saved you from the Grand Marshal, didn't I?",
  ui_story_5082_50820201_72_dialog_content = "No, that's not the point... Hey Barton?",
  ui_story_5082_50820201_73_dialog_content = "Yeah?",
  ui_story_5082_50820201_74_dialog_content = "You really shouldn't be allowed to drive.",
  ui_story_5082_50820201_75_dialog_content = "?",
  ui_story_5082_50820201_76_dialog_content = "Anyway, what is this place?",
  ui_story_5082_50820201_77_dialog_content = "We were running for so long that I lost my sense of direction. Maybe I should use my powers to sense our surroundings.",
  ui_story_5082_50820201_78_dialog_content = "Before you do that, try taking in your surroundings first.",
  ui_story_5082_50820201_79_dialog_content = "My surroundings?",
  ui_story_5082_50820201_80_dialog_content = "Wow, look at all these crates! Could they be...?!",
  ui_story_5082_50820201_81_dialog_content = "They are! Supply crates!",
  ui_story_5082_50820201_82_dialog_content = "You didn't think I was just taking you on a wild ride, did you?",
  ui_story_5082_50820201_83_dialog_content = "In battle, no single action is completely independent from the rest of the situation.",
  ui_story_5082_50820201_84_dialog_content = "Being able to take in everything in your field of vision will bring you one step closer to victory.",
  ui_story_5082_50820201_85_dialog_content = "The first day of the competition is nearly over. Taking control of these supplies will give us one of the greatest advantages possible.",
  ui_story_5082_50820201_86_dialog_content = "Unfortunately, that great advantage also makes you a prime target for everyone else.",
  ui_story_5082_50820201_87_dialog_content = "It's no different than having a spear pointing at your head at all times.",
  ui_story_5082_50820201_88_dialog_content = "Barton!",
  ui_story_5082_50820201_89_dialog_content = "Relax, kid. We haven't lost yet.",
  ui_story_5082_50820201_90_dialog_content = "Come now, Grand Marshal. Even schoolkids know that whoever has the best snacks will always be the target of jealousy.",
  ui_story_5082_50820201_91_dialog_content = "I found these supplies first, so there's no way I'm handing them over so easily.",
  ui_story_5082_50820201_92_dialog_content = "PlayerName's holding a detonator in his hands. One push of a button, and the low-grade explosives I've scattered among the supplies will go off, turning everything to ashes.",
  ui_story_5082_50820201_93_dialog_content = "(Huh? Detonator?)",
  ui_story_5082_50820201_94_dialog_content = "You should know exactly what it means for a person to destroy their own supplies in battle.",
  ui_story_5082_50820201_95_dialog_content = "This exercise runs for two entire days. As Grand Marshal, are you seriously willing to let your subordinates fight without food in their bellies?",
  ui_story_5082_50820201_96_dialog_content = "Hahaha, I almost forgot what it's like to face you in combat.",
  ui_story_5082_50820201_97_dialog_content = "But even if it means going hungry—",
  ui_story_5082_50820201_98_dialog_content = "(... Huh? What on earth is...)",
  ui_story_5082_50820201_99_dialog_content = "(It's already the second day of the training exercise. This situation... isn't going to end anytime soon.)",
  ui_story_5082_50820201_100_dialog_content = "(I'm the only one who found ammunition on the first day. No one else I ran into had any rations.)",
  ui_story_5082_50820201_101_dialog_content = "(I won't make it at this rate...)",
  ui_story_5082_50820201_102_dialog_content = "So you're the one who took the ammo, huh?",
  ui_story_5082_50820201_103_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5082_50820201_104_dialog_content = "Firing before discerning the other person's identity? That's not very nice.",
  ui_story_5082_50820201_105_dialog_content = "You're the one who snuck into my camp. You're not entitled to any pleasantries.",
  ui_story_5082_50820201_106_dialog_content = "Hahahaha! So let's work together then, Reinhardt!",
  ui_story_5082_50820201_107_dialog_content = "This is supposed to be a real combat exercise. Why should I agree to team up with an infiltrator like you?",
  ui_story_5082_50820201_108_dialog_content = "Well, for starters, I blocked your attack just now without much effort— And you weren't holding back, were you?",
  ui_story_5082_50820201_109_dialog_content = "There are other benefits to working with me as well. Rations, for example.",
  ui_story_5082_50820201_110_dialog_content = "There are still plenty of other strong fighters in this exercise. It's only a matter of time before a victor is decided.",
  ui_story_5082_50820201_111_dialog_content = "There's no denying that I need ammunition, and something tells me you don't want to fight on an empty stomach, do you?",
  ui_story_5082_50820201_112_dialog_content = "Tch...",
  ui_story_5082_50820201_113_dialog_content = "Deal.",
  ui_story_5082_50820201_114_dialog_content = "<color=#e8d9bb>Two Days Later</color>",
  ui_story_5082_50820201_115_dialog_content = "I didn't expect to take down another team so quickly. You're pretty good.",
  ui_story_5082_50820201_116_dialog_content = "Of course I am.",
  ui_story_5082_50820201_117_dialog_content = "Looks like we're done fighting for the day. You got to use my ammo, so hand over your rations and—",
  ui_story_5082_50820201_118_dialog_content = "<color=#e8d9bb>Whack!</color>",
  ui_story_5082_50820201_119_dialog_content = "Urgh...",
  ui_story_5082_50820201_120_dialog_content = "A sneak attack... I should've known.",
  ui_story_5082_50820201_121_dialog_content = "She's gone... along with all my ammo.",
  ui_story_5082_50820201_122_dialog_content = "Ugh... I can't believe I fell for it.",
  ui_story_5082_50820201_123_dialog_content = "I haven't eaten in two days, and that battle just now took a lot out of me. It's getting harder and harder to hold on.",
  ui_story_5082_50820201_124_dialog_content = "I'll have to rest here for the day and conserve what little energy I still have. When tomorrow comes, I'll...",
  ui_story_5082_50820201_125_dialog_content = "<color=#e8d9bb>Two More Days Later</color>",
  ui_story_5082_50820201_126_dialog_content = "(My head's spinning... And my body feels so heavy.)",
  ui_story_5082_50820201_127_dialog_content = "(But the battle's not over yet. I have to keep going...)",
  ui_story_5082_50820201_128_dialog_content = "(Instead of getting angry, I need to think about my next move—)",
  ui_story_5082_50820201_129_dialog_content = "Wow, you can still move?",
  ui_story_5082_50820201_130_dialog_content = "You have some nerve, showing yourself around me.",
  ui_story_5082_50820201_131_dialog_content = "Why's that? It's your own fault for not figuring out my motives sooner.",
  ui_story_5082_50820201_132_dialog_content = "At the end of the day, I guess even top students don't amount to much!",
  ui_story_5082_50820201_133_dialog_content = "Tell me, what hurts more right now? Your wounds or your hunger?",
  ui_story_5082_50820201_134_dialog_content = "Just shut up and take me out. That's why you're here, right?",
  ui_story_5082_50820201_135_dialog_content = "Oh, I see. You can barely stand right now, can't you? Poor thing.",
  ui_story_5082_50820201_136_dialog_content = "I said shut up!",
  ui_story_5082_50820201_137_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5082_50820201_138_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5082_50820201_139_dialog_content = "Dodge, PlayerName!",
  ui_story_5082_50820201_140_dialog_content = "Barton!",
  ui_story_5082_50820201_141_dialog_content = "What a ruckus... So the rations were here all along!",
  ui_story_5082_50820201_142_dialog_content = "See that? The Grand Marshal and Commander Barton are going all out... Do we really want to get in the way of that?",
  ui_story_5082_50820201_143_dialog_content = "...",
  ui_story_5082_50820201_144_dialog_content = "...!",
  ui_story_5082_50820201_145_dialog_content = "(Was that... my memory just now?)",
  ui_story_5082_50820201_146_dialog_content = "And here I thought you were spacing out... But if we take this fight seriously, let's see just how much you've improved, Grand Marshal!",
  ui_story_5082_50820301_1_dialog_content = "... Glad we decided against interfering. That attack just now would've killed us a hundred times over.",
  ui_story_5082_50820301_2_dialog_content = "They're on a completely different level, after all. You couldn't tell from watching Commander Barton when he fights Eclipsites...",
  ui_story_5082_50820301_3_dialog_content = "Grand Marshal Reinhardt had him on the ropes just now, but he doesn't have a scratch on him! What's his body made out of...?",
  ui_story_5082_50820301_4_dialog_content = "... Could those rumors be true? They say that Commander Barton owes his immense power to a series of special experiments.",
  ui_story_5082_50820301_5_dialog_content = "I also hear that some of our recent recruits, the ones closest to our scientists, have gone through the same program. Just how many of them are in Illumina...?",
  ui_story_5082_50820301_6_dialog_content = "You seem pretty interested in them.",
  ui_story_5082_50820301_7_dialog_content = "Who wouldn't be? If it's true, all it would take to join the special forces is a few procedures!",
  ui_story_5082_50820301_8_dialog_content = "But who knows what kind of crazy experiments they were subjected to—",
  ui_story_5082_50820301_9_dialog_content = "Well at least I haven't turned into an Eclipsite, right?",
  ui_story_5082_50820301_10_dialog_content = "C-C-Commander Barton!!!",
  ui_story_5082_50820301_11_dialog_content = "...",
  ui_story_5082_50820301_12_dialog_content = "Why so silent all of a sudden?",
  ui_story_5082_50820301_13_dialog_content = "There's no rule against speaking your mind in the 2nd Legion, or anywhere else in Illumina.",
  ui_story_5082_50820301_14_dialog_content = "If you have something to say to your commander, then say it.",
  ui_story_5082_50820301_15_dialog_content = "B-But you're different than the others, Commander Barton!",
  ui_story_5082_50820301_16_dialog_content = "Everyone says that Illumina was in serious danger back then, and that you only made that sacrifice in order to turn the tides of battle!",
  ui_story_5082_50820301_17_dialog_content = "But the others...",
  ui_story_5082_50820301_18_dialog_content = "Did they fight on the front lines?",
  ui_story_5082_50820301_19_dialog_content = "I, uh...",
  ui_story_5082_50820301_20_dialog_content = "I asked you a question, soldier! These \"others\" you keep talking about; did they fight Eclipsites on the front lines?!",
  ui_story_5082_50820301_21_dialog_content = "Yes, sir!",
  ui_story_5082_50820301_22_dialog_content = "Did they struggle through the same bitter training that you went through?!",
  ui_story_5082_50820301_23_dialog_content = "Yes, sir!",
  ui_story_5082_50820301_24_dialog_content = "Did they get to enjoy peaceful, carefree lives simply because they went through those experiments?",
  ui_story_5082_50820301_25_dialog_content = "... No, sir.",
  ui_story_5082_50820301_26_dialog_content = "Then they're still soldiers of Illumina, and your comrades-in-arms!",
  ui_story_5082_50820301_27_dialog_content = "The blood and sweat they shed are no different than yours!",
  ui_story_5082_50820301_28_dialog_content = "They've made sacrifices in ways you can't even imagine, all for the sake of Illumina's future.",
  ui_story_5082_50820301_29_dialog_content = "They're no different than me in any way. Looking down on them is the same as looking down on me!",
  ui_story_5082_50820301_30_dialog_content = "But if you have no intention of seeing me as some kind of monster, then never forget that they're still your allies.",
  ui_story_5082_50820301_31_dialog_content = "...",
  ui_story_5082_50820301_32_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5082_50820301_33_dialog_content = "<color=#e8d9bb>No one saw Barton's attack clearly. All they saw was a flash of silver.</color>",
  ui_story_5082_50820301_34_dialog_content = "<color=#e8d9bb>In the next moment, the soldiers' weapons split in two and fell to the ground.</color>",
  ui_story_5082_50820301_35_dialog_content = "Sorry, but you've been eliminated.",
  ui_story_5082_50820301_36_dialog_content = "Go home and think long and hard about what you learned here.",
  ui_story_5082_50820301_37_dialog_content = "Yes, sir...",
  ui_story_5082_50820301_38_dialog_content = "And as for you, PlayerName.",
  ui_story_5082_50820301_39_dialog_content = "Why the long face? They were talking about us modified soldiers, not you.",
  ui_story_5082_50820301_40_dialog_content = "It's because you accepted the Chord Link's modifications in order to protect all of us...",
  ui_story_5082_50820301_41_dialog_content = "You're still thinking way too much for someone so exhausted.",
  ui_story_5082_50820301_42_dialog_content = "Listen here, kid. I didn't agree to modification to protect you people; I did it to win.",
  ui_story_5082_50820301_43_dialog_content = "And the power I obtained afterward is my own. You saw my speed when I dodged the Grand Marshal's attack earlier, didn't you?",
  ui_story_5082_50820301_44_dialog_content = "It's still a little difficult to control, but all power comes with a price. It's perfectly reasonable, if you ask me.",
  ui_story_5082_50820301_45_dialog_content = "Besides, who's to say I won't be the one keeping the Grand Marshal on the ropes once I get the hang of this power? Hahaha!",
  ui_story_5082_50820301_46_dialog_content = "I'm glad it doesn't seem to affect you... But speaking of Reinhardt...",
  ui_story_5082_50820301_47_dialog_content = "Something seems off about her. She lost focus in the middle of the battle so many times today.",
  ui_story_5082_50820301_48_dialog_content = "It was the same just now too. We were only able to escape because she suddenly stopped attacking.",
  ui_story_5082_50820301_49_dialog_content = "You noticed it too, eh... Whenever the Grand Marshal takes to the battlefield, she has a tendency to be at the center of everything.",
  ui_story_5082_50820301_50_dialog_content = "Whether it's her allies or her enemies, she's able to dictate the flow of the fighting around her.",
  ui_story_5082_50820301_51_dialog_content = "But today's different. Even though she keeps salvaging the situation in the end, she's definitely not in control of it. In fact, it appears to be the other way around.",
  ui_story_5082_50820301_52_dialog_content = "That's not something an old wound \"flaring up\" could ever cause.",
  ui_story_5082_50820301_53_dialog_content = "...",
  ui_story_5082_50820301_54_dialog_content = "...",
  ui_story_5082_50820301_55_dialog_content = "Agh...",
  ui_story_5082_50820301_56_dialog_content = "What is it?",
  ui_story_5082_50820301_57_dialog_content = "I think I suddenly sensed something...",
  ui_story_5082_50820301_58_dialog_content = "In a place like this?",
  ui_story_5082_50820301_59_dialog_content = "I'll try to get a better reading!",
  ui_story_5082_50820301_60_option_content = "Psychic Scan!",
  ui_story_5082_50820301_61_dialog_content = "Where was it...?",
  ui_story_5082_50820301_62_dialog_content = "<color=#e8d9bb>Rumble—</color>",
  ui_story_5082_50820301_63_dialog_content = "The ground... Is it shaking?",
  ui_story_5082_50820301_64_dialog_content = "The presence I sensed just now... I didn't recognize it, but linking with it felt oddly familiar.",
  ui_story_5082_50820301_65_dialog_content = "... It's her.",
  ui_story_5082_50820301_66_dialog_content = "There it is!",
  ui_story_5082_50820301_67_dialog_content = "Who are you? And why are you here?",
  ui_story_5082_50820301_68_dialog_content = "It's that girl...",
  ui_story_5082_50820301_69_dialog_content = "A girl? Who are you talking about?",
  ui_story_5082_50820301_70_dialog_content = "The girl with a dragon behind her!",
  ui_story_5082_50820301_71_dialog_content = "What are you—",
  ui_story_5082_50820301_72_dialog_content = "Watch out, PlayerName!",
  ui_story_5082_50820301_73_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5082_50820302_1_dialog_content = "PlayerName! Are you alright?!",
  ui_story_5082_50820302_2_dialog_content = "*cough* I'm fine... Thanks, Barton.",
  ui_story_5082_50820302_3_dialog_content = "But what made this building collapse? There isn't any fighting nearby, as far as I can tell.",
  ui_story_5082_50820302_4_dialog_content = "Come take a look at this.",
  ui_story_5082_50820302_5_dialog_content = "... What an enormous space! Everything's busted beyond repair... What kind of battle could've taken place here?",
  ui_story_5082_50820302_6_dialog_content = "We were so focused on the training exercise that we never noticed it.",
  ui_story_5082_50820302_7_dialog_content = "But if a battle like this took place so close to Gannon City, there's no way we would've missed it.",
  ui_story_5082_50820302_8_dialog_content = "Or maybe this happened when it collapsed back then...?",
  ui_story_5082_50820302_9_dialog_content = "That's right, I sensed a strange presence just now!",
  ui_story_5082_50820302_10_dialog_content = "It kept saying things I couldn't understand. Maybe it has something to do with this place?",
  ui_story_5082_50820302_11_dialog_content = "I'll try sensing it again—",
  ui_story_5082_50820302_12_dialog_content = "Just a moment, please.",
  ui_story_5082_50820302_13_dialog_content = "... Vivian? What are you doing here?",
  ui_story_5082_50820302_14_dialog_content = "Don't tell me we were making too much noise? Hahaha! Don't worry, I've already taken care of the problem.",
  ui_story_5082_50820302_15_dialog_content = "But if you're all here, does that mean you're looking for a rematch, Grand Marshal?",
  ui_story_5082_50820302_16_dialog_content = "Maybe next time.",
  ui_story_5082_50820302_17_dialog_content = "Don't make things difficult for the Grand Marshal, Barton.",
  ui_story_5082_50820302_18_dialog_content = "I came to share an important notification from headquarters. I've already informed the Grand Marshal and Philyshy about it.",
  ui_story_5082_50820302_19_dialog_content = "What's the situation?",
  ui_story_5082_50820302_20_dialog_content = "Due to a lapse in record-keeping, we only just realized that this area is strictly off-limits.",
  ui_story_5082_50820302_21_dialog_content = "And considering the exacerbation of the Grand Marshal's old wounds, we feel that continuing the training exercise will result in further damage—",
  ui_story_5082_50820302_22_dialog_content = "Therefore, I regret to inform you that this training exercise is now over.",
  ui_story_5082_50820302_23_dialog_content = "But I just sensed...",
  ui_story_5082_50820302_24_dialog_content = "We will handle the rest of the matter, so please understand, PlayerName. It is a restricted area, after all.",
  ui_story_5082_50820302_25_dialog_content = "(Reinhardt looks so serious. Did something happen back in Gannon City...?)",
  ui_story_5082_50820302_26_dialog_content = "... Fine.",
  ui_story_5082_50820302_27_dialog_content = "Is it really over already? And I just got warmed up too!",
  ui_story_5082_50820302_28_dialog_content = "I've been bored out of my mind running my troops through the same exact exercises every day.",
  ui_story_5082_50820302_29_dialog_content = "This contest was such a nice change of pace. Pulling the plug like this leaves a bad taste in my mouth.",
  ui_story_5082_50820302_30_dialog_content = "I agree. Even though the exercise has to end, I'd hate to spoil everyone's fun.",
  ui_story_5082_50820302_31_dialog_content = "Since everyone's already here, why don't we have a bonfire celebration tonight instead?",
  ui_story_5082_50820302_32_dialog_content = "I can leave the preparations to you, right Barton?",
  ui_story_5082_50820302_33_dialog_content = "... Hey, you're the boss around here, aren't you? Of course I can handle it! I'll get my subordinates to start moving things right away!",
  ui_story_5082_50820302_34_dialog_content = "Then I'll go with—",
  ui_story_5082_50820302_35_dialog_content = "Oh no you don't! You're coming with me first!",
  ui_story_5082_50820302_36_dialog_content = "H-Hey! Don't just drag me away, Philyshy! And where have you been this whole time, for that matter?!",
  ui_story_5082_50820302_37_dialog_content = "Slacking off, naturally... But it looks like even I've been in the dark about this place, meow.",
  ui_story_5082_50820302_38_dialog_content = "I heard them talking just now.",
  ui_story_5082_50820302_39_dialog_content = "\"We aren't hiding anything from them. This just isn't the right time, is all.\" That's what I heard Grand Marshal Reinhardt and Officer Vivian say.",
  ui_story_5082_50820302_40_dialog_content = "Now hurry up and use your psychic powers, PlayerName! I wanna hear what they're chatting about now!",
  ui_story_5082_50820302_41_dialog_content = "That's not what my powers are for, Philyshy!",
  ui_story_5082_50820302_42_dialog_content = "Nyeh, you're such a party pooper. I'll just go do it myself then!",
  ui_story_5082_50820302_43_dialog_content = "And she's gone... There's no stopping her when she's curious about something, huh?",
  ui_story_5082_50820302_44_dialog_content = "(Still, I wonder what happened to Reinhardt...)",
  ui_story_5082_50820401_1_dialog_content = "<color=#e8d9bb>In the middle of the night, during the bonfire...</color>",
  ui_story_5082_50820401_2_dialog_content = "... Come.",
  ui_story_5082_50820401_3_dialog_content = "That presence... It's you again!",
  ui_story_5082_50820401_4_dialog_content = "You are the one who sensed me... Caelestite.",
  ui_story_5082_50820401_5_dialog_content = "You know me? Who are you? And why are you reaching out to me?",
  ui_story_5082_50820401_6_dialog_content = "Help me leave this place.",
  ui_story_5082_50820401_7_dialog_content = "!!!",
  ui_story_5082_50820401_8_dialog_content = "You're a Colossus?!",
  ui_story_5082_50820401_9_dialog_content = "They call me Spearhead.",
  ui_story_5082_50820401_10_dialog_content = "When did Illumina get their hands on a sentient Colossus?!",
  ui_story_5082_50820401_11_dialog_content = "Wait a minute... A sentient Colossus... Does that mean you have a Caelestite Navigator like me?",
  ui_story_5082_50820401_12_dialog_content = "&>!#%$^!#$",
  ui_story_5082_50820401_13_dialog_content = "Illumina! Their people cannot be trusted!",
  ui_story_5082_50820401_14_dialog_content = "They imprisoned me! Altered me! They wish to turn me into a weapon of war!",
  ui_story_5082_50820401_15_dialog_content = "I tried to escape so many times, only to be destroyed in my final attempt.",
  ui_story_5082_50820401_16_dialog_content = "It was that girl... the girl with a $^%%$ behind her!",
  ui_story_5082_50820401_17_dialog_content = "(A girl? And there's something behind her...?)",
  ui_story_5082_50820401_18_dialog_content = "^#!^#%$&&! ^&*tite... Come find me.",
  ui_story_5082_50820401_19_dialog_content = "Come find me.",
  ui_story_5082_50820401_20_dialog_content = "Where are you?",
  ui_story_5082_50820401_21_dialog_content = "Come find me. Help me leave—",
  ui_story_5082_50820401_22_dialog_content = "Wait, I still have more questions to ask you!",
  ui_story_5082_50820401_23_dialog_content = "About the Caelestites and Eraveil! About Soroz and—",
  ui_story_5082_50820401_24_dialog_content = "Then come find me—",
  ui_story_5082_50820401_25_dialog_content = "Hey!",
  ui_story_5082_50820401_26_dialog_content = "What's wrong, kid? Snap out of it!",
  ui_story_5082_50820401_27_dialog_content = "Just now, I...",
  ui_story_5082_50820401_28_dialog_content = "Heh, scared of your own dreams eh? Looks like you definitely need more training.",
  ui_story_5082_50820401_29_dialog_content = "Meow... I know all about getting lots of restful sleep. You should try learning from me sometime!",
  ui_story_5082_50820401_30_dialog_content = "That didn't feel like a dream just now...",
  ui_story_5082_50820401_31_dialog_content = "I have to go search for it!",
  ui_story_5082_50820401_32_dialog_content = "Hey, where do you think you're going?! At least wait for us—",
  ui_story_5082_50820401_33_dialog_content = "*yawn* It Doesn't look like the Grand Marshal or Officer Vivian is around either.",
  ui_story_5082_50820401_34_dialog_content = "Even though I can barely sense it, I can tell that it's somewhere in this direction. The ruins where yesterday's exercise got cancelled...",
  ui_story_5082_50820401_35_dialog_content = "Huh? I hear voices up ahead...",
  ui_story_5082_50820401_36_dialog_content = "PlayerName? Didn't I tell you this is a restricted area?",
  ui_story_5082_50820401_37_dialog_content = "It's fine, Vivian. PlayerNamewouldn't rush over here if it wasn't for a good reason.",
  ui_story_5082_50820401_38_dialog_content = "Reinhardt, Vivian... I...",
  ui_story_5082_50820401_39_dialog_content = "This is a pretty big meeting, and in the middle of the night no less. Are we deciding whether or not to restart the training exercise?",
  ui_story_5082_50820401_40_dialog_content = "I'd rather be asleep, but not if it means missing out on something important.",
  ui_story_5082_50820401_41_dialog_content = "I sense the presence of a Colossus somewhere nearby!",
  ui_story_5082_50820401_42_dialog_content = "!",
  ui_story_5082_50820401_43_dialog_content = "... I knew it.",
  ui_story_5082_50820401_44_dialog_content = "Say, this isn't the research base where the reserve navigator experiments were held, is it?",
  ui_story_5082_50820401_45_dialog_content = "Research base... you mean the one that blew up all those years ago?",
  ui_story_5082_50820401_46_dialog_content = "... I remember Vice saying that she participated in something called \"Project: Navigator.\"",
  ui_story_5082_50820401_47_dialog_content = "But apparently the project was a failure, and Vice lost most of her memories from before and after that time.",
  ui_story_5082_50820401_48_dialog_content = "Was Illumina trying to train someone to be Spearhead's Navigator?",
  ui_story_5082_50820401_49_dialog_content = "Wait... Vice must've been a little girl when that happened, right?",
  ui_story_5082_50820401_50_dialog_content = "All of you are correct. During the Darkover Crisis, Illumina launched that program to improve our chances for a brighter future.",
  ui_story_5082_50820401_51_dialog_content = "But we lost too many people, and the research base was buried underground. Our records of the incident are few and far between as well...",
  ui_story_5082_50820401_52_dialog_content = "That program brought shame to entire Illumina and for me... Being unable to conduct a follow-up investigation despite my involvement in the program was even more shameful.",
  ui_story_5082_50820401_53_dialog_content = "... Does that mean you participated in the experiment along with Vice.",
  ui_story_5082_50820401_54_dialog_content = "No. I'm the one who destroyed it.",
  ui_story_5082_50820401_55_dialog_content = "...",
  ui_story_5082_50820401_56_dialog_content = "They said I rescued Vice, but to tell the truth, none of it seemed especially real to me.",
  ui_story_5082_50820401_57_dialog_content = "And that's how I felt right up until yesterday's battle with Barton. When we fought, memories began to surface in my mind...",
  ui_story_5082_50820401_58_dialog_content = "It felt like a secret was buried somewhere here, so I came to see for myself.",
  ui_story_5082_50820401_59_dialog_content = "What you said just now confirmed my suspicions, PlayerName.",
  ui_story_5082_50820401_60_dialog_content = "That Colossus was never moved from this place.",
  ui_story_5082_50820401_61_dialog_content = "—It's right beneath our feet.",
  ui_story_5082_50820401_62_dialog_content = "... If that's really the case, then I need to go see it.",
  ui_story_5082_50820401_63_dialog_content = "Vice never said it, but I'm sure anyone would be bothered if they lost their memories.",
  ui_story_5082_50820401_64_dialog_content = "She's helped me so much ever since we met. It's only right for me to do something for her.",
  ui_story_5082_50820401_65_dialog_content = "As this is a restricted area, allowing you to enter would be a violation of Illumina's regulations.",
  ui_story_5082_50820401_66_dialog_content = "But—",
  ui_story_5082_50820401_67_dialog_content = "However, the Grand Marshal is also present.",
  ui_story_5082_50820401_68_dialog_content = "With her consent, you may be granted permission to enter.",
  ui_story_5082_50820401_69_dialog_content = "I was planning on going down there anyway. I wouldn't mind if PlayerName tagged along.",
  ui_story_5082_50820401_70_dialog_content = "But you have to promise me something.",
  ui_story_5082_50820401_71_dialog_content = "It may be different from what you know, but according to centuries of Illumina intelligence reports—",
  ui_story_5082_50820401_72_dialog_content = "Of the Colossi you've encountered so far, this one might be far more hostile than you expect.",
  ui_story_5082_50820401_73_dialog_content = "I'm sure it didn't have many nice things to say about Illumina when it made contact with you.",
  ui_story_5082_50820401_74_dialog_content = "... That's true.",
  ui_story_5082_50820401_75_dialog_content = "After the incident with the Engineer, I swore I wouldn't risk letting you sense something dangerous like that ever again.",
  ui_story_5082_50820401_76_dialog_content = "Especially when the danger is directed at Illumina.",
  ui_story_5082_50820401_77_dialog_content = "But telling you not to use your unique psychic powers is no different than telling you not to breathe.",
  ui_story_5082_50820401_78_dialog_content = "All I ask is that you tell me when you sense something the moment it happens.",
  ui_story_5082_50820401_79_dialog_content = "Then can I make a request too?",
  ui_story_5082_50820401_80_dialog_content = "Go ahead, I'm listening.",
  ui_story_5082_50820401_81_dialog_content = "I won't try to hide anything I sense, but I'd like for everyone to follow the same rule.",
  ui_story_5082_50820401_82_dialog_content = "Whether something seems off, or if you feel a little strange...",
  ui_story_5082_50820401_83_dialog_content = "Even if you think it's no big deal, please tell the group right away. That way, we can work on a solution together.",
  ui_story_5082_50820401_84_dialog_content = "You've gotten a lot more mature than when we first met.",
  ui_story_5082_50820401_85_dialog_content = "Deal.",
  ui_story_5082_50820401_86_dialog_content = "I don't particularly care about this incident, but it did have a huge and lasting effect on Illumina. If you're gonna look into it, then count me in.",
  ui_story_5082_50820401_87_dialog_content = "I don't really feel like joining everyone, to be honest.",
  ui_story_5082_50820401_88_dialog_content = "But these ruins are hiding something that I want to know about, so I guess I'll tag along too.",
  ui_story_5082_50820401_89_dialog_content = "We just happen to be going in the same direction, so don't expect me to help out very much!",
  ui_story_5082_50820401_90_dialog_content = "What are we gonna do with you, Philyshy...",
  ui_story_5082_50820401_91_dialog_content = "Alright, enough beating around the bush. I'll lead the way, now let's get going!",
  ui_story_5082_50820401_92_dialog_content = "I think I should scout out a path first, Barton. Don't worry, I won't try to sense the Colossus.",
  ui_story_5082_50820401_93_dialog_content = "I'll just take a look at our surroundings to make sure they're safe before we move on.",
  ui_story_5082_50820401_94_dialog_content = "*cough* The space below us is huge, but it's mostly a bunch of ruins...",
  ui_story_5082_50820401_95_dialog_content = "<color=#e8d9bb>Crumble...</color>",
  ui_story_5082_50820401_96_dialog_content = "Whoa! I almost tripped just now.",
  ui_story_5082_50820401_97_dialog_content = "The ground's covered in wires. Watch your step, everyone.",
  ui_story_5082_50820401_98_dialog_content = "<color=#e8d9bb>Bzzz—</color>",
  ui_story_5082_50820401_99_dialog_content = "What's that sound?",
  ui_story_5082_50820401_100_dialog_content = "Meow! Something's flying towards us!",
  ui_story_5082_50820401_101_dialog_content = "Buzz—",
  ui_story_5082_50820401_102_dialog_content = "Dodge it, PlayerName!",
  ui_story_5082_50820401_103_dialog_content = "—!",
  ui_story_5082_50820401_104_dialog_content = "...",
  ui_story_5082_50820401_105_dialog_content = "PlayerName? PlayerName!",
  ui_story_5082_50820401_106_dialog_content = "I think I hear someone shouting my name.",
  ui_story_5082_50820501_1_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820501_2_dialog_content = "Was that... a bugle?",
  ui_story_5082_50820501_3_dialog_content = "I could've sworn I heard a girl shouting just now... Huh?",
  ui_story_5082_50820501_4_dialog_content = "Is this... a military academy?",
  ui_story_5082_50820501_5_dialog_content = "Whoa! Reinhardt wins again!!",
  ui_story_5082_50820501_6_dialog_content = "Reinhardt?",
  ui_story_5082_50820501_7_dialog_content = "Anyone else feel like stepping up?",
  ui_story_5082_50820501_8_dialog_content = "Give it a rest, Reinhardt. You've already beaten everyone in the entire school; no one's dumb enough to challenge you anymore.",
  ui_story_5082_50820501_9_dialog_content = "Yeah but you still haven't given up, right?",
  ui_story_5082_50820501_10_dialog_content = "I just don't feel like beating you at something as stupid as arm wrestling.",
  ui_story_5082_50820501_11_dialog_content = "Our instructor says that we're running an obstacle course after class today. That's when I'll finally put you in your place.",
  ui_story_5082_50820501_12_dialog_content = "Reinhardt took first place in the obstacle course again! The person in second place was over ten seconds slower too!",
  ui_story_5082_50820501_13_dialog_content = "That's hardly surprising. When has she NOT been in the first place?",
  ui_story_5082_50820501_14_dialog_content = "So, who came in second? Don't tell me it was Wrath again?",
  ui_story_5082_50820501_15_dialog_content = "It sure was!",
  ui_story_5082_50820501_16_dialog_content = "It's always been this way ever since I joined the academy and became their classmate. Every contest ends exactly the same for them.",
  ui_story_5082_50820501_17_dialog_content = "I feel so useless compared to them, honestly.",
  ui_story_5082_50820501_18_dialog_content = "Cologne, Vaughn.",
  ui_story_5082_50820501_19_dialog_content = "Am I hearing things, or did Reinhardt just say our names?",
  ui_story_5082_50820501_20_dialog_content = "I'm pretty sure I heard it too.",
  ui_story_5082_50820501_21_dialog_content = "That's because I am calling you guys, now get over here!",
  ui_story_5082_50820501_22_dialog_content = "Wh-Why...",
  ui_story_5082_50820501_23_dialog_content = "Why does Reinhardt know our names?!",
  ui_story_5082_50820501_24_dialog_content = "I was watching your class' mock battle just now.",
  ui_story_5082_50820501_25_dialog_content = "Cologne, your logistics skills are some of the most effective I've seen in our year.",
  ui_story_5082_50820501_26_dialog_content = "And Vaughn, your reaction speed is nothing to laugh about either.",
  ui_story_5082_50820501_27_dialog_content = "So I thought I'd come and say hi. If the chance ever comes up, I'd really like to team up with you two.",
  ui_story_5082_50820501_28_dialog_content = "Reinhardt! The instructor ordered us to assemble!",
  ui_story_5082_50820501_29_dialog_content = "Gotta go! I'll see you guys around.",
  ui_story_5082_50820501_30_dialog_content = "Reinhardt... said she was impressed with us.",
  ui_story_5082_50820501_31_dialog_content = "Hey... Should we go run a few laps around the track?",
  ui_story_5082_50820501_32_dialog_content = "Yeah! Let's do it! Right now!",
  ui_story_5082_50820501_33_dialog_content = "Fall in!",
  ui_story_5082_50820501_34_dialog_content = "You've all been assigned to an urgent mission.",
  ui_story_5082_50820501_35_dialog_content = "Recently, a number of Undercities, including Undercities 38, 42, and 59, have fallen under simultaneous attack by a new type of Eclipsite.",
  ui_story_5082_50820501_36_dialog_content = "These new Eclipsites aren't particularly powerful, but they make up for it with their overwhelming numbers, which are still growing. The living conditions and productivity of these Undercities have already been seriously impacted!",
  ui_story_5082_50820501_37_dialog_content = "You'll be divided into three small teams and sent to the following Undercities to provide support.",
  ui_story_5082_50820501_38_dialog_content = "Yes, sir!",
  ui_story_5082_50820501_39_dialog_content = "...",
  ui_story_5082_50820501_40_dialog_content = "<color=#e8d9bb>After the crisis ended</color>",
  ui_story_5082_50820501_41_dialog_content = "Reinhardt!",
  ui_story_5082_50820501_42_dialog_content = "Your orders were to lead your team to Undercity 42 and provide reinforcements! What are you doing in Undercity 28?!",
  ui_story_5082_50820501_43_dialog_content = "Sir! When we were given our assignments, I noticed that the Undercities in question were relatively distant from one another.",
  ui_story_5082_50820501_44_dialog_content = "For the same type of Eclipsite to appear in each Undercity at the same time, it must mean that there's some sort of connection between them.",
  ui_story_5082_50820501_45_dialog_content = "After arriving in Undercity 42 and dispatching the Eclipsites there, I determined they were extremely vulnerable to attack.",
  ui_story_5082_50820501_46_dialog_content = "However, I discovered the presence of a unique Eclipsite in their midst, a fast-moving one that appears to be capable of rapid regeneration!",
  ui_story_5082_50820501_47_dialog_content = "Following further observation, I confirmed that this type of Eclipsite shares multiple characteristics with sporous plants.",
  ui_story_5082_50820501_48_dialog_content = "And after cross-referencing my map, I realized that all of these Undercities are directly connected via railways, with Undercity 28 at their center.",
  ui_story_5082_50820501_49_dialog_content = "This leads me to believe that these Eclipsites propagated to each of the affected Undercities through our rail carts, and that the main body is located somewhere in Undercity 28.",
  ui_story_5082_50820501_50_dialog_content = "So I brought my team here to hunt down and destroy the source of the invasion!",
  ui_story_5082_50820501_51_dialog_content = "Afterward, I received confirmation from the other Undercities that the Eclipsites were no longer increasing in numbers.",
  ui_story_5082_50820501_52_dialog_content = "... You discovered! You determined! You observed!",
  ui_story_5082_50820501_53_dialog_content = "I'm not asking you about what you've done, Reinhardt! I'm asking you why you did it!!",
  ui_story_5082_50820501_54_dialog_content = "Do you take your superiors for a bunch of fools? Do you think you're the smartest soldier in Illumina just because you uncovered the truth?!",
  ui_story_5082_50820501_55_dialog_content = "Abandoning your mission, acting on your own, and ignoring urgent orders to retreat! And you call yourself a soldier?",
  ui_story_5082_50820501_56_dialog_content = "I'm aware of the consequences of my actions, and am prepared to accept any punishment! However, I still believe that rooting out the source of the Eclipsite invasion as soon as possible was the best choice of action!",
  ui_story_5082_50820501_57_dialog_content = "Get the hell out!!!",
  ui_story_5082_50820501_58_dialog_content = "!",
  ui_story_5082_50820501_59_dialog_content = "Were you waiting for me or something?",
  ui_story_5082_50820501_60_dialog_content = "I just came to drop off my work report for the instructor.",
  ui_story_5082_50820501_61_dialog_content = "... Are you alright?",
  ui_story_5082_50820501_62_dialog_content = "Why wouldn't I be? I just got chewed out, that's all.",
  ui_story_5082_50820501_63_dialog_content = "I wish I knew why the instructor had it out for me.",
  ui_story_5082_50820501_64_dialog_content = "Is that really what's on your mind? Never mind.",
  ui_story_5082_50820501_65_dialog_content = "At the end of the day, we both got sent to the Undercities to provide reinforcement, but I failed to figure out the truth behind those Eclipsites. Looks like you win again, Reinhardt.",
  ui_story_5082_50820501_66_dialog_content = "But mark my words! I won't lose to you next time!",
  ui_story_5082_50820501_67_dialog_content = "Sure.",
  ui_story_5082_50820501_68_dialog_content = "... What was that? I challenge you, and that's all you have to say?",
  ui_story_5082_50820501_69_dialog_content = "You challenge me every single day, don't you?",
  ui_story_5082_50820501_70_dialog_content = "That's why I'm always prepared for anything.",
  ui_story_5082_50820501_71_dialog_content = "Don't... Don't you dare take my challenges for granted!",
  ui_story_5082_50820501_72_dialog_content = "You're the only person worthy of being my rival, so until I defeat you, you're not allowed to lose to anyone else!",
  ui_story_5082_50820501_73_dialog_content = "Haha, I'll do my best.",
  ui_story_5082_50820501_74_dialog_content = "(So this took place in the past.)",
  ui_story_5082_50820501_75_dialog_content = "(Reinhardt and Wrath were so close during their academy days...)",
  ui_story_5082_50820501_76_dialog_content = "Captain! It's an emergency—",
  ui_story_5082_50820501_77_dialog_content = "(The scene is changing again...)",
  ui_story_5082_50820501_78_dialog_content = "Huh...?",
  ui_story_5082_50820501_79_dialog_content = "Halt—!",
  ui_story_5082_50820501_80_dialog_content = "Today's training is over, now return to your barracks! Curfew's in effect, so no going outside after dark!",
  ui_story_5082_50820501_81_dialog_content = "Phew, glad that's over. I'm beaten...",
  ui_story_5082_50820501_82_dialog_content = "It's still a little early though, isn't it? Usually the instructor piles on extra training if we finish this soon.",
  ui_story_5082_50820501_83_dialog_content = "Who cares? This just means we get more time to relax! Right, Reinhardt?",
  ui_story_5082_50820501_84_dialog_content = "... Reinhardt?",
  ui_story_5082_50820501_85_dialog_content = "Hey! Where are you going?",
  ui_story_5082_50820501_86_dialog_content = "To get into more trouble.",
  ui_story_5082_50820501_87_dialog_content = "Then I'm coming too.",
  ui_story_5082_50820501_88_dialog_content = "Didn't you hear what I just said?",
  ui_story_5082_50820501_89_dialog_content = "Are you underestimating me?",
  ui_story_5082_50820501_90_dialog_content = "If you were really that reckless and inconsiderate, I wouldn't consider you my rival no matter how strong you were.",
  ui_story_5082_50820501_91_dialog_content = "The instructor was staring daggers at you just now, and yet you're still hell-bent on sneaking out. Why? What did you discover?",
  ui_story_5082_50820501_92_dialog_content = "An Eclipsite invasion.",
  ui_story_5082_50820501_93_dialog_content = "What?!",
  ui_story_5082_50820501_94_dialog_content = "Roooaaar!",
  ui_story_5082_50820501_95_dialog_content = "Commander! The Eclipsites keep coming, but we don't have enough soldiers to hold them off! Requesting—",
  ui_story_5082_50820501_96_dialog_content = "Keep them at bay even if it costs you your lives!",
  ui_story_5082_50820501_97_dialog_content = "Where in the world did all of these Eclipsites come from—",
  ui_story_5082_50820501_98_dialog_content = "Roar!",
  ui_story_5082_50820501_99_dialog_content = "Ah—",
  ui_story_5082_50820501_100_dialog_content = "Hold the line!",
  ui_story_5082_50820501_101_dialog_content = "Damned filthy monsters!",
  ui_story_5082_50820501_102_dialog_content = "Pierce through all!",
  ui_story_5082_50820501_103_dialog_content = "Strike! Richthofen!",
  ui_story_5082_50820501_104_dialog_content = "What are you doing here?!",
  ui_story_5082_50820501_105_dialog_content = "Like I said, I'm not gonna lose to you!",
  ui_story_5082_50820501_106_dialog_content = "Graaah...",
  ui_story_5082_50820501_107_dialog_content = "Students?",
  ui_story_5082_50820501_108_dialog_content = "Illumina Military Academy Student Reinhardt, reporting in for support duty!",
  ui_story_5082_50820501_109_dialog_content = "Illumina Military Academy Student Wrath, reporting in for support duty!",
  ui_story_5082_50820501_110_dialog_content = "Quit screwing around and go back!",
  ui_story_5082_50820501_111_dialog_content = "I will personally report to my instructor after this is over, but as a citizen of Illumina, I refuse to stand by while Eclipsites invade our home!",
  ui_story_5082_50820501_112_dialog_content = "Please assign me to the left flank's defenses!",
  ui_story_5082_50820501_113_dialog_content = "And please assign me to the right one!",
  ui_story_5082_50820501_114_dialog_content = "You two? Is this some kind of joke?!",
  ui_story_5082_50820501_115_dialog_content = "We can win, I promise.",
  ui_story_5082_50820501_116_dialog_content = "Also, we're not the only ones here to help.",
  ui_story_5082_50820501_117_dialog_content = "Two Eclipsites are attempting to ambush us from a pit at one o'clock! Leave them to me!",
  ui_story_5082_50820501_118_dialog_content = "The Medic Legion will take care of the heavily wounded! We'll administer first-aid to light injuries over here!",
  ui_story_5082_50820501_119_dialog_content = "Allow me to introduce my fellow classmates and comrades-in-arms: Vaughn and Cologne.",
  ui_story_5082_50820501_120_dialog_content = "Looks like this is our chance to finally team up, Reinhardt!",
  ui_story_5082_50820501_121_dialog_content = "Forgive us, commander, but every single soldier has a duty to defend Illumina, even soldiers-in-training!",
  ui_story_5082_50820501_122_dialog_content = "Haha, save your apologies for later!",
  ui_story_5082_50820501_123_dialog_content = "Take up your weapons and prepare to face the Eclipsites!",
  ui_story_5082_50820501_124_dialog_content = "Roger!",
  ui_story_5082_50820501_125_dialog_content = "And just when did you get promoted to commander, huh?!",
  ui_story_5082_50820501_126_dialog_content = "... Reinhardt.",
  ui_story_5082_50820501_127_dialog_content = "<color=#e8d9bb>The next day</color>",
  ui_story_5082_50820501_128_dialog_content = "Fall in and begin training!",
  ui_story_5082_50820501_129_dialog_content = "Yes, sir!",
  ui_story_5082_50820501_130_dialog_content = "No way. Is the instructor seriously letting us off the hook after yesterday's disaster?",
  ui_story_5082_50820501_131_dialog_content = "Reinhardt and Wrath don't look like they're in trouble either, but that just puts me even more on edge...",
  ui_story_5082_50820501_132_dialog_content = "Wait, look! Isn't that the 1st Legion Commander? What's he doing here?!",
  ui_story_5082_50820501_133_dialog_content = "Academy Student Reinhardt! Fall out and report to your instructor's office!",
  ui_story_5082_50820501_134_dialog_content = "Yes, sir!",
  ui_story_5082_50820501_135_dialog_content = "...",
  ui_story_5082_50820501_136_dialog_content = "<color=#e8d9bb>War Room No. 3</color>",
  ui_story_5082_50820501_137_dialog_content = "Greetings, Commander!",
  ui_story_5082_50820501_138_dialog_content = "Due to your outstanding individual performance, we've prepared a series of special training experiments just for you.",
  ui_story_5082_50820501_139_dialog_content = "Roar!",
  ui_story_5082_50820501_140_dialog_content = "These test subject Eclipsites are a crucial part of the training.",
  ui_story_5082_50820501_141_dialog_content = "In a few moments, I will be releasing them into the combat area. I would like for you to fight them using your full power.",
  ui_story_5082_50820501_142_dialog_content = "Tch... These guys hit pretty hard.",
  ui_story_5082_50820501_143_dialog_content = "The Eclipsites you're currently facing are the weakest specimens in the experiment.",
  ui_story_5082_50820501_144_dialog_content = "This training is designed to forge you into Illumina's most powerful soldier. If you're unable to defeat them, we'll have to reconsider your candidacy for the program.",
  ui_story_5082_50820501_145_dialog_content = "Illumina's most powerful soldier, huh? Heh... Who said I couldn't defeat them?!",
  ui_story_5082_50820501_146_dialog_content = "Let's go again!",
  ui_story_5082_50820502_1_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5082_50820502_2_dialog_content = "You call that a punch?! Quit holding back already!",
  ui_story_5082_50820502_3_dialog_content = "Hahaha, sorry. Let's go again.",
  ui_story_5082_50820502_4_dialog_content = "You're such a... Wait, what happened to your hands?!",
  ui_story_5082_50820502_5_dialog_content = "It's from yesterday—",
  ui_story_5082_50820502_6_dialog_content = "Academy Student Reinhardt! Fall out and report to the special training facility!",
  ui_story_5082_50820502_7_dialog_content = "Yes, sir.",
  ui_story_5082_50820502_8_dialog_content = "Instructor! Reinhardt's hands are too injured to continue training! Please give her a day to recover!",
  ui_story_5082_50820502_9_dialog_content = "Academy Student Reinhardt! Report to the special training facility!",
  ui_story_5082_50820502_10_dialog_content = "Instructor—",
  ui_story_5082_50820502_11_dialog_content = "Wrath.",
  ui_story_5082_50820502_12_dialog_content = "Instructor! Please excuse the interruption, but how much longer will Reinhardt's special training continue?",
  ui_story_5082_50820502_13_dialog_content = "A soldier is sworn to carry out their orders. She'll continue with her training for as long as her orders dictate!",
  ui_story_5082_50820502_14_dialog_content = "... Understood, sir.",
  ui_story_5082_50820502_15_dialog_content = "(Her hands... Could these be the \"old wounds\" Reinhardt mentioned earlier?)",
  ui_story_5082_50820502_16_dialog_content = "(No matter how special the training may be, it's not worth doing this to your own body.)",
  ui_story_5082_50820502_17_dialog_content = "(The Eclipsites won't give a damn about your hands hurting.)",
  ui_story_5082_50820502_18_dialog_content = "(Is that the instructor's voice?)",
  ui_story_5082_50820502_19_dialog_content = "(... The academy gets its share of troublemakers every year, but this is the first time I've seen such a promising student disregard orders with absolute impunity...)",
  ui_story_5082_50820502_20_dialog_content = "(You deserve to be put in your place more than anyone else! If you love fighting Eclipsites so much, we'll let you fight 'em to your heart's content!)",
  ui_story_5082_50820502_21_dialog_content = "(This guy's awful!)",
  ui_story_5082_50820502_22_dialog_content = "—!",
  ui_story_5082_50820502_23_dialog_content = "(It's that girl's scream again.)",
  ui_story_5082_50820502_24_dialog_content = "(Who could she be—)",
  ui_story_5082_50820502_25_dialog_content = "!",
  ui_story_5082_50820601_1_dialog_content = "Whoa!",
  ui_story_5082_50820601_2_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5082_50820601_3_dialog_content = "A boulder...",
  ui_story_5082_50820601_4_dialog_content = "That was a close one! If PlayerName noticed it a second sooner, we'd all be as flat as pancakes right now!",
  ui_story_5082_50820601_5_dialog_content = "I'll go scout up ahead. The rest of you wait here for me.",
  ui_story_5082_50820601_6_dialog_content = "I'll go with you.",
  ui_story_5082_50820601_7_dialog_content = "What is it, PlayerName? You look like you have something to say.",
  ui_story_5082_50820601_8_dialog_content = "That boulder just now... I didn't notice it at all.",
  ui_story_5082_50820601_9_dialog_content = "I sensed a girl just now... Or at least I think I did. Either way, she scared me into jumping aside.",
  ui_story_5082_50820601_10_dialog_content = "Was she... Glowing red, by any chance?",
  ui_story_5082_50820601_11_dialog_content = "How did you know?",
  ui_story_5082_50820601_12_dialog_content = "Because I saw her in my memories yesterday.",
  ui_story_5082_50820601_13_dialog_content = "...",
  ui_story_5082_50820601_14_dialog_content = "You've had something to tell me ever since yesterday, right?",
  ui_story_5082_50820601_15_dialog_content = "Not just me.",
  ui_story_5082_50820601_16_dialog_content = "Barton, Philyshy... Everyone's worried about you.",
  ui_story_5082_50820601_17_dialog_content = "Is it really so obvious that something's the matter with me?",
  ui_story_5082_50820601_18_dialog_content = "I appreciate the concern, but there's no need to worry yourself like this, PlayerName.",
  ui_story_5082_50820601_19_dialog_content = "I don't have time to waste on sentimentality, and it's not like I can't tell you about what happened either.",
  ui_story_5082_50820601_20_dialog_content = "During yesterday's training, I suddenly remembered a bunch of things that I have no recollection of.",
  ui_story_5082_50820601_21_dialog_content = "People, places, emotions... everything felt so unfamiliar.",
  ui_story_5082_50820601_22_dialog_content = "Unfortunately, those memories flashed through my mind so quickly that I couldn't tell... Whether or not I really shot that girl dead.",
  ui_story_5082_50820601_23_dialog_content = "Sh-Shot her...?! Is this the \"buried secret\" you were talking about? So that scream I heard earlier...",
  ui_story_5082_50820601_24_dialog_content = "The memories are still too fragmented for me to understand them... I can't even remember her name.",
  ui_story_5082_50820601_25_dialog_content = "Which is odd, considering I remember every single person who attended the academy with me.",
  ui_story_5082_50820601_26_dialog_content = "The academy? That's right. I have a few memories from your training days, too.",
  ui_story_5082_50820601_27_dialog_content = "But that girl never appeared in any of them.",
  ui_story_5082_50820601_28_dialog_content = "Ah! S-Sorry, I didn't mean to pry into your past like that.",
  ui_story_5082_50820601_29_dialog_content = "That's fine, I don't particularly mind. Still, I'm curious to hear about what you saw in my memories.",
  ui_story_5082_50820601_30_dialog_content = "Well, there was a part where you were arm-wrestling people on the training field... And a part where you saved multiple Undercities by disobeying your commander's orders...",
  ui_story_5082_50820601_31_dialog_content = "I also saw what happened to you during your \"special training...\"",
  ui_story_5082_50820601_32_dialog_content = "Haha, I guess I do remember all of that stuff happening.",
  ui_story_5082_50820601_33_dialog_content = "I was young and arrogant back then. I thought I could solve any problem on my own.",
  ui_story_5082_50820601_34_dialog_content = "Are you sure you didn't see that girl in any of those memories?",
  ui_story_5082_50820601_35_dialog_content = "I'm sure...",
  ui_story_5082_50820601_36_dialog_content = "Why not try asking your good friend Philyshy about it? After all, I deal with this sort of thing all the time!",
  ui_story_5082_50820601_37_dialog_content = "We've been through all kinds of adventures together, yet people somehow manage to forget about Yumi.",
  ui_story_5082_50820601_38_dialog_content = "I think Reinhardt's situation is a little different, Philyshy.",
  ui_story_5082_50820601_39_dialog_content = "I think the Committee may know more about these memories... Besides, they owe me plenty of favors.",
  ui_story_5082_50820601_40_dialog_content = "Take a look at this, Grand Marshal. Those strange robots that just attacked us are moving in formation now.",
  ui_story_5082_50820601_41_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_5082_50820601_42_dialog_content = "We took a look at the one that attacked us earlier. Judging from its design, it appears to be a type of combat droid.",
  ui_story_5082_50820601_43_dialog_content = "But what's truly unique about its structure, however, is that it seems capable of merging with other machines. I wonder if they were researching this type of technology here?",
  ui_story_5082_50820601_44_dialog_content = "Their flight pattern is fully coordinated. It looks like they're moving deeper into the ruins.",
  ui_story_5082_50820601_45_dialog_content = "Let's follow them.",
  ui_story_5082_50820601_46_dialog_content = "I'll scout ahead.",
  ui_story_5082_50820601_47_option_content = "Psychic Scan—",
  ui_story_5082_50820601_48_dialog_content = "%^ seek power is $!#￥ to seek destruction... $%^#$#^!$",
  ui_story_5082_50820601_49_dialog_content = "Spearhead! Are you nearby? I need to know more about what happened here—",
  ui_story_5082_50820601_50_dialog_content = "—!",
  ui_story_5082_50820601_51_dialog_content = "It's her...!",
  ui_story_5082_50820601_52_option_content = "Force Boost!",
  ui_story_5082_50820601_53_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_54_dialog_content = "There's the bugle again.",
  ui_story_5082_50820601_55_dialog_content = "Why do I keep getting dragged into these memories whenever I try to make contact with that girl?",
  ui_story_5082_50820601_56_dialog_content = "There's Reinhardt and Wrath.",
  ui_story_5082_50820601_57_dialog_content = "That was the bugle. You should go join them in formation.",
  ui_story_5082_50820601_58_dialog_content = "While you run off for more of your \"special training\"?",
  ui_story_5082_50820601_59_dialog_content = "Is that training program even official? Or is it something they cooked up just for you?",
  ui_story_5082_50820601_60_dialog_content = "You keep coming back with fresh wounds every day. Not even the soldiers returning from the front lines show up with injuries like yours.",
  ui_story_5082_50820601_61_dialog_content = "... I-I'm not worried about you or anything! I just don't want anyone interfering with our challenges!",
  ui_story_5082_50820601_62_dialog_content = "You're overthinking things. I just took my training to the next level, so I'm still getting used to it.",
  ui_story_5082_50820601_63_dialog_content = "There's no such thing as useless training. Any skills and experience I acquire will add to my own strength.",
  ui_story_5082_50820601_64_dialog_content = "Reinhardt! You think you can ignore your daily duties just because of your special training?!",
  ui_story_5082_50820601_65_dialog_content = "Well not on my watch, now give me ten more laps!",
  ui_story_5082_50820601_66_dialog_content = "Instructor, please! Reinhardt's too exhausted to keep going! She needs rest!",
  ui_story_5082_50820601_67_dialog_content = "Have you both forgotten the first thing I taught you? A soldier always follows orders!",
  ui_story_5082_50820601_68_dialog_content = "That's five more laps for you, Wrath!",
  ui_story_5082_50820601_69_dialog_content = "Make it ten, sir!",
  ui_story_5082_50820601_70_dialog_content = "You don't have to keep following me around.",
  ui_story_5082_50820601_71_dialog_content = "\"There's no such thing as useless training.\" You said it yourself, didn't you?",
  ui_story_5082_50820601_72_dialog_content = "Fine, but I'm not thanking you for this.",
  ui_story_5082_50820601_73_dialog_content = "No one asked for your apology anyway.",
  ui_story_5082_50820601_74_dialog_content = "(From then on, every single day was the same for Reinhardt.)",
  ui_story_5082_50820601_75_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_76_dialog_content = "<color=#e8d9bb>The morning bugle call.</color>",
  ui_story_5082_50820601_77_dialog_content = "Academy Student Reinhardt! Report to the special training facility!",
  ui_story_5082_50820601_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_79_dialog_content = "<color=#e8d9bb>The evening bugle call.</color>",
  ui_story_5082_50820601_80_dialog_content = "You're finally back, Reinhardt! Your hands...",
  ui_story_5082_50820601_81_dialog_content = "Sorry, I'm a little tired so I'm going straight to bed.",
  ui_story_5082_50820601_82_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_83_dialog_content = "Reinhardt, reporting for duty.",
  ui_story_5082_50820601_84_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_85_dialog_content = "Reinhardt—",
  ui_story_5082_50820601_86_dialog_content = "Nngh... Huh? Did you need something...?",
  ui_story_5082_50820601_87_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_88_dialog_content = "(Reinhardt went straight from her room to the special training facility and back, only stopping long enough to eat a few bites of her rations.)",
  ui_story_5082_50820601_89_dialog_content = "(Her life was centered entirely around training and sleep, both of which were dictated by the sound of a bugle.)",
  ui_story_5082_50820601_90_dialog_content = "We've compiled enough data from this portion of the program, which means you're ready for the next phase: explosive strength training.",
  ui_story_5082_50820601_91_dialog_content = "For this phase of your training, you will be fighting against combat droids that have been modified based on your specific attributes.",
  ui_story_5082_50820601_92_dialog_content = "Upon engaging them in battle, you'll feel as though you are fighting yourself.",
  ui_story_5082_50820601_93_dialog_content = "Use your full strength to surpass your limits and destroy them.",
  ui_story_5082_50820601_94_dialog_content = "Understood.",
  ui_story_5082_50820602_1_dialog_content = "(It hurts so much... They really raised the difficulty for this so-called \"explosive strength\" training.)",
  ui_story_5082_50820602_2_dialog_content = "Interesting. Her vital signs had completely disappeared just now, and yet she was able to regain consciousness and continue fighting...",
  ui_story_5082_50820602_3_dialog_content = "What did you say?",
  ui_story_5082_50820602_4_dialog_content = "A fine test subject, to be sure. The data we've gathered completely surpassed our expectations.",
  ui_story_5082_50820602_5_dialog_content = "And while the physical damage to her body is relatively high, it's still within acceptable parameters.",
  ui_story_5082_50820602_6_dialog_content = "Now then, it's time to move on to the next phase...",
  ui_story_5082_50820602_7_dialog_content = "May I ask a question?",
  ui_story_5082_50820602_8_dialog_content = "Oh, that's all for today's training. You're dismissed.",
  ui_story_5082_50820602_9_dialog_content = "Taking our initial calculations into consideration...",
  ui_story_5082_50820602_10_dialog_content = "This special training... Am I the only candidate, or are there others like me?",
  ui_story_5082_50820602_11_dialog_content = "The necessary parameters are...",
  ui_story_5082_50820602_12_dialog_content = "...",
  ui_story_5082_50820602_13_dialog_content = "<color=#e8d9bb>Secret Laboratory</color>",
  ui_story_5082_50820602_14_dialog_content = "Your wounds have been treated. Try not to get water on them for the next few days.",
  ui_story_5082_50820602_15_dialog_content = "I'll prepare some meds for you before you go. Remember to change your bandages every day, and eat plenty of—",
  ui_story_5082_50820602_16_dialog_content = "You can save the whole doctor spiel, Helios. It won't make any difference.",
  ui_story_5082_50820602_17_dialog_content = "Whenever she thinks something needs to be done, she chases after it at full power without listening to anyone else.",
  ui_story_5082_50820602_18_dialog_content = "Denier...",
  ui_story_5082_50820602_19_dialog_content = "I'm only telling the truth. It's just like how we agreed to meet here once a week.",
  ui_story_5082_50820602_20_dialog_content = "And yet, it's been four whole weeks since she last showed her face around here.",
  ui_story_5082_50820602_21_dialog_content = "She can barely keep her word, and whenever she does appear, she's unconscious and covered in wounds.",
  ui_story_5082_50820602_22_dialog_content = "One of these days, you're gonna pay me back for all the equipment you've broken from passing out everywhere!",
  ui_story_5082_50820602_23_dialog_content = "Enough, Denier! Try not to get the wrong idea, Reinhardt. I'm sure what she means to say...",
  ui_story_5082_50820602_24_dialog_content = "Is that there are a lot of flammables and explosives lying around, and she doesn't want you to hurt yourself.",
  ui_story_5082_50820602_25_dialog_content = "...",
  ui_story_5082_50820602_26_dialog_content = "I'm sorry, Denier. I know I made you worry by not showing up for so long.",
  ui_story_5082_50820602_27_dialog_content = "I'll make sure to get you brand-new laboratory equipment later.",
  ui_story_5082_50820602_28_dialog_content = "...",
  ui_story_5082_50820602_29_dialog_content = "There, see? Problem solved!",
  ui_story_5082_50820602_30_dialog_content = "...",
  ui_story_5082_50820602_31_dialog_content = "While we're on the subject, I know we built this laboratory ourselves...",
  ui_story_5082_50820602_32_dialog_content = "But it's a little too unventilated, don't you think? If Denier wants to continue with her experiments...",
  ui_story_5082_50820602_33_dialog_content = "Doesn't this place pose a suffocation risk?",
  ui_story_5082_50820602_34_dialog_content = "...",
  ui_story_5082_50820602_35_dialog_content = "Something wrong, Reinhardt?",
  ui_story_5082_50820602_36_dialog_content = "...",
  ui_story_5082_50820602_37_dialog_content = "... Huh? Sorry, I was spacing out.",
  ui_story_5082_50820602_38_dialog_content = "I was just thinking about my last training session. For some reason, I suddenly felt like I was drowning...",
  ui_story_5082_50820602_39_dialog_content = "Are you sure you're okay?",
  ui_story_5082_50820602_40_dialog_content = "Of course! You both know how fast I recover; I may be covered in wounds right now, but they'll be healed up before long.",
  ui_story_5082_50820602_41_dialog_content = "I've been going through even more training lately, so it's gotten a little harder to show up. I'll try not to be late next time.",
  ui_story_5082_50820602_42_dialog_content = "You're avoiding the subject, Reinhardt.",
  ui_story_5082_50820602_43_dialog_content = "You don't care about yourself, or anything else for that matter. All you care about is your stupid training.",
  ui_story_5082_50820602_44_dialog_content = "Do you even know what you're doing? The whole point of training is to increase a soldier's combat potential within certain limits.",
  ui_story_5082_50820602_45_dialog_content = "It isn't to break those limits at the expense of your own body.",
  ui_story_5082_50820602_46_dialog_content = "You're finally telling me what's really on your mind, Denier. I'm glad.",
  ui_story_5082_50820602_47_dialog_content = "You...",
  ui_story_5082_50820602_48_dialog_content = "Don't worry. I know what I'm doing.",
  ui_story_5082_50820602_49_dialog_content = "After all, I'm going to be Grand Marshal someday. How am I supposed to lead all of Illumina if I can't even get through my academy training?",
  ui_story_5082_50820602_50_dialog_content = "Hmph. Just remember to get me a bigger lab when you finally make Grand Marshal.",
  ui_story_5082_50820602_51_dialog_content = "I can't stand seeing Eclipsites in battle, so I'd rather become the greatest researcher in Illumina and study them from my operating table.",
  ui_story_5082_50820602_52_dialog_content = "I don't have great aspirations like you two. As long as I can be a good scout, that's all I need.",
  ui_story_5082_50820602_53_dialog_content = "What's not great about that?",
  ui_story_5082_50820602_54_dialog_content = "Every single soldier plays an important role in powering Illumina.",
  ui_story_5082_50820602_55_dialog_content = "Whether it's our scouts, our researchers, or even the Grand Marshal, all of us make up the lifeblood of Illumina.",
  ui_story_5082_50820602_56_dialog_content = "Anyway, it's hard enough for us to meet up like this, so let's talk about something nice for a change.",
  ui_story_5082_50820602_57_dialog_content = "Preferably something that we can put in our memoirs for the whole world to read.",
  ui_story_5082_50820602_58_dialog_content = "A future Grand Marshal, a future top scientist, and a future scout leader—",
  ui_story_5082_50820602_59_dialog_content = "The best comrades anyone could ask for.",
  ui_story_5082_50820700_1_dialog_content = "Are those combat droids trying to lead us down there? What a lousy tactic!",
  ui_story_5082_50820700_2_dialog_content = "Judging from your expression, I take it you just sensed something?",
  ui_story_5082_50820700_3_dialog_content = "I did. We're getting closer and closer to that glowing red girl.",
  ui_story_5082_50820700_4_dialog_content = "You sensed her presence again?",
  ui_story_5082_50820700_5_dialog_content = "She always appears following that scream, but whenever I try to make contact with her, I see more and more of...",
  ui_story_5082_50820700_6_dialog_content = "My past?",
  ui_story_5082_50820700_7_dialog_content = "Yeah...",
  ui_story_5082_50820700_8_dialog_content = "This time, I saw parts of your explosive strength training.",
  ui_story_5082_50820700_9_dialog_content = "That explains your expression.",
  ui_story_5082_50820700_10_dialog_content = "It was... Pretty brutal to watch.",
  ui_story_5082_50820700_11_dialog_content = "Like they were trying to make you abandon everything that makes you a person, and turn you into a living weapon.",
  ui_story_5082_50820700_12_dialog_content = "You're a kind person, PlayerName.",
  ui_story_5082_50820700_13_dialog_content = "But war is only brutal because there aren't many places where kindness can exist on the battlefield.",
  ui_story_5082_50820700_14_dialog_content = "Whether you agree with it or not, we have no choice but to march forward through that brutality.",
  ui_story_5082_50820700_15_dialog_content = "Back then, I wanted to become the greatest and most powerful soldier in the Federation. Naturally, accomplishing that meant putting myself through a living hell.",
  ui_story_5082_50820700_16_dialog_content = "But... Don't you think it was unfair? Didn't you ever want to quit, or even fight back?",
  ui_story_5082_50820700_17_dialog_content = "Of course I did. Every single day, in fact.",
  ui_story_5082_50820700_18_dialog_content = "Illumina currently has some of the best leaders in its history, but I don't think that happened out of nowhere. Back then, none of us had it easy.",
  ui_story_5082_50820700_19_dialog_content = "Grand Marshal, do you still remember what happened in Undercities 13 and 19?",
  ui_story_5082_50820700_20_dialog_content = "...",
  ui_story_5082_50820700_21_dialog_content = "<color=#e8d9bb>Illumina Federation, Gannon City, Year 1986</color>",
  ui_story_5082_50820700_22_dialog_content = "The commander still hasn't returned?",
  ui_story_5082_50820700_23_dialog_content = "Not yet, Lieutenant Reinhardt! The Grand Marshal requested his presence for a meeting!",
  ui_story_5082_50820700_24_dialog_content = "The commander has ordered to stand by until further notice. No exceptions.",
  ui_story_5082_50820700_25_dialog_content = "Another standby order? But everyone else has been deployed to defend key positions... What in the world is he thinking?",
  ui_story_5082_50820700_26_dialog_content = "Undercities 13 and 19 have fallen under Eclipsite attack, and all communications have been cut off. The only messenger who managed to escape is requesting reinforcements.",
  ui_story_5082_50820700_27_dialog_content = "... Where exactly did you learn about that?",
  ui_story_5082_50820700_28_dialog_content = "That's not important. What's important is that two of our Undercities are on the brink of destruction.",
  ui_story_5082_50820700_29_dialog_content = "While the Eclipsites are overrunning our home, the Grand Marshal and the commander are busy twiddling their thumbs in a meeting!",
  ui_story_5082_50820700_30_dialog_content = "The commander ordered us to stand by.",
  ui_story_5082_50820700_31_dialog_content = "Standing by right now is no different than letting them die. You, of all people, should know that.",
  ui_story_5082_50820700_32_dialog_content = "...",
  ui_story_5082_50820700_33_dialog_content = "What's the matter? Think you can still bury your head in the sand and feign ignorance?",
  ui_story_5082_50820700_34_dialog_content = "You're just like those pompous commanders, always willing to pretend that everything's okay as long as the blood doesn't reach your hands.",
  ui_story_5082_50820700_35_dialog_content = "...",
  ui_story_5082_50820700_36_dialog_content = "Lieutenant Reinhardt? Where are you going?",
  ui_story_5082_50820700_37_dialog_content = "Just taking a walk, that's all.",
  ui_story_5082_50820700_38_dialog_content = "<color=#e8d9bb>The doors of the central meeting hall swing wide open as 2nd Legion Commander Pango and Deputy Battalion Commander Barton storm out.</color>",
  ui_story_5082_50820700_39_dialog_content = "Hey, you two. I take it things didn't go too well in there?",
  ui_story_5082_50820700_40_dialog_content = "With that coward in charge of the 1st Legion? Of course not!",
  ui_story_5082_50820700_41_dialog_content = "Don't run off just yet! I'm here to deliver new orders.",
  ui_story_5082_50820700_42_dialog_content = "\"Effective immediately, the 2nd Legion must deploy to Undercities 13 and 19 to provide reinforcements, with Lieutenant Reinhardt and a portion of the 1st Legion also providing support.\"",
  ui_story_5082_50820700_43_dialog_content = "That's more or less the gist of it. How does it sound?",
  ui_story_5082_50820700_44_dialog_content = "You're seriously thinking of falsifying military orders?",
  ui_story_5082_50820700_45_dialog_content = "If you're not willing to help, then we'll handle it on our own.",
  ui_story_5082_50820700_46_dialog_content = "I can dispatch a few of the 1st Legion's squads; the rest of them are more than capable of defending Gannon City along with the 3rd Legion.",
  ui_story_5082_50820700_47_dialog_content = "We may not have much of an impact over here, but our presence in those Undercities could mean the difference between life and death.",
  ui_story_5082_50820700_48_dialog_content = "Unfortunately, I don't have nearly enough soldiers for this mission. That's why I wanted to ask the 2nd Legion for help.",
  ui_story_5082_50820700_49_dialog_content = "You know what'll happen to you if we go along with this, don't you?",
  ui_story_5082_50820700_50_dialog_content = "I appreciate your concern, commander... But saving lives is still more important to me.",
  ui_story_5082_50820700_51_dialog_content = "... You're just a lowly lieutenant. What gave you the confidence to approach us with a stunt like this?",
  ui_story_5082_50820700_52_dialog_content = "My belief is that neither of you would ever abandon your comrades.",
  ui_story_5082_50820700_53_dialog_content = "Are you still undecided, Commander Pango? Because I'm going with her either way.",
  ui_story_5082_50820700_54_dialog_content = "First you disobeyed orders, and now you're forging them? You have some serious audacity, Reinhardt.",
  ui_story_5082_50820700_55_dialog_content = "That's all you have to say after following me all this way?",
  ui_story_5082_50820700_56_dialog_content = "Hah! You think I'm just gonna stand around and let you do whatever you want?",
  ui_story_5082_50820700_57_dialog_content = "Interesting... It looks like we're not the only ones fed up with the upper brass, right? Good! It's about time we call the shots around here!",
  ui_story_5082_50820700_58_dialog_content = "I can hardly believe that actually happened... Although that does sound like you, Reinhardt.",
  ui_story_5082_50820700_59_dialog_content = "Unfortunately, we still didn't make it in time.",
  ui_story_5082_50820700_60_dialog_content = "Undercity 13 was all but annihilated, and Undercity 19 wasn't in much better shape.",
  ui_story_5082_50820700_61_dialog_content = "At the very least, we managed to rescue a few people... And while a lot of people praised our actions, we also caught the attention of the Committee.",
  ui_story_5082_50820700_62_dialog_content = "Ironically enough, the results of our actions kept us from being charged with insubordination. In fact, Wrath and I were lucky enough to get promoted to Battalion Commanders!",
  ui_story_5082_50820700_63_dialog_content = "Luck has nothing to do with this sort of thing. Not in Illumina.",
  ui_story_5082_50820700_64_dialog_content = "Commander Pango had been training you to take his place for a long time. The incident just forced him to push up his plans for you.",
  ui_story_5082_50820700_65_dialog_content = "You were still so young at the time, and you didn't have many accomplishments under your belt yet. I'm sure you had your fair share of difficulties back then too, didn't you??",
  ui_story_5082_50820700_66_dialog_content = "You're the one who had it harder than anyone else, Reinhardt. Your unauthorized actions and falsified orders really ticked off the 1st Legion's commander at the time.",
  ui_story_5082_50820700_67_dialog_content = "They demoted you to the lowest possible rank, stripping you of any authority and sending you in for basic training all over again.",
  ui_story_5082_50820700_68_dialog_content = "Hahaha! But even now, whenever I think of you confronting our superiors for my sake—",
  ui_story_5082_50820700_69_dialog_content = "It always gets my blood pumping, just like before! You even showed up with a whole crowd of people chanting, \"Splendor Illumina\"!",
  ui_story_5082_50820700_70_dialog_content = "...?",
  ui_story_5082_50820700_71_dialog_content = "Wait... The one who clashed with your superiors...",
  ui_story_5082_50820700_72_dialog_content = "<color=#e8d9bb>Illumina Federation, Gannon City, Year 1986</color>",
  ui_story_5082_50820700_73_dialog_content = "Hey, Reinhardt! This training equipment's still covered in dust! You haven't been slacking off, have you?!",
  ui_story_5082_50820700_74_dialog_content = "I'll wipe it down again.",
  ui_story_5082_50820700_75_dialog_content = "My canteen's empty too. Go fill it up while you're at it.",
  ui_story_5082_50820700_76_dialog_content = "Right away.",
  ui_story_5082_50820700_77_dialog_content = "Hey... Don't you think we're going a bit too far with this?",
  ui_story_5082_50820700_78_dialog_content = "What're you talking about? She falsified orders just to make a name for herself, and you still think she deserves better?",
  ui_story_5082_50820700_79_dialog_content = "The commander agrees too...",
  ui_story_5082_50820700_80_dialog_content = "Those guys are going way overboard!",
  ui_story_5082_50820700_81_dialog_content = "Don't get so worked up about this, Cologne. I broke the rules, and now I'm paying for it.",
  ui_story_5082_50820700_82_dialog_content = "Getting dragged down because of me isn't worth it, so just let it go.",
  ui_story_5082_50820700_83_dialog_content = "How could you say that, Reinhardt?! We all knew the truth when we agreed to go with you!",
  ui_story_5082_50820700_84_dialog_content = "You shouldn't be the only one getting punished, and that's exactly what I'm gonna tell the commander!",
  ui_story_5082_50820700_85_dialog_content = "Hey, aren't those guys from the 2nd Legion? I don't remember having to share the training field with those losers today?",
  ui_story_5082_50820700_86_dialog_content = "Seriously? What a drag.",
  ui_story_5082_50820700_87_dialog_content = "And that new guy is still the Battalion Commander. I heard he was in league with Reinhardt when everything happened.",
  ui_story_5082_50820700_88_dialog_content = "They're the ones who raided the equipment cache! A lot of people got hurt because they wanted to hog all the glory!",
  ui_story_5082_50820700_89_dialog_content = "Yeah, but they also saved Undercity 19... Do you think the other rumors about them are true?",
  ui_story_5082_50820700_90_dialog_content = "If they're not, the Grand Marshal would've cleared things up by now. That means whatever we hear about them now is probably true.",
  ui_story_5082_50820700_91_dialog_content = "The rumors are starting to get out of hand, commander. Shouldn't we do something about it?",
  ui_story_5082_50820700_92_dialog_content = "Not at all. They brought this on themselves, after all.",
  ui_story_5082_50820700_93_dialog_content = "I never thought the 2nd Legion's most promising soldier would be like this...",
  ui_story_5082_50820700_94_dialog_content = "They say Commander Pango personally promoted him, but in the end...",
  ui_story_5082_50820700_95_dialog_content = "...",
  ui_story_5082_50820700_96_dialog_content = "I know you can hear them, Commander Barton! The 1st Legion is completely out of line!",
  ui_story_5082_50820700_97_dialog_content = "Just keep moving.",
  ui_story_5082_50820700_98_dialog_content = "...",
  ui_story_5082_50820700_99_dialog_content = "What do you think you're doing?",
  ui_story_5082_50820700_100_dialog_content = "Are you just gonna stand around and watch?",
  ui_story_5082_50820700_101_dialog_content = "Is all of this totally fair and acceptable?",
  ui_story_5082_50820700_102_dialog_content = "...",
  ui_story_5082_50820700_103_dialog_content = "... Hmph!",
  ui_story_5082_50820700_104_dialog_content = "Barton!",
  ui_story_5082_50820700_105_dialog_content = "We did nothing wrong!",
  ui_story_5082_50820700_106_dialog_content = "?",
  ui_story_5082_50820700_107_dialog_content = "<color=#e8d9bb>In the sudden silence, she marches through the crowd with her head held high and stands at the center of the commotion.</color>",
  ui_story_5082_50820700_108_dialog_content = "You're all a bunch of worthless puppets.",
  ui_story_5082_50820700_109_dialog_content = "If anyone's guilty of wrongdoing, it's you people!",
  ui_story_5082_50820700_110_dialog_content = "Was I wrong for not wanting to leave my comrades behind?",
  ui_story_5082_50820700_111_dialog_content = "Was I wrong for wanting to save the people who were left out to die?!",
  ui_story_5082_50820700_112_dialog_content = "You—",
  ui_story_5082_50820700_113_dialog_content = "Use your heads and think about what you would've done! Or have you people lost the ability to do that?",
  ui_story_5082_50820700_114_dialog_content = "We fight to defeat the Eclipsites and to protect our allies.",
  ui_story_5082_50820700_115_dialog_content = "And yet, some people think we should be punished for doing what they're always too scared to do.",
  ui_story_5082_50820700_116_dialog_content = "The only thing any of you are good for now is obeying.",
  ui_story_5082_50820700_117_dialog_content = "That's why all it takes is a single command to make you turn against your comrades-in-arms and send them to their deaths.",
  ui_story_5082_50820700_118_dialog_content = "...",
  ui_story_5082_50820700_119_dialog_content = "I'll say it again.",
  ui_story_5082_50820700_120_dialog_content = "We did nothing wrong.",
  ui_story_5082_50820700_121_dialog_content = "And if we had to do it all over again, we'd make the exact same choice.",
  ui_story_5082_50820700_122_dialog_content = "That's because you or I could be the next ones trapped in a hopeless situation.",
  ui_story_5082_50820700_123_dialog_content = "But as long as we're allies, none of us have the right or reason to turn our backs on each other without even trying!",
  ui_story_5082_50820700_124_dialog_content = "I'll say it one last time!",
  ui_story_5082_50820700_125_dialog_content = "Yes, we violated our orders, but we—",
  ui_story_5082_50820700_126_dialog_content = "Did nothing wrong!",
  ui_story_5082_50820700_127_dialog_content = "...",
  ui_story_5082_50820700_128_dialog_content = "Got anything else to say, Barton?",
  ui_story_5082_50820700_129_dialog_content = "Hmph.",
  ui_story_5082_50820700_130_dialog_content = "<color=#e8d9bb>Without a word, Barton marches through the crowd as it parts before him, and stands opposite of her.</color>",
  ui_story_5082_50820700_131_dialog_content = "I'm not as good at talking as you are, but right now, there's no need for any more words.",
  ui_story_5082_50820700_132_dialog_content = "<color=#e8d9bb>Barton puffs out his chest.</color>",
  ui_story_5082_50820700_133_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_134_dialog_content = "Heh, no need for more words, huh?",
  ui_story_5082_50820700_135_dialog_content = "<color=#e8d9bb>She takes a deep breath, and matches his intensity with her own call.</color>",
  ui_story_5082_50820700_136_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_137_dialog_content = "<color=#e8d9bb>The soldiers surrounding them glance at one another, unsure of what they should do. The two continue to stand their ground, as though the heavens themselves couldn't make them budge.</color>",
  ui_story_5082_50820700_138_dialog_content = "<color=#e8d9bb>Before anyone comes to their senses, two more figures emerge from the crowd.</color>",
  ui_story_5082_50820700_139_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_140_dialog_content = "<color=#e8d9bb>After them, the ones who fought in that battle step forth.</color>",
  ui_story_5082_50820700_141_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_142_dialog_content = "<color=#e8d9bb>Before long, more and more people join the chanting.</color>",
  ui_story_5082_50820700_143_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_144_dialog_content = "<color=#e8d9bb>The space that once divided the crowd is now filled with soldiers united under a single cause.</color>",
  ui_story_5082_50820700_145_dialog_content = "<color=#e8d9bb>Those who had fought together, and those who had not.</color>",
  ui_story_5082_50820700_146_dialog_content = "<color=#e8d9bb>Those who knew each other by name and those who were complete strangers.</color>",
  ui_story_5082_50820700_147_dialog_content = "<color=#e8d9bb>Every soldier stood proudly among their peers.</color>",
  ui_story_5082_50820700_148_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_149_dialog_content = "Splendor Illumina!!!",
  ui_story_5082_50820700_150_dialog_content = "What should we do, commander? The crowd's going to lose control at this rate.",
  ui_story_5082_50820700_151_dialog_content = "... So now she's playing the hero, eh?",
  ui_story_5082_50820700_152_dialog_content = "Settle down, all of you!!!",
  ui_story_5082_50820700_153_dialog_content = "...",
  ui_story_5082_50820700_154_dialog_content = "Battalion Commander Barton! Pango's preferential treatment of you doesn't apply outside of the 2nd Legion, so please refrain from interrupting the 1st Legion's training any further.",
  ui_story_5082_50820700_155_dialog_content = "Attention, all members of the 1st Legion! As punishment for your actions today, you are hereby assigned to clean every single training field in Gannon City, effective immediately!",
  ui_story_5082_50820700_156_dialog_content = "That punishment's completely unreasonable!",
  ui_story_5082_50820700_157_dialog_content = "You will follow your orders, soldier!!!",
  ui_story_5082_50820700_158_dialog_content = "Once cleaning is complete, the entire 1st Legion will be reorganized and prohibited from participating in any future military events.",
  ui_story_5082_50820801_1_dialog_content = "When I think back on it... Everyone was just going with the flow, but she was the one who voiced the words that were in their hearts.",
  ui_story_5082_50820801_2_dialog_content = "Hang on, what do you mean by that?",
  ui_story_5082_50820801_3_dialog_content = "I don't remember any girl in red back then!",
  ui_story_5082_50820801_4_dialog_content = "I'll never forget a moment of what happened that day. The one who said all of those words was you, Reinhardt!",
  ui_story_5082_50820801_5_dialog_content = "... Me?",
  ui_story_5082_50820801_6_dialog_content = "You didn't lose your memories in that laboratory explosion, did you? In all my years of knowing you, I've never seen anyone like the person you're describing.",
  ui_story_5082_50820801_7_dialog_content = "But these memories... The further we go into this base, the more they keep resurfacing... And they don't seem fake at all.",
  ui_story_5082_50820801_8_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5082_50820801_9_dialog_content = "Agh, darn it...",
  ui_story_5082_50820801_10_dialog_content = "Watch your step! This place is covered in old and busted electronics, so try not to trip on them.",
  ui_story_5082_50820801_11_dialog_content = "Here, watch closely! The next time you're about to fall over, just spring forward like this, and...",
  ui_story_5082_50820801_12_dialog_content = "Thanks Philyshy, but I'm pretty sure only a cat can pull that off...",
  ui_story_5082_50820801_13_dialog_content = "Hey, this thing I tripped on... Why does it look like it's supposed to be worn on your head?",
  ui_story_5082_50820801_14_dialog_content = "Meow! I've seen this before!",
  ui_story_5082_50820801_15_dialog_content = "Doctor Chandra used this thing to treat me and Yumi in the very beginning. She said it was pretty valuable too.",
  ui_story_5082_50820801_16_dialog_content = "Apparently there aren't many like it, and they were used to train Illumina's elite soldiers.",
  ui_story_5082_50820801_17_dialog_content = "There's one over here too. They're damaged beyond repair, but the original design can still be seen from the remaining parts.",
  ui_story_5082_50820801_18_dialog_content = "Let me take a look...",
  ui_story_5082_50820801_19_dialog_content = "Wait...",
  ui_story_5082_50820801_20_dialog_content = "<color=#e8d9bb>The group only manages to see the device briefly before Barton stomps it into pieces.</color>",
  ui_story_5082_50820801_21_dialog_content = "... There's no way something like this could be used to train elite soldiers, right?",
  ui_story_5082_50820801_22_dialog_content = "Are these things really that rare and valuable? Because we already managed to find three of them here.",
  ui_story_5082_50820801_23_dialog_content = "This one's still mostly intact, but it's covered in rust... Huh?",
  ui_story_5082_50820801_24_dialog_content = "This machine...",
  ui_story_5082_50820801_25_dialog_content = "... I can sense life flowing through it.",
  ui_story_5082_50820801_26_dialog_content = "!",
  ui_story_5082_50820801_27_dialog_content = "Ugh...",
  ui_story_5082_50820801_28_dialog_content = "Reinhardt?!",
  ui_story_5082_50820801_29_option_content = "Force Boost!",
  ui_story_5082_50820801_30_dialog_content = "...",
  ui_story_5082_50820801_31_dialog_content = "Vital signs are no longer detected...",
  ui_story_5082_50820801_32_dialog_content = "<color=#e8d9bb>Glub, glub, glub...</color>",
  ui_story_5082_50820801_33_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820801_34_dialog_content = "The bugle... It's time for training.",
  ui_story_5082_50820801_35_dialog_content = "Roar!",
  ui_story_5082_50820801_36_dialog_content = "Grand Marshal!",
  ui_story_5082_50820801_37_dialog_content = "This machine... I've seen it before... I've worn it...",
  ui_story_5082_50820801_38_dialog_content = "But... Why...",
  ui_story_5082_50820801_39_dialog_content = "Hang in there, Grand Marshal!",
  ui_story_5082_50820801_40_dialog_content = "PlayerName! Get rid of that thing!",
  ui_story_5082_50820801_41_dialog_content = "Wait, that presence just now... Did you remember something, Reinhardt?",
  ui_story_5082_50820801_42_dialog_content = "It's vague, but it definitely has something to do with that thing... It's up to you now, PlayerName...",
  ui_story_5082_50820801_43_dialog_content = "Grand Marshal...!",
  ui_story_5082_50820801_44_dialog_content = "This is very important to me, Vivian.",
  ui_story_5082_50820801_45_dialog_content = "Stay on your toes, everyone. I need you to keep those monsters away from us.",
  ui_story_5082_50820801_46_dialog_content = "I'm about to enter Reinhardt's consciousness to find out what's behind this weird device.",
  ui_story_5082_50820901_1_dialog_content = "(It looks like I'm in an Illumina laboratory, but it feels so oppressive here.)",
  ui_story_5082_50820901_2_dialog_content = "Subject #1, please enter rooms one through three and use your Luminatics according to their instructions.",
  ui_story_5082_50820901_3_dialog_content = "Understood.",
  ui_story_5082_50820901_4_dialog_content = "Subject #2, please enter rooms one through three and use your Luminatics according to their instructions.",
  ui_story_5082_50820901_5_dialog_content = "...",
  ui_story_5082_50820901_6_dialog_content = "(What are they doing?)",
  ui_story_5082_50820901_7_dialog_content = "Subject #2, please comply with your orders.",
  ui_story_5082_50820901_8_dialog_content = "I would like to know the true purpose of this experiment.",
  ui_story_5082_50820901_9_dialog_content = "If my mastery of Luminatics is the subject of testing, I should be made aware of the testing environment in order to make any necessary adjustments.",
  ui_story_5082_50820901_10_dialog_content = "This would be preferable to me simply unleashing my Lumina in a dark room without a clear goal in mind.",
  ui_story_5082_50820901_11_dialog_content = "Just know that this experiment will help you on your path to becoming a researcher, Denier.",
  ui_story_5082_50820901_12_dialog_content = "...",
  ui_story_5082_50820901_13_dialog_content = "Subject #3, please enter rooms one through three and use your Luminatics according to their instructions.",
  ui_story_5082_50820901_14_dialog_content = "I wasn't told about any changes to my training today.",
  ui_story_5082_50820901_15_dialog_content = "We have no obligation to disclose any information to you. It's nothing more than a small series of tests, now please comply.",
  ui_story_5082_50820901_16_dialog_content = "I think I have the right to know about anything that pertains to me.",
  ui_story_5082_50820901_17_dialog_content = "PlayerName?",
  ui_story_5082_50820901_18_dialog_content = "Are you feeling better? You really scared me just now...",
  ui_story_5082_50820901_19_dialog_content = "What kind of experiment was that? And why were all three of you there?",
  ui_story_5082_50820901_20_dialog_content = "\"All three of us\"? What do you mean?",
  ui_story_5082_50820901_21_dialog_content = "You didn't see yourself just now? You were standing right here...",
  ui_story_5082_50820901_22_dialog_content = "I didn't...",
  ui_story_5082_50820901_23_dialog_content = "<color=#e8d9bb>Reinhardt pauses for a moment, her brow furrowed in thought. She takes two steps forward and stands where she stood in her memory.</color>",
  ui_story_5082_50820901_24_dialog_content = "What did you see, PlayerName?",
  ui_story_5082_50820901_25_dialog_content = "I saw you as well as your past self in her academy uniform.",
  ui_story_5082_50820901_26_dialog_content = "But I saw someone else.",
  ui_story_5082_50820901_27_dialog_content = "A girl with short and messy black hair, whose sharp eyes looked like they were ready to challenge anyone.",
  ui_story_5082_50820901_28_dialog_content = "She had scars all over her hands and arms, but she didn't bother covering them at all. She wore a red shirt and a coat draped over her shoulders like a cape.",
  ui_story_5082_50820901_29_dialog_content = "She looked so lawless and unfettered, like a raging fire that threatened to burn everything in its path. A terrifying sight—",
  ui_story_5082_50820901_30_dialog_content = "And yet somehow it felt so liberating.",
  ui_story_5082_50820901_31_dialog_content = "So that glowing-red girl you mentioned before...",
  ui_story_5082_50820901_32_dialog_content = "That's right.",
  ui_story_5082_50820901_33_dialog_content = "To be honest, I'm having trouble believing it as well. But after seeing this memory, there's no denying it any longer.",
  ui_story_5082_50820901_34_dialog_content = "That girl—",
  ui_story_5082_50820901_35_dialog_content = "Is me.",
  ui_story_5082_50820901_36_dialog_content = "(The scene is changing again.)",
  ui_story_5082_50820901_37_dialog_content = "All test subjects, please make any necessary adjustments to your equipment and concentrate.",
  ui_story_5082_50820901_38_dialog_content = "Those three machines... They look like the ones we just found.",
  ui_story_5082_50820901_39_dialog_content = "So you guys wore them in the past. No wonder Philyshy said they were used to train elite soldiers.",
  ui_story_5082_50820901_40_dialog_content = "But why did I have no recollection of these things...?",
  ui_story_5082_50820901_41_dialog_content = "Urgh... Why does my head hurt so much? Could it have something to do with these machines?",
  ui_story_5082_50820901_42_dialog_content = "A device that stimulates the brain to trigger hidden potential...",
  ui_story_5082_50820901_43_dialog_content = "If they mess with my brain, they'd better be ready to pay for it—!",
  ui_story_5082_50820901_44_dialog_content = "Wait a minute, this isn't my heartbeat! These complicated emotions aren't mine either... Do I hear something? No... I feel it...",
  ui_story_5082_50820901_45_dialog_content = "I feel someone else's presence.",
  ui_story_5082_50820901_46_dialog_content = "... Sister?",
  ui_story_5082_50820901_47_dialog_content = "... Denier.",
  ui_story_5082_50820901_48_dialog_content = "I never expected to have a conversation with you like this.",
  ui_story_5082_50820901_49_dialog_content = "Or to have it here, of all places... What are you doing here?",
  ui_story_5082_50820901_50_dialog_content = "The ability to sense other people's thoughts and emotions... Are they trying to replicate the power of the Caelestites?",
  ui_story_5082_50820901_51_dialog_content = "But if you're here, that means someone else should also be here.",
  ui_story_5082_50820901_52_dialog_content = "What is this?!",
  ui_story_5082_50820901_53_dialog_content = "Looks like I was right.",
  ui_story_5082_50820901_54_dialog_content = "... They said they wanted to test our control of Luminatics, but this has nothing to do with that.",
  ui_story_5082_50820901_55_dialog_content = "Maybe they're trying to improve our combat efficiency as a cohesive unit?",
  ui_story_5082_50820901_56_dialog_content = "If only it were that simple. Aren't you guys curious about why they chose the three of us?",
  ui_story_5082_50820901_57_dialog_content = "...",
  ui_story_5082_50820901_58_dialog_content = "Also, the researchers probably mentioned that there would be more tests like this, right?",
  ui_story_5082_50820901_59_dialog_content = "I haven't forgotten what Reinhardt looked like after she came back from those so-called \"tests.\"",
  ui_story_5082_50820901_60_dialog_content = "We're nowhere near as powerful as Reinhardt, so maybe our tests won't be so... Urgh!",
  ui_story_5082_50820901_61_dialog_content = "Helios?!",
  ui_story_5082_50820901_62_dialog_content = "I don't sense his consciousness anymore. Maybe he—Ack!",
  ui_story_5082_50820901_63_dialog_content = "Denier! What's going on?!",
  ui_story_5082_50820901_64_dialog_content = "Roar!",
  ui_story_5082_50820901_65_dialog_content = "... You guys are the next part of their \"small series of tests,\" aren't you?",
  ui_story_5082_50820902_1_dialog_content = "(After that day, I noticed that I was constantly being followed, no matter where I went.)",
  ui_story_5082_50820902_2_dialog_content = "...",
  ui_story_5082_50820902_3_dialog_content = "Phew, today's contenders were pretty tough.",
  ui_story_5082_50820902_4_dialog_content = "See? I told you she'd be fine. She said she wouldn't stand us up again, remember?",
  ui_story_5082_50820902_5_dialog_content = "So did you run into any trouble, Reinhardt?",
  ui_story_5082_50820902_6_dialog_content = "Nah, just being constantly watched as usual. What about you two? Ever since the experiment ended, I haven't seen you speak to one another.",
  ui_story_5082_50820902_7_dialog_content = "...",
  ui_story_5082_50820902_8_dialog_content = "If there's something on your mind, you should talk about it. Knowing the truth is the only way we can make the right decisions.",
  ui_story_5082_50820902_9_dialog_content = "... You're right. We grew up together, and we shouldn't keep secrets about this from each other.",
  ui_story_5082_50820902_10_dialog_content = "The truth is, my head has been hurting ever since the experiment that day.",
  ui_story_5082_50820902_11_dialog_content = "For some reason, I was never included in group activities for my scout training anymore. Even my commander won't give me a straight answer when I ask about it.",
  ui_story_5082_50820902_12_dialog_content = "Have you gotten yourself checked out yet?",
  ui_story_5082_50820902_13_dialog_content = "They said there's nothing wrong with me, and that I shouldn't worry so much since it doesn't seriously impact my life or combat abilities.",
  ui_story_5082_50820902_14_dialog_content = "What about you, Denier?",
  ui_story_5082_50820902_15_dialog_content = "... This place has been discovered.",
  ui_story_5082_50820902_16_dialog_content = "!",
  ui_story_5082_50820902_17_dialog_content = "It's my fault.",
  ui_story_5082_50820902_18_dialog_content = "I was in need of some materials, so I reached out to my superiors with a proposition for a project that I was working on, but they ignored me.",
  ui_story_5082_50820902_19_dialog_content = "And then just a few days ago, my project suddenly got completely rejected. They tracked me all the way here on suspicion of carrying out dangerous experiments.",
  ui_story_5082_50820902_20_dialog_content = "I was ordered to shut down the laboratory and hand over all of my equipment and research.",
  ui_story_5082_50820902_21_dialog_content = "That's not an issue. We built this place before, and we can build it again.",
  ui_story_5082_50820902_22_dialog_content = "Losing your research is the real loss here... Which reminds me, what were you even working on here?",
  ui_story_5082_50820902_23_dialog_content = "... We have something more important to talk about right now.",
  ui_story_5082_50820902_24_dialog_content = "\"No test subjects have successfully completed this program, but your data may be the key to a scientific breakthrough for Illumina.\"",
  ui_story_5082_50820902_25_dialog_content = "\"Write down everything you experience during this experiment... What you hear... What you feel...\"",
  ui_story_5082_50820902_26_dialog_content = "\"Whether you seek promotion or access to the most cutting-edge technology available, all will be within your reach.\"",
  ui_story_5082_50820902_27_dialog_content = "You two were also told something along these lines after that experiment, right?",
  ui_story_5082_50820902_28_dialog_content = "...",
  ui_story_5082_50820902_29_dialog_content = "So now it's time to decide. All in favor of rejecting their promises of greatness and purposefully failing their experiment, raise your hand.",
  ui_story_5082_50820902_30_dialog_content = "What Denier said that day made me realize that the three of us are connected by this experiment.",
  ui_story_5082_50820902_31_dialog_content = "I don't know what their goal is, but I'm worried that my results are going to pose a risk for you two.",
  ui_story_5082_50820902_32_dialog_content = "That's why I can't and won't make any decisions about this on my own.",
  ui_story_5082_50820902_33_dialog_content = "<color=#e8d9bb>Helios raises his hand.</color>",
  ui_story_5082_50820902_34_dialog_content = "I still have more to say too.",
  ui_story_5082_50820902_35_dialog_content = "Hang on, it's my turn to speak. I'm an expert when it comes to getting \"tested,\" so a lot of this stuff is second nature to me now.",
  ui_story_5082_50820902_36_dialog_content = "As long as you keep showing them your limits, they'll keep pushing you to exceed them.",
  ui_story_5082_50820902_37_dialog_content = "They'll even drag your friends into it. No price is too great in their eyes, not even our very lives.",
  ui_story_5082_50820902_38_dialog_content = "<color=#e8d9bb>Reinhardt raises her hand.</color>",
  ui_story_5082_50820902_39_dialog_content = "I've been doing a little investigating of my own these last few days.",
  ui_story_5082_50820902_40_dialog_content = "To increase Illumina's military strength, they're going to begin experiments to activate a Colossus known as \"Spearhead.\"",
  ui_story_5082_50820902_41_dialog_content = "A Colossus...",
  ui_story_5082_50820902_42_dialog_content = "You've heard about it, right? They excavated it from one of the nearby Undercities. Apparently, it even predates the Eraveil Colossi.",
  ui_story_5082_50820902_43_dialog_content = "It's possible that the experiment's goal was to find a suitable pilot for the Colossus.",
  ui_story_5082_50820902_44_dialog_content = "But I don't feel like wasting time on pointless experiments, and I definitely don't want them getting in the way of our daily meetings.",
  ui_story_5082_50820902_45_dialog_content = "So—",
  ui_story_5082_50820902_46_dialog_content = "<color=#e8d9bb>Denier raises her hand.</color>",
  ui_story_5082_50820902_47_dialog_content = "We're all in agreement.",
  ui_story_5082_50820902_48_dialog_content = "Congratulations, everyone. The Navigator selection experiment is already a complete and utter failure.",
  ui_story_5082_50820902_49_dialog_content = "Which means we're free to do what we have to do now. Let's call it for today.",
  ui_story_5082_50820902_50_dialog_content = "Could I please have another second? I still have more to say, and I think it might be related to our situation.",
  ui_story_5082_50820902_51_dialog_content = "I haven't had much to do lately, and I've been thinking about that experiment, so I decided to investigate that laboratory.",
  ui_story_5082_50820902_52_dialog_content = "The tests they ran on us were only in a small section of the lab. The entire facility is a lot bigger than we imagined.",
  ui_story_5082_50820902_53_dialog_content = "That explains why they had to build it in one of the neighboring Undercities. Aside from the research sector, the lab has an unusually well-stocked medical center and fully functional equipment.",
  ui_story_5082_50820902_54_dialog_content = "Security was tight, so I wasn't able to get a better look inside.",
  ui_story_5082_50820902_55_dialog_content = "But judging from the amount of food being allocated to the facility, my guess is that they're keeping a lot of patients in there.",
  ui_story_5082_50820902_56_dialog_content = "So you're saying that your headaches aren't unique to you, and that other people might have required hospitalization for their own symptoms?",
  ui_story_5082_50820902_57_dialog_content = "Maybe, but the thing I want to mention most...",
  ui_story_5082_50820902_58_dialog_content = "I've seen people taking children in and out of the nursery there.",
  ui_story_5082_50820902_59_dialog_content = "It's scary to think about, but due to the repeated failures of adult test subjects, it's possible that they've started taking their research in a different direction...",
  ui_story_5082_50820902_60_dialog_content = "Do you mean they're experimenting with orphans now?!",
  ui_story_5082_50820902_61_dialog_content = "Sit down, Reinhardt.",
  ui_story_5082_50820902_62_dialog_content = "Everything we've spoken about today was supposed to stay classified.",
  ui_story_5082_50820902_63_dialog_content = "You know how things are right now; there's no room for us to play heroes when we can't even guarantee our own safety.",
  ui_story_5082_50820902_64_dialog_content = "So just calm down. The experiment that day gave me a few ideas on how to further my research and solve our problem.",
  ui_story_5082_50820902_65_dialog_content = "With any luck, it'll be able to protect us, and even get us out of this place for good. But right now...",
  ui_story_5082_50820902_66_dialog_content = "As someone who's been through countless \"special training\" sessions, I know from personal experience that no ordinary person can survive this kind of hell!",
  ui_story_5082_50820902_67_dialog_content = "They took me to all kinds of hidden locations for my \"tests,\" including abandoned buildings and old battlefields..",
  ui_story_5082_50820902_68_dialog_content = "I'll mark their exact locations on a map. You might be able to use one of those places as a temporary lab.",
  ui_story_5082_50820902_69_dialog_content = "But it's possible that you'll have to go there alone.",
  ui_story_5082_50820902_70_dialog_content = "Didn't you hear anything I just said?",
  ui_story_5082_50820902_71_dialog_content = "It's very likely that your \"training\" was in service of an even larger goal—",
  ui_story_5082_50820902_72_dialog_content = "Even so!",
  ui_story_5082_50820902_73_dialog_content = "Sister...",
  ui_story_5082_50820902_74_dialog_content = "I understand your concern, Denier. But running away won't solve anything.",
  ui_story_5082_50820902_75_dialog_content = "Are you willing to help me do a little more investigating, Helios?",
  ui_story_5082_50820902_76_dialog_content = "You don't even have to ask. But if our assumptions are correct, what are you prepared to do about it?",
  ui_story_5082_50820902_77_dialog_content = "What do you think?",
  ui_story_5082_50820902_78_dialog_content = "S-Say we manage to rescue the people inside... What then?",
  ui_story_5082_50820902_79_dialog_content = "I haven't planned that far ahead.",
  ui_story_5082_50820902_80_dialog_content = "But if I just stand aside, knowing these terrible things are happening...",
  ui_story_5082_50820902_81_dialog_content = "Then what would be the point of all my efforts up until this point?",
  ui_story_5082_50820902_82_dialog_content = "I want to make Grand Marshal and become Illumina's strongest soldier someday. Whenever disaster strikes, I want to be at the forefront of battle and protect everyone.",
  ui_story_5082_50820902_83_dialog_content = "I don't want to be someone who hesitates when her allies are in danger, or cowers in the face of a new threat—",
  ui_story_5082_50820902_84_dialog_content = "And I refuse to be complicit in the self-aggrandizing schemes of people who experiment on little children.",
  ui_story_5082_50820902_85_dialog_content = "If Illumina's leaders are all like this, then I need to ask them...",
  ui_story_5082_50820902_86_dialog_content = "When they chant Splendor Illumina while sending our frontline soldiers to their deaths, or kidnapping and torturing innocent people...",
  ui_story_5082_50820902_87_dialog_content = "Is it just to ensure the stability of their interests?",
  ui_story_5082_50820902_88_dialog_content = "Wait, Reinhardt! Do you even know what you're saying?",
  ui_story_5082_50820902_89_dialog_content = "The upper brass already sees you as an extremist and a threat after you falsified orders last time.",
  ui_story_5082_50820902_90_dialog_content = "Are you actually going to betray Illumina this time?!",
  ui_story_5082_50820902_91_dialog_content = "Betray? Not at all.",
  ui_story_5082_50820902_92_dialog_content = "The real traitors are the cowards in charge of the military and the fools who obey them.",
  ui_story_5082_50820902_93_dialog_content = "The real traitors are the people who experiment on innocent children, as well as the people who just stand by and let it happen.",
  ui_story_5082_50820902_94_dialog_content = "I refuse to go along with this, and I refuse to only think of my own safety.",
  ui_story_5082_50820902_95_dialog_content = "Denier, Helios, I'm sorry for wrapping you both in this mess.",
  ui_story_5082_50820902_96_dialog_content = "But if I compromise my ideals to preserve the status quo, I'll never accomplish my dreams.",
  ui_story_5082_50820902_97_dialog_content = "Which is why I'm going to do everything in my power to overthrow this rotten, hypocritical system.",
  ui_story_5082_50821001_1_dialog_content = "I can't believe it... The Grand Marshal herself actually tried to overthrow Illumina in the past?!",
  ui_story_5082_50821001_2_dialog_content = "The strange telepathic link between those three augmented soldiers was no accident at all...",
  ui_story_5082_50821001_3_dialog_content = "They thought they'd be safe as long as they kept the results of their research hidden, but it only attracted the attention of their superiors even more.",
  ui_story_5082_50821001_4_dialog_content = "Overthrowing Illumina... was a bold undertaking, to say the least...",
  ui_story_5082_50821001_5_dialog_content = "But when she realized that her potential was real, and that her power was the result of a carefully constructed plan, she knew she could do it.",
  ui_story_5082_50821001_6_dialog_content = "... You talk about your past self as though she was a completely different person.",
  ui_story_5082_50821001_7_dialog_content = "That's because as far as I'm concerned, she is a totally different person.",
  ui_story_5082_50821001_8_dialog_content = "The academy, the training and experiments, the nursery... All this time, I thought my memories of these things were complete.",
  ui_story_5082_50821001_9_dialog_content = "I would notice tiny lapses in my memories from time to time, but I never knew there were so many unfamiliar details hidden within them.",
  ui_story_5082_50821001_10_dialog_content = "Especially the test all three of us went through. It seems as though my memories of that day were completely erased.",
  ui_story_5082_50821001_11_dialog_content = "Could it be that my memories of the past are entirely different from what actually happened...?",
  ui_story_5082_50821001_12_dialog_content = "I'm sure Vice feels the same way about it too...",
  ui_story_5082_50821001_13_dialog_content = "Good thing we were able to glean a bit of the truth from these machines, right?",
  ui_story_5082_50821001_14_dialog_content = "Since you were also chosen for their experiments, it's likely that you lost your memories for a similar reason.",
  ui_story_5082_50821001_15_dialog_content = "Not quite. After seeing my past, you should know that I wasn't chosen to pilot the Colossus. My memories don't indicate otherwise anyway.",
  ui_story_5082_50821001_16_dialog_content = "All the same, I'd really like to know what happened to her next.",
  ui_story_5082_50821001_17_dialog_content = "Your hunches were mostly correct.",
  ui_story_5082_50821001_18_dialog_content = "According to the lab's latest reports, they're officially ready to activate the Spearhead Colossus.",
  ui_story_5082_50821001_19_dialog_content = "The pilot they've currently selected is a four-year-old girl from the nursery—",
  ui_story_5082_50821001_20_dialog_content = "Her compatibility with the backup systems is the highest out of any other test subject.",
  ui_story_5082_50821001_21_dialog_content = "Are you kidding me? They're forcing a little girl to do this?!",
  ui_story_5082_50821001_22_dialog_content = "Don't underestimate her because of her age.",
  ui_story_5082_50821001_23_dialog_content = "Prior to this project, it seems the Committee had been training her for an entire year. It's possible that she has even more experience than any of us.",
  ui_story_5082_50821001_24_dialog_content = "She even achieved a 20% success rate on her initial trial.",
  ui_story_5082_50821001_25_dialog_content = "Denier, you...",
  ui_story_5082_50821001_26_dialog_content = "... Don't put it that way.",
  ui_story_5082_50821001_27_dialog_content = "I'm only being realistic. Have you seen how our fight against the Eclipsites is going?",
  ui_story_5082_50821001_28_dialog_content = "Given the current status of the experiment, risking a single child's life for the sake of countless others yields a high probability of success.",
  ui_story_5082_50821001_29_dialog_content = "That's still no reason to toy with a child's life! We can't wait any longer; we have to do something!",
  ui_story_5082_50821001_30_dialog_content = "Setting aside the question of where to even begin, you only just regained your command privileges. Denier and I are also being isolated from you, which means you have no one else to rely on.",
  ui_story_5082_50821001_31_dialog_content = "Even though I only regained some of my previous privileges, that doesn't mean I'm starting over fresh.",
  ui_story_5082_50821001_32_dialog_content = "The strongest soldiers of the 1st Legion have already agreed to follow me.",
  ui_story_5082_50821001_33_dialog_content = "I'll do my best to shake off surveillance to set up correspondence in one of the nearby Undercities.",
  ui_story_5082_50821001_34_dialog_content = "Reach out to Barton if you need to contact me. He's agreed to help us as well.",
  ui_story_5082_50821001_35_dialog_content = "You may be isolated right now, but that just means you have more freedom to gather information.",
  ui_story_5082_50821001_36_dialog_content = "Denier can handle the lab's progress. In the meantime, Helios, we need you to find out how many more of these secret experiments are being carried out in Illumina.",
  ui_story_5082_50821001_37_dialog_content = "Whether it's the upper echelons of the military or the researchers, we have to be prepared for the worst possible scenario. We're at war, after all.",
  ui_story_5082_50821001_38_dialog_content = "And when I become Grand Marshal, my first order of business will be to fight for the lives of every innocent victim of these experiments.",
  ui_story_5082_50821001_39_dialog_content = "But we still don't know how powerful the Committee is right now. Don't you think this is too risky?",
  ui_story_5082_50821001_40_dialog_content = "If they have another Reinhardt somewhere on standby, our chances of success will be even more slim.",
  ui_story_5082_50821001_41_dialog_content = "Then we'll just go with Plan B.",
  ui_story_5082_50821001_42_dialog_content = "Aurorians can survive just about anywhere, even in an abandoned Undercity...",
  ui_story_5082_50821001_43_dialog_content = "As long as there's enough food, water, space, and light, a settlement for Aurorians to gather can be built.",
  ui_story_5082_50821001_44_dialog_content = "And wherever Aurorians gather, there will always be a need for a Grand Marshal.",
  ui_story_5082_50821001_45_dialog_content = "Hahaha! You're thinking way too far ahead, Denier. I have no intention of letting things get to that point.",
  ui_story_5082_50821001_46_dialog_content = "After all, our original goal was to provide a place of shelter for every crisis-stricken Aurorian...",
  ui_story_5082_50821001_47_dialog_content = "To protect the children who, like us, have no recollection of their own parents and must rely on their fists to survive.",
  ui_story_5082_50821001_48_dialog_content = "...",
  ui_story_5082_50821001_49_dialog_content = "Lots of people in Illumina share the same story, huh...",
  ui_story_5082_50821001_50_dialog_content = "I only knew about Vice before, but after seeing this... I feel so sorry for everyone...",
  ui_story_5082_50821001_51_dialog_content = "No one had it better than anyone back then. I'd wager plenty of people had similar experiences as that four-year-old girl.",
  ui_story_5082_50821001_52_dialog_content = "As for Vice, I'm starting to think... That her memories of these experiments might not be entirely real.",
  ui_story_5082_50821001_53_dialog_content = "You, on the other hand, seem to sympathize a lot with that girl.",
  ui_story_5082_50821001_54_dialog_content = "... So did your plan work out in the end?",
  ui_story_5082_50821001_55_dialog_content = "If you have to ask, then all I can do is remind you that I'm the Grand Marshal of Illumina now.",
  ui_story_5082_50821001_56_dialog_content = "Are we still talking about the same you? Or the same Illumina, for that matter?",
  ui_story_5082_50821001_57_dialog_content = "Is that really important? It's obvious that \"her\" plan ultimately failed, isn't it?",
  ui_story_5082_50821001_58_dialog_content = "I think it's very much important.",
  ui_story_5082_50821001_59_dialog_content = "I'm curious to know the outcome, even though it was all in the past.",
  ui_story_5082_50821001_60_dialog_content = "But what you're saying right now sounds like it's coming from the Reinhardt of today.",
  ui_story_5082_50821001_61_dialog_content = "Part of it implies your victory over \"her,\" while the rest implies \"her\" failure towards Illumina.",
  ui_story_5082_50821001_62_dialog_content = "So I have to ask: where exactly do you stand now, Reinhardt?",
  ui_story_5082_50821001_63_dialog_content = "Would it kill you to be more direct sometimes?",
  ui_story_5082_50821001_64_dialog_content = "I'm only complicating things because this is you we're talking about.",
  ui_story_5082_50821001_65_dialog_content = "Then it sounds like I need to be more honest with you.",
  ui_story_5082_50821001_66_dialog_content = "To tell you the truth, I'm a little confused myself. Do you think that \"Reinhardt\" is more like me, or that I'm more like her?",
  ui_story_5082_50821001_67_dialog_content = "I...",
  ui_story_5082_50821001_68_dialog_content = "You don't need to shy away from the question. I won't be upset regardless of what you say, I promise.",
  ui_story_5082_50821001_69_dialog_content = "Th-That's not what's on my mind.",
  ui_story_5082_50821001_70_dialog_content = "She just seems a lot more free and uninhibited, and...",
  ui_story_5082_50821001_71_dialog_content = "Sorry, I don't really know how best to describe it right now.",
  ui_story_5082_50821001_72_dialog_content = "Don't worry. You've already hit the nail on the head.",
  ui_story_5082_50821001_73_dialog_content = "As you can see, we're a lot different from one another.",
  ui_story_5082_50821001_74_dialog_content = "At any given time, someone in Illumina could be going through the same hell I went through back then.",
  ui_story_5082_50821001_75_dialog_content = "You think that after all these years of seeing the brutality of the Dark Zone for myself, I haven't been changed by it?",
  ui_story_5082_50821001_76_dialog_content = "I thought I hadn't. With all my heart, I wished I hadn't.",
  ui_story_5082_50821001_77_dialog_content = "When I was young, I thought I could shield the entire Federation all on my own.",
  ui_story_5082_50821001_78_dialog_content = "But after losing so many comrades, I started wondering to myself, \"Even if I could protect everyone on my own, how long could it possibly last?\"",
  ui_story_5082_50821001_79_dialog_content = "If someone young and angry like her stood in front of me right now and called me useless and corrupt...",
  ui_story_5082_50821001_80_dialog_content = "And swore to tear me down and build a bright new world in my place...",
  ui_story_5082_50821001_81_dialog_content = "I don't know if I would stop her, support her...",
  ui_story_5082_50821001_82_dialog_content = "Or even...",
  ui_story_5082_50821001_83_dialog_content = "I may not understand the burden of leadership like you do, but as your friend, I know for sure that you're not that kind of person...",
  ui_story_5082_50821001_84_dialog_content = "You're also far from the only one supporting Illumina.",
  ui_story_5082_50821001_85_dialog_content = "I know what you're trying to say, but after seeing her and remembering everything that happened back then... I can't help but feel a little discontent.",
  ui_story_5082_50821001_86_dialog_content = "Still, I'm not afraid to share these things with you. Seeing me like this must be a little disappointing, huh?",
  ui_story_5082_50821001_87_dialog_content = "Not at all...",
  ui_story_5082_50821001_88_dialog_content = "Let's go back. The others must be tired of waiting for us by now.",
  ui_story_5082_50821001_89_dialog_content = "... So the Grand Marshal was seeing herself in her past memories?",
  ui_story_5082_50821001_90_dialog_content = "... What about you, Barton? How much do you know about what happened back then?",
  ui_story_5082_50821001_91_dialog_content = "My understanding is that Reinhardt, Forsakin, and Helios were secretly planning something back then.",
  ui_story_5082_50821001_92_dialog_content = "...",
  ui_story_5082_50821001_93_dialog_content = "I also told you that I would support you no matter what, but I never received word of anything until the very end.",
  ui_story_5082_50821001_94_dialog_content = "I only knew that you were somehow involved in the lab's explosion, but I had no way of investigating the matter at the time.",
  ui_story_5082_50821001_95_dialog_content = "Our hands were already tied with the Darkover Crisis, and there was a world's worth of work to do in the aftermath of the fighting.",
  ui_story_5082_50821001_96_dialog_content = "You still hadn't made commander by the time we saw each other again, but you were already poised to rise far beyond that rank.",
  ui_story_5082_50821001_97_dialog_content = "So even after all of that happened... Reinhardt get promoted again?",
  ui_story_5082_50821001_98_dialog_content = "That's right, and she was a completely different person by then too: steadfast, imposing, and an absolute terror on the battlefield. Her already impressive power seemed to grow with each passing day.",
  ui_story_5082_50821001_99_dialog_content = "Compared to her and her explosive growth, I was just a lowly grunt stomping around in the mud.",
  ui_story_5082_50821001_100_dialog_content = "So while I carried out my missions, I also put myself through my own brand of special training. That's also around the time I started going harder on my subordinates!",
  ui_story_5082_50821001_101_dialog_content = "I see. So that's when the 2nd Legion developed a reputation for its harsh and unforgiving training methods.",
  ui_story_5082_50821001_102_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5082_50821001_103_dialog_content = "Meow! And here I thought it was over already!",
  ui_story_5082_50821001_104_dialog_content = "Why do they keep crashing into the walls?",
  ui_story_5082_50821001_105_dialog_content = "This place is too structurally unstable to withstand their collisions! We need to stop them before the walls come down and bury us alive!",
  ui_story_5082_50821101_1_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5082_50821101_2_dialog_content = "Is everyone alright?",
  ui_story_5082_50821101_3_dialog_content = "I'm good! But I'd rather not take another fall from that height anytime soon.",
  ui_story_5082_50821101_4_dialog_content = "I'm fine, Grand Marshal.",
  ui_story_5082_50821101_5_dialog_content = "What about you, PlayerName?",
  ui_story_5082_50821101_6_dialog_content = "I'm good... Thanks for the save, Barton. I would've gotten squashed just now if it wasn't for you.",
  ui_story_5082_50821101_7_dialog_content = "A little extra training and you wouldn't need to rely on me so much, y'know!",
  ui_story_5082_50821101_8_dialog_content = "When this is all over, I'll be sure to add altitude training to your daily regimen!",
  ui_story_5082_50821101_9_dialog_content = "It looks like we landed at the lowest level of the research facility.",
  ui_story_5082_50821101_10_dialog_content = "Why did they need such an enormous space down here?",
  ui_story_5082_50821101_11_dialog_content = "I can answer that without having to dig into my memories. This is where they kept it.",
  ui_story_5082_50821101_12_dialog_content = "All I see is a pile of huge bones... Wait! This is the Colossus I sensed earlier!",
  ui_story_5082_50821101_13_dialog_content = "... Given its current state, it's no surprise that the Undercity has started to collapse on itself.",
  ui_story_5082_50821101_14_dialog_content = "... Can you still remember what happened during those experiments back then, Reinhardt?",
  ui_story_5082_50821101_15_dialog_content = "My memories of that time aren't entirely clear, but I know for a fact that she never appeared again after I became a Legion Commander.",
  ui_story_5082_50821101_16_dialog_content = "Still, I have a pretty good guess as to what happened here.",
  ui_story_5082_50821101_17_dialog_content = "My memories of that time aren't entirely clear, but I know for a fact that she never appeared again after I became a Legion Commander.",
  ui_story_5082_50821101_18_dialog_content = "Still, I have a pretty good guess as to what happened here.",
  ui_story_5082_50821101_19_dialog_content = "They must've thought that they buried everything, including my past...",
  ui_story_5082_50821101_20_dialog_content = "But she's still lingering here for some reason, as though she wants to tell me something.",
  ui_story_5082_50821101_21_dialog_content = "I think that this place, or rather the accident that took place here, is the last piece of the puzzle related to her.",
  ui_story_5082_50821101_22_dialog_content = "Whatever happened here caused her to separate from my body...",
  ui_story_5082_50821101_23_dialog_content = "And also granted me the overwhelming power that made me the Grand Marshal that I am today.",
  ui_story_5082_50821101_24_dialog_content = "After learning the truth behind the Phospherus Program, I'm not surprised by anything about myself anymore.",
  ui_story_5082_50821101_25_dialog_content = "Ulysses once said that I brought a decade of peace to all of Illumina... Heh, looks like I became their perfect super-soldier after all.",
  ui_story_5082_50821101_26_dialog_content = "...",
  ui_story_5082_50821101_27_dialog_content = "... Let's not jump to any conclusions just yet. We still have plenty of investigating to do.",
  ui_story_5082_50821101_28_dialog_content = "We might even dig up some new evidence proving your power came from discovering your true potential!",
  ui_story_5082_50821101_29_dialog_content = "My fur's standing on end means we're not alone down here!",
  ui_story_5082_50821101_30_dialog_content = "<color=#e8d9bb>Buzz—!</color>",
  ui_story_5082_50821101_31_dialog_content = "(That noise... I know what it is...)",
  ui_story_5082_50821101_32_option_content = "Mind Link!",
  ui_story_5082_50821101_33_dialog_content = "... Spearhead!",
  ui_story_5082_50821101_34_dialog_content = "You came, just as you promised.",
  ui_story_5082_50821101_35_dialog_content = "I didn't promise anything. You're the one who asked me to find you.",
  ui_story_5082_50821101_36_dialog_content = "But now that I'm here, I need to ask you a few questions.",
  ui_story_5082_50821101_37_dialog_content = "I know what you seek. You wish to learn more about a certain girl's past, or the pasts of two different girls.",
  ui_story_5082_50821101_38_dialog_content = "(I knew it! Vice and Reinhardt's lost memories are tied to the Navigator selection experiments that took place here!)",
  ui_story_5082_50821101_39_dialog_content = "Tell me what happened to them back then!",
  ui_story_5082_50821101_40_dialog_content = "What you seek is but a small amount of data stored in this place.",
  ui_story_5082_50821101_41_dialog_content = "But, the data is scattered and fragmented. In my current state of disrepair, I am unable to retrieve it or even see it clearly.",
  ui_story_5082_50821101_42_dialog_content = "Are you asking me to help you retrieve it?",
  ui_story_5082_50821101_43_dialog_content = "You are the one searching for the data, not I.",
  ui_story_5082_50821101_44_dialog_content = "... Then what should I do?",
  ui_story_5082_50821101_45_dialog_content = "The ones who tore me apart attempted to reshape my systems using their outdated technology.",
  ui_story_5082_50821101_46_dialog_content = "As such, I can no longer restore them to their original state, Caelestite.",
  ui_story_5082_50821101_47_dialog_content = "That device, however, will allow you to connect with me and find what you seek.",
  ui_story_5082_50821101_48_dialog_content = "I just have to put it on, right?",
  ui_story_5082_50821101_49_dialog_content = "Wait PlayerName, what are you doing?",
  ui_story_5082_50821101_50_dialog_content = "I just made contact with Spearhead's consciousness. It says that I might be able to find what we're looking for by putting this on.",
  ui_story_5082_50821101_51_dialog_content = "Don't you remember what you told me before we came down here?",
  ui_story_5082_50821101_52_dialog_content = "I do, but with things as they are right now, this is our last remaining clue.",
  ui_story_5082_50821101_53_dialog_content = "We fought so hard to get down here. I don't want everyone's efforts to be in vain.",
  ui_story_5082_50821101_54_dialog_content = "I know it's a little dangerous, but we all have each other's backs, don't we?",
  ui_story_5082_50821101_55_dialog_content = "This is also what I meant when I said you're not the only one supporting Illumina. You can count on us too, Reinhardt.",
  ui_story_5082_50821101_56_dialog_content = "Even if Spearhead tries to do anything, I'm sure everyone here can put a stop to it. After all, Illumina already defeated it once before, right?",
  ui_story_5082_50821101_57_dialog_content = "Well said, kid! I never get tired of seeing you stick up for your friends in their time of need! So what do you say, Grand Marshal?",
  ui_story_5082_50821101_58_dialog_content = "Understood. Just be careful, okay?",
  ui_story_5082_50821101_59_dialog_content = "I will.",
  ui_story_5082_50821101_60_dialog_content = "(So first, I have to put this on my head, and then...)",
  ui_story_5082_50821101_61_option_content = "Psychic–",
  ui_story_5082_50821101_62_dialog_content = "Adjustments to the Colossus are nearly complete. I'll notify the Tech Officer right away.",
  ui_story_5082_50821101_63_dialog_content = "All we need to do now is find a suitable \"Navigator,\" and we can begin testing.",
  ui_story_5082_50821101_64_dialog_content = "Which of the subjects has the highest compatibility?",
  ui_story_5082_50821101_65_dialog_content = "Following the tests we ran on our three previous candidates, they started omitting personal information for the rest of our test subjects. Only their data is visible to us now.",
  ui_story_5082_50821101_66_dialog_content = "I remember those three. Their data was rather promising, if I remember correctly?",
  ui_story_5082_50821101_67_dialog_content = "Indeed. They came from the Artificial Sun project, after all.",
  ui_story_5082_50821101_68_dialog_content = "However, there were notable differences between their performances and the test results. The Committee has reason to suspect that they deliberately misrepresented their capabilities during the experiment.",
  ui_story_5082_50821101_69_dialog_content = "Is that so?",
  ui_story_5082_50821101_70_dialog_content = "Then, regardless of their compatibility with the Colossus, if they're willing to lie to us during testing, we have no use for them.",
  ui_story_5082_50821101_71_dialog_content = "If the Committee finds them guilty of this, they'll need all the luck they can get.",
  ui_story_5082_50821101_72_dialog_content = "(Ugh, I can't stand the way these scientists talk.)",
  ui_story_5082_50821101_73_dialog_content = "(... But I have to keep watching.)",
  ui_story_5082_50821101_74_dialog_content = "When will we get to the part of those two girls, Spearhead?",
  ui_story_5082_50821101_75_dialog_content = "Soon. I promise.",
  ui_story_5082_50821101_76_dialog_content = "Wait for the signal to extend, Caelestite. Search for a special button, and then press it!",
  ui_story_5082_50821101_77_dialog_content = "A special button, huh...",
  ui_story_5082_50821101_78_dialog_content = "There! Quickly, Caelestite!",
  ui_story_5082_50821101_79_dialog_content = "(Why is the scene suddenly...?)",
  ui_story_5082_50821101_80_dialog_content = "Quickly... Press the button! Hurry—!",
  ui_story_5082_50821101_81_dialog_content = "Urgh, my head... What do you think you're doing, Spearhead?!",
  ui_story_5082_50821101_82_dialog_content = "Press the button, and let me be free!",
  ui_story_5082_50821101_83_dialog_content = "As a weapon of Eclipse, I will destroy all Aurorians in the name of my masters!",
  ui_story_5082_50821101_84_dialog_content = "!",
  ui_story_5082_50821101_85_dialog_content = "Death to Illumina! Death to those impudent fools, and especially that man!",
  ui_story_5082_50821101_86_dialog_content = "For leaving me in such a pitiful state... I swore to exact vengeance upon them, even at the cost of my existence!",
  ui_story_5082_50821101_87_dialog_content = "(Such powerful hatred... Am I still in Spearhead's memory files, or is this its actual consciousness?)",
  ui_story_5082_50821101_88_dialog_content = "(... If it's letting me see this, it means the Colossus' mind is already way too unstable.)",
  ui_story_5082_50821101_89_dialog_content = "(This might be my chance to look for its weak spot!)",
  ui_story_5082_50821101_90_option_content = "Telepathic Reach!",
  ui_story_5082_50821101_91_dialog_content = "<color=#e8d9bb>But instead of Spearhead's weak point, a piercing scream rings out even more clearly.</color>",
  ui_story_5082_50821101_92_dialog_content = "(That scream... It's her!)",
  ui_story_5082_50821101_93_dialog_content = "Are you there? Can you hear me?!",
  ui_story_5082_50821101_94_dialog_content = "Reinhardt!",
  ui_story_5082_50821101_95_dialog_content = "That's strange. You're my first-ever visitor to this place.",
  ui_story_5082_50821101_96_dialog_content = "I finally have a chance to talk to you!",
  ui_story_5082_50821101_97_dialog_content = "\"Finally\"?",
  ui_story_5082_50821101_98_dialog_content = "Reinhardt and I... The other you, I mean! We've been looking for you all this time!",
  ui_story_5082_50821101_99_dialog_content = "...",
  ui_story_5082_50821101_100_dialog_content = "The kid's been wearing that thing for a long time now. Why hasn't he moved yet?",
  ui_story_5082_50821101_101_dialog_content = "It's only been about thirty seconds, Commander Barton! Don't be in such a rush!",
  ui_story_5082_50821101_102_dialog_content = "PlayerName said that time flows differently within the subconscious world. Let's just keep waiting.",
  ui_story_5082_50821101_103_dialog_content = "PlayerName put his trust in us, so we should do the same for him.",
  ui_story_5082_50821101_104_dialog_content = "...",
  ui_story_5082_50821101_105_dialog_content = "Meanwhile, we need to be ready for battle at all times if we're going to protect him.",
  ui_story_5082_50821101_106_dialog_content = "Watch your 3 o'clock, Barton!",
  ui_story_5082_50821101_107_dialog_content = "Ha! Just what I was waiting for!",
  ui_story_5082_50821101_108_dialog_content = "<color=#e8d9bb>Bang, bang, bang!</color>",
  ui_story_5082_50821101_109_dialog_content = "<color=#e8d9bb>Suddenly, dozens of small machines come flying out of the remnants of the Colossus.</color>",
  ui_story_5082_50821101_110_dialog_content = "This big guy was only pretending to be dead!",
  ui_story_5082_50821101_111_dialog_content = "Protect PlayerName, and get ready to fight!",
  ui_story_5082_50821201_1_dialog_content = "And that's more or less what's happening outside.",
  ui_story_5082_50821201_2_dialog_content = "Reinhardt? Didn't you hear me?",
  ui_story_5082_50821201_3_dialog_content = "I did.",
  ui_story_5082_50821201_4_dialog_content = "I'm amazed that stubborn fool actually became Grand Marshal.",
  ui_story_5082_50821201_5_dialog_content = "You say that as if you're talking about a different person.",
  ui_story_5082_50821201_6_dialog_content = "It's not that far from the truth. There's a world of differences between us, after all.",
  ui_story_5082_50821201_7_dialog_content = "You're actually sounding a lot like her right now...",
  ui_story_5082_50821201_8_dialog_content = "You must be a Caelestite, right?",
  ui_story_5082_50821201_9_dialog_content = "Me? Y-Yeah, that's right.",
  ui_story_5082_50821201_10_dialog_content = "Think you can use your powers to let me speak to her?",
  ui_story_5082_50821201_11_dialog_content = "I have something I want to tell her.",
  ui_story_5082_50821201_12_dialog_content = "Normally that would be fine, but I'm using one of Spearhead's devices to communicate with you right now.",
  ui_story_5082_50821201_13_dialog_content = "I can't afford to destabilize Spearhead's consciousness even further, or else it'll be even harder to stop.",
  ui_story_5082_50821201_14_dialog_content = "And after discovering its connection to the Eclipsites, bringing Reinhardt in here would be way too dangerous.",
  ui_story_5082_50821201_15_dialog_content = "Which reminds me... What exactly caused you to stay here?",
  ui_story_5082_50821201_16_dialog_content = "So you're saying that if we can divert the Colossus' attention, you'll have a way to work around it?",
  ui_story_5082_50821201_17_dialog_content = "I suppose that's possible... But how are you going to draw Spearhead's attention?",
  ui_story_5082_50821201_18_dialog_content = "Like this, obviously—!",
  ui_story_5082_50821201_19_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5082_50821201_20_dialog_content = "<color=#e8d9bb>As wild flames quickly spread across the entire space, she begins cackling maniacally amid the raging inferno.</color>",
  ui_story_5082_50821201_21_dialog_content = "Ah, it's been so long since I've felt this good!",
  ui_story_5082_50821201_22_dialog_content = "Sorry Colossus, but after hearing that you're friends with the Eclipsites, I don't have a shred of sympathy for you anymore.",
  ui_story_5082_50821201_23_dialog_content = "I can't hurt your physical body, so setting your entire mind on fire will have to do! Hurts, doesn't it?!",
  ui_story_5082_50821201_24_dialog_content = "You! How dare you—!",
  ui_story_5082_50821201_25_dialog_content = "You are nothing but residual data in my consciousness! I can erase your existence whenever I please!",
  ui_story_5082_50821201_26_dialog_content = "The space is disappearing... Spearhead must be deleting the data!",
  ui_story_5082_50821201_27_dialog_content = "Your consciousness is being stored here too, isn't it? Are you sure this is okay?",
  ui_story_5082_50821201_28_dialog_content = "I'll be fine as long as it doesn't catch me.",
  ui_story_5082_50821201_29_dialog_content = "What's that supposed to mean?",
  ui_story_5082_50821201_30_dialog_content = "What I mean is—",
  ui_story_5082_50821201_31_dialog_content = "Run!!!",
  ui_story_5082_50821201_32_dialog_content = "You sounded so confident just now! Is this really the best idea you could come up with?!",
  ui_story_5082_50821201_33_dialog_content = "Hahahaha!",
  ui_story_5082_50821201_34_dialog_content = "Meow!",
  ui_story_5082_50821201_35_dialog_content = "Philyshy! How can you be playing with those things when they're attacking us?!",
  ui_story_5082_50821201_36_dialog_content = "Sorry, they just look like a big, long tail when they link up like that! I couldn't help it!",
  ui_story_5082_50821201_37_dialog_content = "It makes sense when you put it that way. The Colossus must be controlling each of those \"tails\" to attack us...",
  ui_story_5082_50821201_38_dialog_content = "Even if it can't move its body, its command center is still functional enough to attack us with its skeletal remains!",
  ui_story_5082_50821201_39_dialog_content = "Those are my thoughts exactly!",
  ui_story_5082_50821201_40_dialog_content = "Hmph! As far as I'm concerned, this run-down Colossus is only good for wagging its tail at us now!",
  ui_story_5082_50821201_41_dialog_content = "<color=#e8d9bb>Pit, pat, pit, pat—!</color>",
  ui_story_5082_50821201_42_dialog_content = "Huh? PlayerName?!",
  ui_story_5082_50821201_43_dialog_content = "Of all the times to show up— Wait, don't move!",
  ui_story_5082_50821201_44_dialog_content = "<color=#e8d9bb>Crackle—</color>",
  ui_story_5082_50821201_45_dialog_content = "... An electric current?",
  ui_story_5082_50821201_46_dialog_content = "Get away from that tail, Philyshy! Something's not right about it!",
  ui_story_5082_50821201_47_dialog_content = "Buzz—Buzz—",
  ui_story_5082_50821201_48_dialog_content = "The bones are multiplying! Stay on your guards, everyone; the Colossus might attack soon—",
  ui_story_5082_50821201_49_dialog_content = "<color=#e8d9bb>Boom! Boom! Boom!</color>",
  ui_story_5082_50821201_50_dialog_content = "I can smell explosions coming from inside the walls!",
  ui_story_5082_50821201_51_dialog_content = "The structure is going to collapse! We need to clear out these cables and find a place to take cover!",
  ui_story_5082_50821201_52_dialog_content = "But what about PlayerName? Forget it, I'll just carry him myself!",
  ui_story_5082_50821201_53_dialog_content = "Hey! Grand Marshal! Now's not the time to—",
  ui_story_5082_50821201_54_dialog_content = "... I can hear a countdown.",
  ui_story_5082_50821201_55_dialog_content = "Reinhardt!",
  ui_story_5082_50821201_56_dialog_content = "... An electric current, an explosion, and... her screams.",
  ui_story_5082_50821201_57_dialog_content = "Reinhardt!!!",
  ui_story_5082_50821201_58_dialog_content = "The same thing happened back then.",
  ui_story_5082_50821201_59_dialog_content = "<color=#e8d9bb>A nearby wall explodes, sending cables and rocks crashing into the ground.</color>",
  ui_story_5082_50821201_60_dialog_content = "Endless Slash!",
  ui_story_5082_50821201_61_dialog_content = "<color=#e8d9bb>Barton cleaves an enormous piece of falling debris in half before it lands on him.</color>",
  ui_story_5082_50821201_62_dialog_content = "<color=#e8d9bb>He then keeps his momentum going.</color>",
  ui_story_5082_50821201_63_dialog_content = "Barton...",
  ui_story_5082_50821201_64_dialog_content = "Now's not the time for daydreaming! Also, what did you think of my technique just now?",
  ui_story_5082_50821201_65_dialog_content = "Hahaha, it was as ferocious as ever! Thank you, Barton.",
  ui_story_5082_50821201_66_dialog_content = "Thank you for always fighting by my side!",
  ui_story_5082_50821201_67_dialog_content = "It's only natural, isn't it? Now come on, this place is too dangerous for—",
  ui_story_5082_50821201_68_dialog_content = "Don't worry, I'm fine now.",
  ui_story_5082_50821201_69_dialog_content = "I just need to go through what happened back then one last time.",
  ui_story_5082_50821201_70_dialog_content = "<color=#e8d9bb>The building rumbles and crashes as the walls come tumbling down.</color>",
  ui_story_5082_50821201_71_dialog_content = "<color=#e8d9bb>Like the eye of a storm, Reinhardt stands completely unfazed in the center of the chaos; even the air around her looks perfectly still.</color>",
  ui_story_5082_50821201_72_dialog_content = "Go take cover.",
  ui_story_5082_50821201_73_dialog_content = "I still owe this guy a rematch.",
  ui_story_5082_50821202_1_dialog_content = "What is this place...?",
  ui_story_5082_50821202_2_dialog_content = "It's a space created by that device. It uses Spearhead's system data as its foundation.",
  ui_story_5082_50821202_3_dialog_content = "Thanks to you wounding Spearhead from the outside, we safely took cover in here.",
  ui_story_5082_50821202_4_dialog_content = "Your powers are a lot more impressive than I imagined.",
  ui_story_5082_50821202_5_dialog_content = "Not only could you help me control Spearhead's consciousness, but you could also pull her in here as soon as she unleashed her Lumina.",
  ui_story_5082_50821202_6_dialog_content = "It solves the fighting outside while also ensuring that the device's operation remains uninterrupted.",
  ui_story_5082_50821202_7_dialog_content = "I'm sure you'll accomplish even more incredible things with this power in the future.",
  ui_story_5082_50821202_8_dialog_content = "Thanks, but you're the one who came up with this plan... which I still think was way too dangerous! What if your data got deleted?!",
  ui_story_5082_50821202_9_dialog_content = "There's no such thing as a battle without risks.",
  ui_story_5082_50821202_10_dialog_content = "Besides, everything worked out in the end, didn't it?",
  ui_story_5082_50821202_11_dialog_content = "We managed to temporarily put a stop to the fighting, and I was able to learn more about your Caelestite abilities.",
  ui_story_5082_50821202_12_dialog_content = "And now that I know I can trust you, I can safely say...",
  ui_story_5082_50821202_13_dialog_content = "That this person hasn't changed much from how I remember her.",
  ui_story_5082_50821202_14_dialog_content = "Long time no see, Reinhardt.",
  ui_story_5082_50821202_15_dialog_content = "It feels a little strange to hear that, considering I only started to remember you today...",
  ui_story_5082_50821202_16_dialog_content = "But long time no see, Reinhardt.",
  ui_story_5082_50821202_17_dialog_content = "Uh, Reinhardt...?",
  ui_story_5082_50821202_18_dialog_content = "Yes?",
  ui_story_5082_50821202_19_dialog_content = "...",
  ui_story_5082_50821202_20_dialog_content = "Hahahaha! If it makes things any easier, you can call me \"Renegade\"!",
  ui_story_5082_50821202_21_dialog_content = "That's what everyone used to call me behind my back. I know they didn't mean anything good by it, but I always liked the name.",
  ui_story_5082_50821202_22_dialog_content = "I just don't know if you still remember any of that, Reinhardt.",
  ui_story_5082_50821202_23_dialog_content = "I see. You're not sure if I'm still the same person you once knew, and I only just remembered that you even existed.",
  ui_story_5082_50821202_24_dialog_content = "So why don't we get to know each other again?",
  ui_story_5082_50821202_25_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5082_50821202_26_dialog_content = "What does this rumbling mean, PlayerName?",
  ui_story_5082_50821202_27_dialog_content = "It's Spearhead... It found us!",
  ui_story_5082_50821202_28_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5082_50821202_29_option_content = "Force Boost!",
  ui_story_5082_50821202_30_dialog_content = "It was you people!",
  ui_story_5082_50821202_31_dialog_content = "You were the ones who destroyed my body! You were the ones who buried me alive for thirteen years!",
  ui_story_5082_50821202_32_dialog_content = "Now die—!",
  ui_story_5082_50821202_33_option_content = "Force Boost!",
  ui_story_5082_50821202_34_dialog_content = "Urgh!",
  ui_story_5082_50821202_35_dialog_content = "I can make a barrier to keep Spearhead at bay for now, but this is still its domain.",
  ui_story_5082_50821202_36_dialog_content = "Despite how chaotic its consciousness has gotten, I still might not be able to keep this up for long—",
  ui_story_5082_50821202_37_dialog_content = "Who's asking you to stop it?",
  ui_story_5082_50821202_38_dialog_content = "If someone hits you, shouldn't your first reaction be to hit them back?",
  ui_story_5082_50821202_39_dialog_content = "No!",
  ui_story_5082_50821202_40_dialog_content = "Your data is still being stored here! If we fight back right now—",
  ui_story_5082_50821202_41_dialog_content = "There's nothing more pointless than being indecisive in battle.",
  ui_story_5082_50821202_42_dialog_content = "If you have a way to win, then use it.",
  ui_story_5082_50821202_43_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5082_50821202_44_dialog_content = "Renegade!",
  ui_story_5082_50821202_45_dialog_content = "... Damn it!",
  ui_story_5082_50821202_46_dialog_content = "<color=#e8d9bb>Scorching flames rise up once again.</color>",
  ui_story_5082_50821202_47_dialog_content = "<color=#e8d9bb>Although the blaze is simply a representation of Spearhead's data being destroyed within a mind space, its flames are more dazzling than those of a real fire.</color>",
  ui_story_5082_50821202_48_dialog_content = "<color=#e8d9bb>Like an unstoppable tyrant, she wields the power of fire to consume everything in her path.</color>",
  ui_story_5082_50821202_49_dialog_content = "Have you gone mad?! Your existence is but a string of code within my system! Without a physical body, you'll disappear!",
  ui_story_5082_50821202_50_dialog_content = "But we'll also win. Your body was destroyed a long time ago, and your mind could never keep up with me.",
  ui_story_5082_50821202_51_dialog_content = "You truly #%%^$&... Lost your mind￥%#......%......%！",
  ui_story_5082_50821202_52_dialog_content = "Hahahaha! Sorry Spearhead, but we win.",
  ui_story_5082_50821202_53_dialog_content = "#%%^$&......!!!",
  ui_story_5082_50821202_54_dialog_content = "I know we don't have much time left, PlayerName, but could you lend me your power one last time?",
  ui_story_5082_50821202_55_dialog_content = "Before I go, I'd like to get to know the other me a little better.",
  ui_story_5082_50821202_56_dialog_content = "Sure!",
  ui_story_5082_50821202_57_dialog_content = "No wait, that's not right.",
  ui_story_5082_50821202_58_dialog_content = "<color=#e8d9bb>Renegade walks right up to Reinhardt. From this distance, their reflections can be seen in each other's eyes.</color>",
  ui_story_5082_50821202_59_dialog_content = "I think there's a better way for us to understand each other.",
  ui_story_5082_50821202_60_dialog_content = "...",
  ui_story_5082_50821202_61_dialog_content = "Remember that year you went for the check-up to get into the academy?",
  ui_story_5082_50821202_62_dialog_content = "That was when we first met.",
  ui_story_5082_50821202_63_dialog_content = "Everyone else had already gone home after their exams.",
  ui_story_5082_50821202_64_dialog_content = "But the doctor asked me to stay.",
  ui_story_5082_50821202_65_dialog_content = "What's the matter?",
  ui_story_5082_50821202_66_dialog_content = "I don't know.",
  ui_story_5082_50821202_67_dialog_content = "But... I get fevers all the time, so maybe there's something wrong with me?",
  ui_story_5082_50821202_68_dialog_content = "I hope it doesn't keep me from entering the academy.",
  ui_story_5082_50821202_69_dialog_content = "It won't.",
  ui_story_5082_50821202_70_dialog_content = "... How do you know that?",
  ui_story_5082_50821202_71_dialog_content = "Because I can see it.",
  ui_story_5082_50821202_72_dialog_content = "?",
  ui_story_5082_50821202_73_dialog_content = "You're not sick or anything. The source of your fevers—",
  ui_story_5082_50821202_74_dialog_content = "Is the crimson dragon burning at your back.",
  ui_story_5082_50821301_1_dialog_content = "<color=#e8d9bb>Live-fire Drill</color>",
  ui_story_5082_50821301_2_dialog_content = "Tell me, what hurts more right now? Your wounds or your hunger?",
  ui_story_5082_50821301_3_dialog_content = "Shut up.",
  ui_story_5082_50821301_4_dialog_content = "Oh, I see. You can barely stand right now, can't you? Poor thing.",
  ui_story_5082_50821301_5_dialog_content = "I said shut up!",
  ui_story_5082_50821301_6_dialog_content = "Is this really all you can take?",
  ui_story_5082_50821301_7_dialog_content = "If you lose this disgracefully in battle, getting ridiculed will be the least of your problems.",
  ui_story_5082_50821301_8_dialog_content = "I won't make the same mistake ever again.",
  ui_story_5082_50821301_9_dialog_content = "Oh really? Because I think your skills are flawed at their most fundamental level.",
  ui_story_5082_50821301_10_dialog_content = "If I could fool you like this, what makes you think you stand a chance in a real battle against real Eclipsites? They're a thousand times more merciless than me, I promise.",
  ui_story_5082_50821301_11_dialog_content = "If Aurorians could use textbook knowledge to defeat them, we would've won the war long ago.",
  ui_story_5082_50821301_12_dialog_content = "That line of thinking just leads to a dead end.",
  ui_story_5082_50821301_13_dialog_content = "So if you want to survive and realize your ambitions, then you'll need to be stronger. Stronger than the strongest Aurorians in the world.",
  ui_story_5082_50821301_14_dialog_content = "And you'll need to be more cunning than the most evil Eclipsites in the eternal night.",
  ui_story_5082_50821301_15_dialog_content = "Only when you reach the most unimaginable of heights will you be able to deliver the final blow.",
  ui_story_5082_50821301_16_dialog_content = "Do you understand?",
  ui_story_5082_50821301_17_dialog_content = "<color=#e8d9bb>Military Academy Training Grounds</color>",
  ui_story_5082_50821301_18_dialog_content = "Today's training is over, now return to your barracks! Curfew's in effect, so no going outside after dark!",
  ui_story_5082_50821301_19_dialog_content = "Shhh! Come see what's happening at the academy's gates, and don't let the instructor see you!",
  ui_story_5082_50821301_20_dialog_content = "It's the 1st Legion... What are they doing at the academy?",
  ui_story_5082_50821301_21_dialog_content = "And why are they leaving with our weapon stores?",
  ui_story_5082_50821301_22_dialog_content = "Lots of officers have been coming and going since earlier this afternoon.",
  ui_story_5082_50821301_23_dialog_content = "They're gathering a large amount of resources and equipment. Even some of the academy's strongest instructors have yet to come back after leaving with them.",
  ui_story_5082_50821301_24_dialog_content = "If my hunch is correct, there's going to be a battle in Gannon City tonight.",
  ui_story_5082_50821301_25_dialog_content = "...",
  ui_story_5082_50821301_26_dialog_content = "I saw a defense map in the office a while ago.",
  ui_story_5082_50821301_27_dialog_content = "There's a poorly guarded area just west of the city's gates. It won't last if it comes under attack.",
  ui_story_5082_50821301_28_dialog_content = "It's the perfect place for us to show the Federation what we can do!",
  ui_story_5082_50821301_29_dialog_content = "I'm going, but not for that sort of reason.",
  ui_story_5082_50821301_30_dialog_content = "As a soldier of Illumina, my orders are to protect our people at all costs.",
  ui_story_5082_50821301_31_dialog_content = "<color=#e8d9bb>Spec-Ops Room 3</color>",
  ui_story_5082_50821301_32_dialog_content = "Roar!",
  ui_story_5082_50821301_33_dialog_content = "Urgh...",
  ui_story_5082_50821301_34_dialog_content = "(My mind's... Getting hazy...)",
  ui_story_5082_50821301_35_dialog_content = "Subject's heart rate and blood pressure are dropping, and her breathing is becoming irregular–",
  ui_story_5082_50821301_36_dialog_content = "(How could I let myself die in a stupid experiment like this...?)",
  ui_story_5082_50821301_37_dialog_content = "<color=#e8d9bb>Beep—</color>",
  ui_story_5082_50821301_38_dialog_content = "Vital signs are no longer detected. The subject's death is now confirmed.",
  ui_story_5082_50821301_39_dialog_content = "...",
  ui_story_5082_50821301_40_dialog_content = "—!",
  ui_story_5082_50821301_41_dialog_content = "What do you think you're doing?!",
  ui_story_5082_50821301_42_dialog_content = "It's not your time to die yet!",
  ui_story_5082_50821301_43_dialog_content = "Open your eyes already! Those heartless scientists are just watching all of this happen, muttering to themselves without a hint of remorse!",
  ui_story_5082_50821301_44_dialog_content = "They're treating you like a tool for their convenience! Compared to the data they're after, your life doesn't amount to anything!",
  ui_story_5082_50821301_45_dialog_content = "If you don't want to die such a meaningless death, then get up right now!",
  ui_story_5082_50821301_46_dialog_content = "<color=#e8d9bb>... Beep! Beep... Beep... Beep...</color>",
  ui_story_5082_50821301_47_dialog_content = "... She's still alive?",
  ui_story_5082_50821301_48_dialog_content = "Ugh...",
  ui_story_5082_50821301_49_dialog_content = "They really raised the difficulty for this so-called \"explosive strength\" training.",
  ui_story_5082_50821301_50_dialog_content = "But at least... It's finally over.",
  ui_story_5082_50821301_51_dialog_content = "Interesting. Her vital signs had completely disappeared just now, and yet she was able to regain consciousness and continue fighting...",
  ui_story_5082_50821301_52_dialog_content = "You saw that, right?",
  ui_story_5082_50821301_53_dialog_content = "That jerk looks even more disappointed now than when she thought you were dead.",
  ui_story_5082_50821301_54_dialog_content = "So don't die so easily ever again.",
  ui_story_5082_50821301_55_dialog_content = "(I won't...)",
  ui_story_5082_50821301_56_dialog_content = "<color=#e8d9bb>Secret Laboratory</color>",
  ui_story_5082_50821301_57_dialog_content = "You're always telling us to be more honest with you, and yet you never tell us when something's wrong with you.",
  ui_story_5082_50821301_58_dialog_content = "... Is it that obvious?",
  ui_story_5082_50821301_59_dialog_content = "Helios sees it too. He just doesn't say anything because he doesn't want to bother you.",
  ui_story_5082_50821301_60_dialog_content = "But I'm not as considerate as he is, which is why I'm asking you right now.",
  ui_story_5082_50821301_61_dialog_content = "What the hell is happening, Reinhardt?",
  ui_story_5082_50821301_62_dialog_content = "What kind of tests are they putting you through that you keep showing up with wounds all over your body?",
  ui_story_5082_50821301_63_dialog_content = "You're the strongest person among your peers, hands down. So why are they doing this to you?",
  ui_story_5082_50821301_64_dialog_content = "...",
  ui_story_5082_50821301_65_dialog_content = "Because even though you're strong, you have a tendency to go rogue when they need you to follow orders.",
  ui_story_5082_50821301_66_dialog_content = "They wanted to dull your edge, crush your pride, and turn you into a good little soldier like everyone else.",
  ui_story_5082_50821301_67_dialog_content = "But you didn't give them what they wanted, and now they're afraid of you. They have no use for a blade that cuts its wielder.",
  ui_story_5082_50821301_68_dialog_content = "If you don't want to be tossed into the furnace, to be reshaped at their whim, you must stand firm. Remember who you are, and keep hanging on.",
  ui_story_5082_50821301_69_dialog_content = "I still haven't grasped the entire situation yet.",
  ui_story_5082_50821301_70_dialog_content = "So can we hold off on answering that question, Denier? I promise I'll tell you everything once I know the truth.",
  ui_story_5082_50821301_71_dialog_content = "Well, it is a breach of scientific conduct to pry into other people's confidential matters without permission.",
  ui_story_5082_50821301_72_dialog_content = "But if something happens to you, then I'm throwing those scruples out the window regardless of whoever holds me accountable.",
  ui_story_5082_50821301_73_dialog_content = "I promise I'll be careful.",
  ui_story_5082_50821301_74_dialog_content = "(The same goes for you two.)",
  ui_story_5082_50821301_75_dialog_content = "<color=#e8d9bb>???</color>",
  ui_story_5082_50821301_76_dialog_content = "Where am I...?",
  ui_story_5082_50821301_77_dialog_content = "What am I doing...?",
  ui_story_5082_50821301_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_79_dialog_content = "!",
  ui_story_5082_50821301_80_dialog_content = "Roooaaar!",
  ui_story_5082_50821301_81_dialog_content = "I have to... Fight the Eclipsites...!",
  ui_story_5082_50821301_82_dialog_content = "Graaah—",
  ui_story_5082_50821301_83_dialog_content = "Fight...",
  ui_story_5082_50821301_84_dialog_content = "Roar!",
  ui_story_5082_50821301_85_dialog_content = "Fight!",
  ui_story_5082_50821301_86_dialog_content = "It's not over yet...",
  ui_story_5082_50821301_87_dialog_content = "I have to keep going—!",
  ui_story_5082_50821301_88_dialog_content = "Wake up!",
  ui_story_5082_50821301_89_dialog_content = "Snap out of it! Don't let them turn you into another tool at their disposal!",
  ui_story_5082_50821301_90_dialog_content = "... I know.",
  ui_story_5082_50821301_91_dialog_content = "It's just a bad reflex that I haven't gotten rid of yet. I won't let this sort of thing control me.",
  ui_story_5082_50821301_92_dialog_content = "But what am I doing here?",
  ui_story_5082_50821301_93_dialog_content = "Wait, what time is it?! The plan...",
  ui_story_5082_50821301_94_dialog_content = "Today's the day they're going to use that little girl to activate the Colossus.",
  ui_story_5082_50821301_95_dialog_content = "I have to stick to the plan—Nngh!",
  ui_story_5082_50821301_96_dialog_content = "The numbing agent hasn't finished running its course, so quit your babbling.",
  ui_story_5082_50821301_97_dialog_content = "After all, it's obvious that someone found out about our plan.",
  ui_story_5082_50821301_98_dialog_content = "... Where are the others?",
  ui_story_5082_50821301_99_dialog_content = "What do I look like, an Illumina surveillance system? I can only keep watch over you.",
  ui_story_5082_50821301_100_dialog_content = "We're still close to the base. Your daily training makes it easy for them to keep track of you, but your friends still have some time.",
  ui_story_5082_50821301_101_dialog_content = "If you want to check on them, your only choice is to escape.",
  ui_story_5082_50821301_102_dialog_content = "Now hurry! Once those researchers get here, it'll be too late.",
  ui_story_5082_50821301_103_dialog_content = "...",
  ui_story_5082_50821301_104_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5082_50821301_105_dialog_content = "Oh? Awake already, I see. It seems your body has gotten much stronger recently.",
  ui_story_5082_50821301_106_dialog_content = "Go ahead and lay back down. We'll be injecting you with your next treatment soon.",
  ui_story_5082_50821301_107_dialog_content = "... Excuse me, but the treatments I've been getting lately...",
  ui_story_5082_50821301_108_dialog_content = "Suppressant #05... Round 13 of treatment...",
  ui_story_5082_50821301_109_dialog_content = "What's with that pathetic look on your face?! She has a gun, so take it and kill her! That'll be our chance to escape!",
  ui_story_5082_50821301_110_dialog_content = "<color=#e8d9bb>Reinhardt stands up and grabs the researcher by the arm, but is immediately stunned by an overwhelming sense of dizziness.</color>",
  ui_story_5082_50821301_111_dialog_content = "<color=#e8d9bb>The two researchers approach her. While one of them subdues Reinhardt, the other holds the injector aloft...</color>",
  ui_story_5082_50821301_112_dialog_content = "(No—!)",
  ui_story_5082_50821301_113_dialog_content = "<color=#e8d9bb>A large volume of suppressant is injected into Renegade's body.</color>",
  ui_story_5082_50821301_114_dialog_content = "You...",
  ui_story_5082_50821301_115_dialog_content = "Run!",
  ui_story_5082_50821301_116_dialog_content = "Don't let them steal your power! Now run—!!",
  ui_story_5082_50821301_117_dialog_content = "<color=#e8d9bb>Reinhardt clenches her teeth as she scrambles out of the door.</color>",
  ui_story_5082_50821301_118_dialog_content = "Huff... Huff...",
  ui_story_5082_50821301_119_dialog_content = "My body... It's burning up...",
  ui_story_5082_50821301_120_dialog_content = "(And my mind... Why is it...)",
  ui_story_5082_50821301_121_dialog_content = "(No, this isn't right... I'm not on the training grounds, but I'm...)",
  ui_story_5082_50821301_122_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5082_50821301_123_dialog_content = "!",
  ui_story_5082_50821301_124_dialog_content = "Don't stop!",
  ui_story_5082_50821301_125_dialog_content = "It's you! Are you alright?!",
  ui_story_5082_50821301_126_dialog_content = "Stop talking and run!",
  ui_story_5082_50821301_127_dialog_content = "... Alright.",
  ui_story_5082_50821301_128_dialog_content = "There's no going back for us now. We'll have to keep going deeper.",
  ui_story_5082_50821301_129_dialog_content = "Helios marked the room where they're keeping the Colossus on his map. It's at the other end of the research base, and it's close to the outside.",
  ui_story_5082_50821301_130_dialog_content = "We can look for a way out from there, and then find another Undercity—",
  ui_story_5082_50821301_131_dialog_content = "\"Plan B\"...",
  ui_story_5082_50821301_132_dialog_content = "Bet you regret not listening to Denier or giving her plan more thought, huh?",
  ui_story_5082_50821301_133_dialog_content = "I blame myself more than anything else.",
  ui_story_5082_50821301_134_dialog_content = "This is all because of my ignorance and pride.",
  ui_story_5082_50821301_135_dialog_content = "My ignorance led me to blindly follow orders...",
  ui_story_5082_50821301_136_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_137_dialog_content = "Reinhardt, reporting for duty.",
  ui_story_5082_50821301_138_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_139_dialog_content = "Sorry, I'm a little tired so I'm going straight to bed.",
  ui_story_5082_50821301_140_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_141_dialog_content = "...",
  ui_story_5082_50821301_142_dialog_content = "And my pride fooled me into thinking I could achieve my dreams someday as long as I put up with it.",
  ui_story_5082_50821301_143_dialog_content = "The Eclipsites you're currently facing are the weakest specimens in the experiment.",
  ui_story_5082_50821301_144_dialog_content = "This training is designed to forge you into Illumina's most powerful soldier. If you're unable to defeat them, we'll have to reconsider your candidacy for the program.",
  ui_story_5082_50821301_145_dialog_content = "Heh... Who said I couldn't defeat them?!",
  ui_story_5082_50821301_146_dialog_content = "Let's go again!",
  ui_story_5082_50821301_147_dialog_content = "It turns out that when people are trapped in a web, their so-called \"struggles\" do nothing but strangle them all the sooner.",
  ui_story_5082_50821301_148_dialog_content = "Stow that kind of talk! This isn't the time or place for your self-pity!",
  ui_story_5082_50821301_149_dialog_content = "Dreams don't have to be impossible to achieve, you know.",
  ui_story_5082_50821301_150_dialog_content = "?",
  ui_story_5082_50821301_151_dialog_content = "I can't stand following a routine, and I hate the feeling of going through life as though I'm reading from a script.",
  ui_story_5082_50821301_152_dialog_content = "If they keep trying to fit me into a box, then I'll keep breaking out of it, even if I have to burn it to ashes.",
  ui_story_5082_50821301_153_dialog_content = "But you're different.",
  ui_story_5082_50821301_154_dialog_content = "Even though everyone admires you and praises your strength and intelligence, you're just as foolish as anyone else.",
  ui_story_5082_50821301_155_dialog_content = "Stubborn, stoic, intolerant of failure, and unwilling to budge even when you hit a wall.",
  ui_story_5082_50821301_156_dialog_content = "I told you so many times that those tests were meant to kill you, not make you stronger.",
  ui_story_5082_50821301_157_dialog_content = "But you never listened, and that's why we ended up in this mess.",
  ui_story_5082_50821301_158_dialog_content = "I...",
  ui_story_5082_50821301_159_dialog_content = "But it's because you never listened",
  ui_story_5082_50821301_160_dialog_content = "...that you've honed yourself into the sharpest and most brilliant blade in Illumina.",
  ui_story_5082_50821301_161_dialog_content = "That's why those bastards will do anything to control you, even if it means endangering themselves.",
  ui_story_5082_50821301_162_dialog_content = "They're cowards, but their greed overpowers their fear. They want to trim your branches until you become their perfect soldier.",
  ui_story_5082_50821301_163_dialog_content = "And I happen to be the branch they most want to trim.",
  ui_story_5082_50821301_164_dialog_content = "That's enough! I don't need to hear the rest.",
  ui_story_5082_50821301_165_dialog_content = "I know you think I'm stubborn, but that just means I'll never give up on the things that matter most to me.",
  ui_story_5082_50821301_166_dialog_content = "Haha, this might be the first time I've heard you admit this to yourself.",
  ui_story_5082_50821301_167_dialog_content = "Unfortunately for you, I'm still not the type to follow other people's orders.",
  ui_story_5082_50821301_168_dialog_content = "The reason all those suppressant treatments couldn't make me disappear is because I didn't let them.",
  ui_story_5082_50821301_169_dialog_content = "But now that you want me to stay, I've decided to change my mind.",
  ui_story_5082_50821301_170_dialog_content = "As long as I leave, your chance to become Grand Marshal will not be taken away.",
  ui_story_5082_50821301_171_dialog_content = "Don't say that! I wouldn't be the same person if it wasn't for you!",
  ui_story_5082_50821301_172_dialog_content = "<color=#e8d9bb>Beep-beep-beep-beep-beep!!!!</color>",
  ui_story_5082_50821301_173_dialog_content = "An alarm?",
  ui_story_5082_50821301_174_dialog_content = "The Colossus activation site is just up ahead. Something must have gone wrong.",
  ui_story_5082_50821301_175_dialog_content = "—!",
  ui_story_5082_50821301_176_dialog_content = "This scream... It's that girl calling for help!",
  ui_story_5082_50821301_177_dialog_content = "Hey!",
  ui_story_5082_50821301_178_dialog_content = "<color=#e8d9bb>Control Room</color>",
  ui_story_5082_50821301_179_dialog_content = "<color=#e8d9bb>Beep-beep-beep-beep—</color>",
  ui_story_5082_50821301_180_dialog_content = "... Her compatibility decreasing?",
  ui_story_5082_50821301_181_dialog_content = "Has something gone wrong, Tech Officer?",
  ui_story_5082_50821301_182_dialog_content = "The actual <color=#FFB400>parameters</color> for the Reserve Navigator are different from those in the report. Has anyone seen the test subject in person?",
  ui_story_5082_50821301_183_dialog_content = "No, ma'am... The Committee won't allow it, but I know I read the parameters in the report—",
  ui_story_5082_50821301_184_dialog_content = "It doesn't matter now! The Colossus is about to lose control—",
  ui_story_5082_50821301_185_dialog_content = "T-Tech Officer! Where are you going?!",
  ui_story_5082_50821301_X185_dialog_content = "I need to be there now! The subject is in danger!",
  ui_story_5082_50821301_186_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5082_50821301_187_dialog_content = "<color=#e8d9bb>—!</color>",
  ui_story_5082_50821301_188_dialog_content = "All personnel, evacuate immediately! All personnel, evacuate immediately!",
  ui_story_5082_50821301_189_dialog_content = "... Th-The Colossus has gone berserk!",
  ui_story_5082_50821301_190_dialog_content = "Adjusting the parameters isn't doing anything anymore!",
  ui_story_5082_50821301_191_dialog_content = "At this rate, the girl inside the piloting room...",
  ui_story_5082_50821301_192_dialog_content = "Pulling the pilot out of there right now will only make things worse.",
  ui_story_5082_50821301_193_dialog_content = "This mess is in the Tech Officer's hands now, not ours. I'm sure the Committee will figure something out.",
  ui_story_5082_50821301_194_dialog_content = "What's more, the only way we can obtain the data we need for future activation attempts is by keeping that child in there.",
  ui_story_5082_50821301_195_dialog_content = "...",
  ui_story_5082_50821301_196_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5082_50821301_197_dialog_content = "Look down there... What happened to this place?",
  ui_story_5082_50821301_198_dialog_content = "...",
  ui_story_5082_50821301_199_dialog_content = "Stop! I know what you're thinking, but you narrowly avoided death just now!",
  ui_story_5082_50821301_200_dialog_content = "If you go down there in your current state, you can forget about becoming Grand Marshal, or anything else for that matter!",
  ui_story_5082_50821301_201_dialog_content = "If I just stand by and watch that poor little girl die, then I don't deserve to become Grand Marshal either.",
  ui_story_5082_50821301_202_dialog_content = "I wanted to tell you something before. I know you've always shown yourself to me this way...",
  ui_story_5082_50821301_203_dialog_content = "But in the end, we'll always be the same person.",
  ui_story_5082_50821301_204_dialog_content = "So stop looking at me like I'm such a disappointment! Even I—",
  ui_story_5082_50821301_205_dialog_content = "Can have my rebellious moments!",
  ui_story_5082_50821301_206_dialog_content = "They said my dream of becoming Grand Marshal was like a bottomless pit, one that constantly lured me in and sucked away my spirit...",
  ui_story_5082_50821301_207_dialog_content = "A dream that would consume me and eventually kill me.",
  ui_story_5082_50821301_208_dialog_content = "But the Grand Marshal I aspire to be doesn't care about status or glory.",
  ui_story_5082_50821301_209_dialog_content = "All she needs is the strength and authority to protect the hurt and the suffering under her watch.",
  ui_story_5082_50821301_210_dialog_content = "That's why it doesn't matter if Illumina accepts me or not.",
  ui_story_5082_50821301_211_dialog_content = "At the very least, I'm going to be that little girl's Grand Marshal!!!",
  ui_story_5082_50821301_212_dialog_content = "When we first met, you said there was a burning dragon at my back.",
  ui_story_5082_50821301_213_dialog_content = "I still don't fully understand what you meant by that, but if I have the power to become fire...",
  ui_story_5082_50821301_214_dialog_content = "Then let me be the fire that burns away this rotten status quo!",
  ui_story_5082_50821301_215_dialog_content = "...",
  ui_story_5082_50821301_216_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5082_50821301_217_dialog_content = "(I can still hear her voice! She's somewhere inside the Colossus!)",
  ui_story_5082_50821301_218_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5082_50821301_219_dialog_content = "(But if I don't deal with its tail first— Huh?!)",
  ui_story_5082_50821301_220_dialog_content = "(The suppressant they injected into me... Is it also suppressing my Luminatics?!)",
  ui_story_5082_50821301_221_dialog_content = "You really are a fool...",
  ui_story_5082_50821301_222_dialog_content = "They called me your alter-ego and said that I'm the rebellious side of your otherwise obedient persona.",
  ui_story_5082_50821301_223_dialog_content = "They tried to get rid of me so that only your \"useful\" side remained.",
  ui_story_5082_50821301_224_dialog_content = "But for all their so-called intelligence, they never saw us for who we truly are.",
  ui_story_5082_50821301_225_dialog_content = "Rebellion and obedience are just two different types of firewood. With the right amount of heat—",
  ui_story_5082_50821301_226_dialog_content = "Both will ignite and become an unstoppable fireball!",
  ui_story_5082_50821301_227_dialog_content = "Hey! Reinhardt!",
  ui_story_5082_50821301_228_dialog_content = "<color=#e8d9bb>The crimson-red hem of her clothing flutters in the heat of battle.</color>",
  ui_story_5082_50821301_229_dialog_content = "<color=#e8d9bb>With a wanton and defiant smile, she turns and gazes at her other self from afar.</color>",
  ui_story_5082_50821301_230_dialog_content = "My power's in your hands now. Use it well!",
  ui_story_5082_50821301_231_dialog_content = "<color=#e8d9bb>Boom—!!!</color>",
  ui_story_5082_50821301_232_dialog_content = "<color=#e8d9bb>A wave of Lumina surges through the dancing flames.</color>",
  ui_story_5082_50821301_233_dialog_content = "<color=#e8d9bb>Shining particles scatter throughout the blazing heat, and begin to converge in the very next instant...</color>",
  ui_story_5082_50821301_234_dialog_content = "<color=#e8d9bb>An enormous dragon of pure flame encircles Reinhardt as it pierces the Colossus' tail.</color>",
  ui_story_5082_50821301_235_dialog_content = "<color=#e8d9bb>Renegade disappears with a bang, but her laughter and burning gaze linger.</color>",
  ui_story_5082_50821301_236_dialog_content = "Burn it all to your heart's content!",
  ui_story_5082_50821301_237_dialog_content = "Never let any of them steal your power!",
  ui_story_5082_50821301_238_dialog_content = "Of course!",
  ui_story_5082_50821301_239_dialog_content = "Illuminated Finale—!!",
  ui_story_5082_50821400_1_dialog_content = "Are we outside again?",
  ui_story_5082_50821400_2_dialog_content = "Ah! But what about Spearhead and the other Reinhardt?!",
  ui_story_5082_50821400_3_dialog_content = "That big fella got turned into a pile of scrap a long time ago.",
  ui_story_5082_50821400_4_dialog_content = "It could only fight us with a single tail. The rest of its body was completely out of commission.",
  ui_story_5082_50821400_5_dialog_content = "If that thing could still move around, we should all be questioning ourselves!",
  ui_story_5082_50821400_6_dialog_content = "As for Reinhardt, isn't that her over there?",
  ui_story_5082_50821400_7_dialog_content = "No, I'm not talking about...",
  ui_story_5082_50821400_8_dialog_content = "<color=#e8d9bb>Reinhardt walks over silently. In her hands is the machine that had tied so many people's destinies together.</color>",
  ui_story_5082_50821400_9_dialog_content = "... She's not here anymore, is she?",
  ui_story_5082_50821400_10_dialog_content = "No, but she won. She always wins, even against the current me.",
  ui_story_5082_50821400_11_dialog_content = "Uh... What exactly happened there?",
  ui_story_5082_50821400_12_dialog_content = "Maybe it was just my luck...",
  ui_story_5082_50821400_13_dialog_content = "According to the normal procedure, she should have disappeared from my life after my fever subsided back then.",
  ui_story_5082_50821400_14_dialog_content = "But she never disappeared at all...",
  ui_story_5082_50821400_15_dialog_content = "They managed to kill me, but they didn't manage to destroy us.",
  ui_story_5082_50821400_16_dialog_content = "...",
  ui_story_5082_50821400_17_dialog_content = "<color=#e8d9bb>Bzzt, bzzt—</color>",
  ui_story_5082_50821400_18_dialog_content = "(It's Spearhead...)",
  ui_story_5082_50821400_19_dialog_content = "Die... All of you...",
  ui_story_5082_50821400_20_dialog_content = "You still haven't accepted defeat?",
  ui_story_5082_50821400_21_dialog_content = "Your attitude disgusts me, Caelestite.",
  ui_story_5082_50821400_22_dialog_content = "I have no reason to be amicable towards one who has deceived me and harmed my allies.",
  ui_story_5082_50821400_23_dialog_content = "Aurorians have no way of receiving my power.",
  ui_story_5082_50821400_24_dialog_content = "It was their hunger for that power, which never belonged to them, that led to their ultimate demise.",
  ui_story_5082_50821400_25_dialog_content = "But she and that little girl were different...",
  ui_story_5082_50821400_26_dialog_content = "Their powers were greater than that of any other Aurorians, and so I was forced to pay a price as well.",
  ui_story_5082_50821400_27_dialog_content = "Power comparable to Reinhardt's...",
  ui_story_5082_50821400_28_dialog_content = "What kind of power was hidden inside the four-year-old Vice?",
  ui_story_5082_50821400_29_dialog_content = "The power to pilot me...",
  ui_story_5082_50821400_30_dialog_content = "... Pilot you?",
  ui_story_5082_50821400_31_dialog_content = "My last crash-landing took away my wings.",
  ui_story_5082_50821400_32_dialog_content = "And my last battle took away my body.",
  ui_story_5082_50821400_33_dialog_content = "Nothing remains of my former self. I cannot accomplish anything in my current state.",
  ui_story_5082_50821400_34_dialog_content = "Just because I sympathize with you doesn't mean I can forgive you for the things you've done in the past.",
  ui_story_5082_50821400_35_dialog_content = "However, I can deliver a message in your place.",
  ui_story_5082_50821400_36_dialog_content = "You must know a lot about the Eclipsites, right? In exchange for that information, Illumina might be willing to construct a new body for you.",
  ui_story_5082_50821400_37_dialog_content = "... You wish to command me? Compared to my previous Navigator, you are not nearly worthy.",
  ui_story_5082_50821400_38_dialog_content = "Was your previous Navigator... a Caelestite too?",
  ui_story_5082_50821400_39_dialog_content = "Hmph, traitor.",
  ui_story_5082_50821400_40_dialog_content = "No! We're not traitors. Those two girls and I follow our own paths now. We're true to ourselves!",
  ui_story_5082_50821400_41_dialog_content = "Yourselves?",
  ui_story_5082_50821400_42_dialog_content = "Hmm. I am no longer certain of who I am myself.",
  ui_story_5082_50821400_43_dialog_content = "Well whoever you are, you're not allowed to hurt any more people, no matter your reasons.",
  ui_story_5082_50821400_44_dialog_content = "Say what you will, but I still have no reason to obey you.",
  ui_story_5082_50821400_45_dialog_content = "%$^#$^%^!......",
  ui_story_5082_50821400_46_dialog_content = "...",
  ui_story_5082_50821400_47_dialog_content = "So the other Grand Marshal and Yumi... They're not the same, right? Makes sense, since only the Grand Marshal can see her...",
  ui_story_5082_50821400_48_dialog_content = "Wait...",
  ui_story_5082_50821400_49_dialog_content = "Vice, a four-year-old girl, and Reinhardt, the rising star of the Federation at the time... Both were involved in those experiments...",
  ui_story_5082_50821400_50_dialog_content = "So why wasn't I aware of it...?",
  ui_story_5082_50821400_51_dialog_content = "G-Give me a second! I... I need to sort a few things out...",
  ui_story_5082_50821400_52_dialog_content = "I know that Tech Officer Gronru was appointed to her position during the Darkover Crisis, and her first order of business was to activate the Colossus.",
  ui_story_5082_50821400_53_dialog_content = "I tried asking her about it once... I was even discreet about it!",
  ui_story_5082_50821400_54_dialog_content = "But she just kept ignoring me and typing the word \"parameters\" over and over again on her computer...",
  ui_story_5082_50821400_55_dialog_content = "Well, it looks like I've found more or less the information I was looking for!",
  ui_story_5082_50821400_56_dialog_content = "Aside from Gronru... many other researchers involved were also seriously injured.",
  ui_story_5082_50821400_57_dialog_content = "I don't even want to think about what would have happened if the Grand Marshal hadn't saved Vice back then...",
  ui_story_5082_50821400_58_dialog_content = "Saving Vice was nothing compared to what I once intended to do. It was like the curtain call for the fallen.",
  ui_story_5082_50821400_59_dialog_content = "I didn't know who Vice was at the time. All I wanted to do was become her Grand Marshal at that moment.",
  ui_story_5082_50821400_60_dialog_content = "...",
  ui_story_5082_50821400_61_dialog_content = "In your eyes, the Grand Marshal is someone with \"the strength and authority to protect the hurt and suffering under her watch.\"",
  ui_story_5082_50821400_62_dialog_content = "Doesn't that make you the only person fit for the job, Reinhardt?",
  ui_story_5082_50821400_63_dialog_content = "But this strength is the very brand imprinted upon us by those we were so determined to rebel against.",
  ui_story_5082_50821400_64_dialog_content = "Back then, I was just a hothead, completely fueled by rage. I didn't understand what it meant to be the Grand Marshal—all I cared about was meting out my own brand of justice and nothing else.",
  ui_story_5082_50821400_65_dialog_content = "As for my authority...",
  ui_story_5082_50821400_66_dialog_content = "I had no idea those experiments would tie our destinies together like this.",
  ui_story_5082_50821400_67_dialog_content = "Helios, Denier, and myself... We grew surprisingly close to one another.",
  ui_story_5082_50821400_68_dialog_content = "But in the end, we had to go our separate ways.",
  ui_story_5082_50821400_69_dialog_content = "Helios went through so much suffering. Cologne and Vaughn were sent to the most dangerous battlefronts and were never heard from again.",
  ui_story_5082_50821400_70_dialog_content = "But compared to them, Denier... or rather Forsakin, was the one whose decision aligned most with our original intentions.",
  ui_story_5082_50821400_71_dialog_content = "I watched as each of my closest allies disappeared one by one.",
  ui_story_5082_50821400_72_dialog_content = "And now that they're all gone, I've finally become Grand Marshal of Illumina. That's the irony of my authority.",
  ui_story_5082_50821400_73_dialog_content = "That's not true, Reinhardt.",
  ui_story_5082_50821400_74_dialog_content = "All I see is someone who never gave up on her past ideals.",
  ui_story_5082_50821400_75_dialog_content = "You still protect the weak and defenseless at all costs. That much about you hasn't changed.",
  ui_story_5082_50821400_76_dialog_content = "Even if I'm starting to look more like one of those \"big shots\" from the old days?",
  ui_story_5082_50821400_X76_dialog_content = "The me you see before you now is me who made a compromise for the sake of Illumina. I've strayed from my initial ideals, failing to grant them the illumination they deserved.",
  ui_story_5082_50821400_X77_dialog_content = "Right, you've sacrificed even yourself... that's why you're the Grand Marshal. You've paid your dues... isn't that enough?",
  ui_story_5082_50821400_77_dialog_content = "...",
  ui_story_5082_50821400_78_dialog_content = "Reinhardt, I've been thinking about the old times... I have to admit, it's all a bit hazy now.",
  ui_story_5082_50821400_79_dialog_content = "If I hadn't experienced all of this today, I never would've known... Just how different you are now compared to your teenage self.",
  ui_story_5082_50821400_80_dialog_content = "Powerful, decisive, and inevitably at the heart of every battle.",
  ui_story_5082_50821400_81_dialog_content = "I still remember a time when we didn't have so many responsibilities to bear... The things we had to do, the way things had to end...",
  ui_story_5082_50821400_82_dialog_content = "Even conquering all of Astra was something we thought we could accomplish!",
  ui_story_5082_50821400_83_dialog_content = "... I'm not sure what I'm trying to say, but as the Grand Marshal and our fellow soldier, everything you won up until today was through your own strength.",
  ui_story_5082_50821400_84_dialog_content = "Regardless of whether or not I knew what was happening behind the scenes, I saw your power grow with each passing day...",
  ui_story_5082_50821400_85_dialog_content = "And watched as you led your soldiers into countless battles that would remain engraved in the hearts of Illumina's people for the rest of their lives.",
  ui_story_5082_50821400_86_dialog_content = "So when news of your promotion to Grand Marshal started to spread, every single person in the Federation felt nothing but joy for you.",
  ui_story_5082_50821400_87_dialog_content = "At least in my eyes, the look you give me as Grand Marshal is no different than the look you give me when we fight at each other's side.",
  ui_story_5082_50821400_88_dialog_content = "... You don't think this is all a part of the Committee's plan?",
  ui_story_5082_50821400_89_dialog_content = "When I was promoted to Grand Marshal during the last Darkover Crisis, it seemed as though the Committee had no other choice...",
  ui_story_5082_50821400_90_dialog_content = "But for a cooled-off time bomb like myself, the best way to control me is to leave the detonator in my hands.",
  ui_story_5082_50821400_91_dialog_content = "As far as the scientists on the Committee are concerned, this course of action was entirely appropriate.",
  ui_story_5082_50821400_92_dialog_content = "As was sending Wrath to fight that awful battle in Twilight.",
  ui_story_5082_50821400_93_dialog_content = "Actually, I think the Committee's attempt to destroy someone as powerful as you was their biggest mistake.",
  ui_story_5082_50821400_94_dialog_content = "Even if they refuse to admit it, every soldier in Illumina and even the nobles of Lumopolis saw it...",
  ui_story_5082_50821400_95_dialog_content = "During the Darkover Crisis, you were the only realistic choice to become the next Grand Marshal.",
  ui_story_5082_50821400_96_dialog_content = "If you had half a mind to do it, no one could stop you from overthrowing the Committee and becoming the supreme leader of Illumina.",
  ui_story_5082_50821400_97_dialog_content = "Hahahaha! That might be something Renegade would've done, but I'm a different kind of Grand Marshal, Barton.",
  ui_story_5082_50821400_98_dialog_content = "You're not disappointed in me, are you?",
  ui_story_5082_50821400_99_dialog_content = "Disappointed?",
  ui_story_5082_50821400_100_dialog_content = "Not at all. I've seen everything you've accomplished so far, and I know those experiments didn't turn you into any sort of monster.",
  ui_story_5082_50821400_101_dialog_content = "And after seeing what Forsakin has done in the last few years... Let's just say I'm glad that kind of power is in your hands and not someone else's...",
  ui_story_5082_50821400_102_dialog_content = "I chose you as my Grand Marshal, Reinhardt. My life has been in your hands for a long time now.",
  ui_story_5082_50821400_103_dialog_content = "Disappointed in you? Ha! You know me better than that!",
  ui_story_5082_50821400_104_dialog_content = "Meow... Something tells me Commander Barton is a little upset...",
  ui_story_5082_50821400_105_dialog_content = "That's because I am upset, mostly at myself!",
  ui_story_5082_50821400_106_dialog_content = "The more I think about these things, the worse it all feels to me... My closest ally was going through so much pain, but what did I do about it?",
  ui_story_5082_50821400_107_dialog_content = "I should've asked more questions! I should've... Argh!",
  ui_story_5082_50821400_108_dialog_content = "Barton.",
  ui_story_5082_50821400_109_dialog_content = "Thank you.",
  ui_story_5082_50821400_110_dialog_content = "...",
  ui_story_5082_50821400_111_dialog_content = "Regardless of what kind of Grand Marshal you may be... You're still the Grand Marshal of Illumina!",
  ui_story_5082_50821400_112_dialog_content = "And even a rebellious Grand Marshal can bring about some much-needed change in the Federation, and improve everyone's lives!",
  ui_story_5082_50821400_113_dialog_content = "Yumi loves dried fish as much as I do, which makes her the same as me!",
  ui_story_5082_50821400_114_dialog_content = "And I'll always be grateful that you became our Grand Marshal. In fact, I hope it stays that way forever!",
  ui_story_5082_50821400_115_dialog_content = "Haha, I can't promise anything like that; after all, each new day brings new changes. There may come a day when I'm not the Grand Marshal of Illumina anymore.",
  ui_story_5082_50821400_116_dialog_content = "And it might be just as unexpected as everything that happened here today.",
  ui_story_5082_50821400_117_dialog_content = "Never thought I could even witness how my own destiny changed with such a perspective.",
  ui_story_5082_50821400_118_dialog_content = "I still don't feel as though I've fully mastered the power she gave me back then.",
  ui_story_5082_50821400_119_dialog_content = "But now, I still hold the title of Grand Marshal, so I'll keep doing the things that only I can do.",
  ui_story_5082_50821400_120_dialog_content = "It's the only way I can stop those tragedies from happening again.",
  ui_story_5082_50821400_121_dialog_content = "I'll make our past ideals a reality.",
  ui_story_5082_50821400_122_dialog_content = "Whether it's the Eclipsites or those who seek to hurt our comrades, we still have many long and difficult battles ahead of us.",
  ui_story_5082_50821400_123_dialog_content = "Can I rely on everyone's support to keep Illumina moving in the right direction?",
  ui_story_5082_50821400_124_dialog_content = "We're always at your command, Grand Marshal!",
  ui_story_5082_50821400_125_dialog_content = "Like I always say, you're not allowed to count me out of anything!",
  ui_story_5082_50821400_126_dialog_content = "You're always welcome to ask me for the latest intelligence too, Grand Marshal!",
  ui_story_5082_50821400_127_dialog_content = "Then once we get back, we'll start by investigating the aftermath of that past Colossus experiment.",
  ui_story_5082_50821400_128_dialog_content = "Understood!",
  ui_story_5082_50821400_129_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_5082_50821400_130_dialog_content = "Everyone's already gone back. Why are you still here?",
  ui_story_5082_50821400_131_dialog_content = "I could ask you the same question.",
  ui_story_5082_50821400_132_dialog_content = "You're still thinking about Renegade, aren't you?",
  ui_story_5082_50821400_133_dialog_content = "... I just feel a little sorry, that's all.",
  ui_story_5082_50821400_134_dialog_content = "I didn't expect to see a part of myself die like that.",
  ui_story_5082_50821400_135_dialog_content = "Before she left, Renegade entrusted me with a question for you.",
  ui_story_5082_50821400_136_dialog_content = "?",
  ui_story_5082_50821400_137_dialog_content = "She wanted to know",
  ui_story_5082_50821400_138_dialog_content = "...if you were still angry about everything.",
  ui_story_5082_50821400_139_dialog_content = "...",
  ui_story_5082_50821400_140_dialog_content = "When we first got here, I would always hear her scream each time I sensed her presence.",
  ui_story_5082_50821400_141_dialog_content = "I thought she was screaming out of pain or sadness.",
  ui_story_5082_50821400_142_dialog_content = "But after seeing your memories, I finally understood. She wasn't screaming in pain—",
  ui_story_5082_50821400_143_dialog_content = "She was howling with rage.",
  ui_story_5082_50821400_144_dialog_content = "She was angry, Reinhardt.",
  ui_story_5082_50821400_145_dialog_content = "Angry for every innocent victim of injustice, and for every life that had been treated with cruelty and disdain.",
  ui_story_5082_50821400_146_dialog_content = "That eternal fury was engraved in her heart and in the deepest depths of her consciousness.",
  ui_story_5082_50821400_147_dialog_content = "She was a renegade born from the fires of anger.",
  ui_story_5082_50821400_148_dialog_content = "You should give her an answer.",
  ui_story_5082_50821400_149_dialog_content = "I don't think she'll like my answer, to be honest.",
  ui_story_5082_50821400_150_dialog_content = "And that's because I'm the Grand Marshal of Illumina now.",
  ui_story_5082_50821400_151_dialog_content = "I once heard someone say that the Grand Marshal is like a flame.",
  ui_story_5082_50821400_152_dialog_content = "One that is ignited and fueled by the bodies of fallen soldiers.",
  ui_story_5082_50821400_153_dialog_content = "But a bright and scorching flame won't burn for long when it's covered.",
  ui_story_5082_50821400_154_dialog_content = "The fire within a single person will never be bright enough or powerful enough to illuminate the eternal night.",
  ui_story_5082_50821400_155_dialog_content = "That's why I can't let the expectations of countless people stay trapped within the person known as Reinhardt.",
  ui_story_5082_50821400_156_dialog_content = "But above all, I cannot regard myself solely as a savior.",
  ui_story_5082_50821400_157_dialog_content = "A truly brilliant world that shines with the light of illumination... it is a world we shall forge together.",
  ui_story_5082_50821400_158_dialog_content = "That's why I need to sand down a few of my own edges... edges that may still be a little too sharp.",
  ui_story_5082_50821400_159_dialog_content = "And that's why I must bury her here.",
  ui_story_5082_50821400_160_dialog_content = "<color=#e8d9bb>Reinhardt bends down and sets the device on the ground before sprinkling some dirt on it.</color>",
  ui_story_5082_50821400_161_dialog_content = "<color=#e8d9bb>As though laying someone to rest.</color>",
  ui_story_5082_50821400_162_dialog_content = "After today, it'll really just be me.",
  ui_story_5082_50821400_163_dialog_content = "Goodbye, Reinhardt.",
  ui_story_5082_50821400_164_dialog_content = "I wish we had the chance to talk more before the end.",
  ui_story_5082_50821400_165_dialog_content = "But I'll always remember you. You were the one who made me complete.",
  ui_story_5082_50821400_166_dialog_content = "May I never forget the anger that once fueled me and brought me to this point.",
  ui_story_5082_50821400_167_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5082_50821400_168_dialog_content = "<color=#e8d9bb>Like a final response, the dust on the device is gently blown away.</color>",
  ui_story_5082_50821400_169_dialog_content = "You won't.",
  ui_story_5082_50821400_170_dialog_content = "So you've come, my \"anger.\"",
  ui_story_5082_50821400_171_dialog_content = "And even if you do forget, I'll always be there to remind you.",
  ui_story_5082_50821400_172_dialog_content = "I'm part of your strength now, and no one will ever take that away from you.",
  ui_story_5082_50821400_173_dialog_content = "Have you come to accept what I've become? I've learned to compromise over the years and fallen into the role of the evil dragon you perceived.",
  ui_story_5082_50821400_174_dialog_content = "But you remembering me means you haven't truly forgotten where our anger came from.",
  ui_story_5082_50821400_175_dialog_content = "You were the one who struck me down, yet the very flames that consumed me ended up forging you into what you are now—the illumination we'd all been waiting for.",
  ui_story_5082_50821400_176_dialog_content = "Knowing you're still on the right path, I bear no grievances.",
  ui_story_5082_50821400_177_dialog_content = "I'll always be watching you in your heart... And if you start to lose your way someday—",
  ui_story_5082_50821400_178_dialog_content = "I'll rebel against you.",
  ui_story_5082_50821400_179_dialog_content = "<color=#e8d9bb>Her smile always carries a burning intensity. Seeing it strangely reassures Reinhardt.</color>",
  ui_story_5082_50821400_180_dialog_content = "Now, you're talking!",
  ui_story_5082_50821400_181_dialog_content = "Deal."
}
return config
